import 'package:flutter/material.dart';

/// コラム本文に埋め込む表. 本文中の {{TABLE}} マーカー位置に描画される.
class ArticleTable {
  final List<String> headers;
  final List<List<String>> rows;
  const ArticleTable({required this.headers, required this.rows});

  String get searchText => [...headers, for (final r in rows) ...r].join(' ');
}

/// コラム (解説記事)1本. NutriCalcの「ノート」と同じ構造.
class ColumnArticle {
  final String category;
  final String title;
  final String body;
  final Color color;
  final List<String> tags; // 生理学 / 薬理学 / 術前評価 / モニタリング など横断タグ
  final ArticleTable? table;
  final String? headerArt; // 本文先頭に表示する図のキー (UI側で widget へマップ)
  final List<String> relatedArticleTitles; // 同じ画面内で直接開く関連記事タイトル
  const ColumnArticle({
    required this.category,
    required this.title,
    required this.body,
    required this.color,
    this.tags = const [],
    this.table,
    this.headerArt,
    this.relatedArticleTitles = const [],
  });

  /// 検索対象テキスト (タイトル・本文・カテゴリ・タグ・表)
  String get searchText =>
      '$title $body $category ${tags.join(' ')} ${table?.searchText ?? ''} ${relatedArticleTitles.join(' ')}'
          .toLowerCase();
}

