    color: _cAirway,
    tags: const ['呼吸', '手技'],
    body:
        '■ 適応\n'
        '・口腔内/顎顔面手術 (口腔外科・耳鼻科の口腔咽頭操作)で経口チューブが術野の妨げになる場合. 開口制限例, 経口での気道確保が困難な場合など. \n\n'
        '■ 禁忌・注意\n'
        '・絶対的: 頭蓋底骨折を疑う所見 (LeFort II/III, 篩骨洞/前頭蓋底損傷, 髄液鼻漏, raccoon eyes) → チューブの頭蓋内迷入リスク. \n'
        '・相対的: 著明な鼻出血傾向・抗凝固/抗血小板, 鼻腔閉塞 (鼻ポリープ・鼻中隔彎曲・後鼻孔閉鎖), 副鼻腔炎, 妊娠 (鼻粘膜充血で出血しやすい). \n\n'
