        '・チューブは経口より0.5-1.0mm細め (目安 女性6.5-7.0, 男性7.0-7.5). 経鼻RAEや先端の軟らかいものを選び, 温生食/温水に浸けて軟化させると粘膜損傷が減る. \n'
        '・鼻腔前処置: 血管収縮薬 (ナファゾリン・オキシメタゾリン・フェニレフリン等の点鼻)で粘膜を収縮させ出血予防と通過性を改善. リドカインゼリー/スプレーで潤滑・表面麻酔. \n'
        '・通りの良い鼻腔を選ぶ (左右の通りを患者に確認, または鼻翼を押して観察). 必要なら経鼻エアウェイで事前に拡張. \n\n'
        '■ 手技の流れ\n'
        '1. 前処置 (血管収縮+潤滑)後, 軟化させたチューブにゼリーを塗る. \n'
        '2. チューブを顔面に垂直 (鼻腔底に沿って後方へ)に進める. 下鼻甲介を避け鼻腔底に沿わせ, 上向きに押し込まない (鼻甲介・篩板損傷). \n'
        '3. 抵抗があれば無理せず, 軽く回転させるか反対の鼻腔へ. 後鼻孔を越えて咽頭まで進める. \n'
        '4. 喉頭鏡で喉頭を展開し, Magill鉗子でチューブ先端を声門へ誘導する. カフを傷つけないようカフより手前を把持し, 助手にチューブを押し進めてもらう. \n'
        '5. 挿管困難が予想される/確実性を優先する場合は気管支ファイバーをガイドにした経鼻挿管が安全. 自発呼吸下の盲目的経鼻挿管は熟練を要する. \n\n'
        '■ 確認・固定\n'
        '・カフを声門下に置き, カプノグラフィ (ETCO₂)+両肺聴診で気管内を確認. \n'
        '・深さの目安は経口より2-3cm深い (鼻孔基準で 女性 約26cm, 男性 約28cm前後). 片肺挿管に注意. \n'
        '・カフ圧を適正化し, チューブを鼻翼/頬に確実に固定 (鼻翼の圧迫壊死に注意). \n\n'
        '■ 合併症\n'
        '・鼻出血 (最多), 鼻甲介・鼻粘膜損傷, 粘膜下の偽腔形成 (false passage), アデノイド/扁桃の損傷・出血, 菌血症, 長期では副鼻腔炎. 頭蓋底骨折例では頭蓋内迷入. \n\n'
        '■ コツ\n'
        '・出血を制する=血管収縮の前処置を丁寧に. チューブは温めて軟らかく. \n'
        '・「顔面に垂直・鼻腔底に沿わせる」方向を守る. Magill鉗子はカフを掴まない. \n'
        '・困難気道ではファイバーガイドが最も確実. ',
  ),
  ColumnArticle(
    category: '気道管理',
    title: 'DLT挿管手順',
    color: _cAirway,
    tags: const ['気道管理', '胸部外科', '分離肺換気', 'DLT', '気管支鏡'],
    body:
        '■ 最初に決めること\n'
        'DLT (double-lumen tube)は左右肺を分離し, 一側肺換気を行うための気道器具. サイズ表や身長からの挿入深さは開始点にすぎず, 最終位置は気管支鏡で確認する. 術側, 切除部位, 気管支形成の有無, 術前CTの気管・主気管支径と走行, 困難気道, 術後挿管継続の可能性を上級医・術者と共有する. \n\n'
        '■ 左用か右用か\n'
        '・原則は左用DLT. 左主気管支は右より長く, 右上葉口を閉塞しにくいため位置決めが安定しやすい. \n'
        '・右用DLTを考えるのは, 左肺全摘, 左主気管支の手術・狭窄・腫瘍・高度変形, 左肺移植など左主気管支へ留置できない場合. 右上葉換気孔を右上葉口に合わせる必要があり, 気管支鏡による確認が必須. \n'
        '・困難気道や術後挿管継続が予想される場合は, まず通常の気管チューブで確実に気道確保し, 気管支ブロッカーを使う選択肢も検討する. \n\n'
        '■ 準備\n'
        '・選択サイズのDLTと1サイズ小さい予備, 両ルーメンを通過できる気管支鏡, コネクター, クランプ, 吸引, ビデオ喉頭鏡, 救済用の通常気管チューブを準備する. \n'
        '・DLT本体と両カフの破損を確認し, 気管支側先端とカフを潤滑する. スタイレット先端をチューブから突出させない. \n\n'
        '■ 挿入\n'
        '1. 十分に酸素化し, 導入後にマスク換気可能であることを確認する. 十分な筋弛緩下に喉頭展開する. \n'
        '2. 気管支側先端を前方へ向けて声門を通す. 気管支カフが声門を越えたらスタイレットを抜く. \n'
        '3. 左用DLTは患者の左方向へ90度反時計回りに回転して, 抵抗を感じるまでゆっくり進める. 右用DLTは右方向へ回転し, 早い段階から気管支鏡で誘導する. 抵抗に逆らって押し込まない. \n'
        '4. 予定深さは参考値として用い, 固定前に位置を確認する. 気管カフ, 気管支カフともシールに必要な最小量・最小圧で膨らませる. 一律の固定量を注入せず, 過膨張による粘膜虚血・気管支損傷を避ける. \n\n'
        '■ 最初の確認\n'
        '・持続するカプノグラムで気管内留置を確認するが, これだけではDLTの左右・深さは確定できない. \n'
        '・クランプテストと左右胸郭運動・聴診はスクリーニング. 聴診だけでは位置異常を除外できないため, 最終確認は気管支鏡で行う. \n'
        '・左用DLTの気管ルーメン: carinaを中央に確認し, 右主気管支と右上葉口が開存していること, 左主気管支内の青い気管支カフ上縁がcarina直下に少量見え, 気管側へ脱出していないことを確認する. \n'
        '・左用DLTの気管支ルーメン: 左上葉口と左下葉口の分岐が見え, どちらもチューブ先端やカフで閉塞していないことを確認する. \n'
        '・右用DLT: 右上葉換気孔と右上葉口の位置が一致し, 気管支中間幹が開存していることを両ルーメンから確認する. \n\n'
        '■ 体位変換と一側肺換気\n'
        'チューブを固定して歯列での深さを記録する. 側臥位への体位変換後は必ず気管支鏡で再確認する. 頭頸部の位置変更, 術者の肺門操作, 換気量低下, 気道内圧上昇, 肺虚脱不良, 酸素化低下があれば位置ずれを疑い, その都度再確認する. 一側肺換気開始前に, どちらのルーメンをクランプして開放するかを術者・上級医と声に出して照合する. \n\n'
        '■ 突然の低酸素・高気道内圧\n'
        '1. 応援を呼び術者へ伝え, 必要なら手術操作を止める. FiO2 1.0とし, 速やかに両肺換気へ戻す. \n'
        '2. 回路, コネクター, クランプ, カフ, 換気側を確認し, 血液・分泌物・粘液栓を吸引する. \n'
        '3. 気管支鏡で浅すぎ, 深すぎ, 左用DLTの右主気管支迷入, 上葉口閉塞を確認して再調整する. \n'
        '4. 位置が正しくても改善しなければ, 無気肺, 気管支攣縮, 出血, 気胸, 循環不全などDLT以外の原因を並行して検索する. \n\n'
        '{{TABLE}}\n\n'
        '■ 終了時\n'
        '両肺換気へ戻し, 両ルーメンを吸引してからカフを脱気する. 術後人工呼吸が必要なら, 通常の気管チューブへの交換を困難気道手順として計画し, 酸素化と再挿管手段を確保して行う. \n\n'
        '■ 根拠\n'
        'BJA Education 2023: Double-lumen tubes and bronchial blockers (PMCID: PMC10591134). 聴診の限界: PMID 1394757. 側臥位後の位置異常と低酸素: PMID 14722168. 左用DLTの回転法: PMCID PMC11046950. 気管支カフ圧: PMID 17312225. ',
    table: ArticleTable(
      headers: ['確認時点', '必須確認', '異常時'],
      rows: [
        ['仰臥位で挿管直後', '気管支鏡でcarina, カフ, 右上葉口, 左上・下葉口', '浅い/深い/左右誤挿入を修正'],
        ['側臥位へ体位変換後', '深さと全葉口の開存を気管支鏡で再確認', '再調整後に固定深さを更新'],
        ['一側肺換気中の変化', '回路・吸引・気管支鏡を順に確認', 'FiO2 1.0, 両肺換気, 術者・上級医と連携'],
      ],
