  ColumnArticle(
    category: '気道管理',
    title: '気管支鏡所見の見かた',
    color: _cAirway,
    tags: const ['気道管理', '気管支鏡', '解剖', '分離肺換気', 'DLT'],
    body:
        '■ 最初に向きを作る\n'
        '気管では前方・側方に白い軟骨輪, 後方に平坦な膜様部が見える. 画面の向きを固定してcarinaまで進み, 正常解剖を系統的にたどる. 分泌物で視野が悪いまま押し進めず, 酸素化・換気を監視しながら必要最小限の吸引を行う. 抵抗がある場所へ無理に進めない. \n\n'
        '■ 右肺の追い方\n'
        'carinaから右主気管支へ入ると, 早い位置で右上葉気管支が分岐する. 典型例では右上葉の3区域口がクローバー状に見えるが, 分岐変異は少なくない. その先の気管支中間幹が右中葉と右下葉へ分かれる. 「早く出る右上葉口」を目印に左右を判断する. \n\n'
        '■ 左肺の追い方\n'
        '左主気管支は右より長く, より水平に走る. その先で左上葉と左下葉に分岐する. 左上葉は上区と舌区へ分かれる. 左用DLTの気管支ルーメンからは, 左上葉口と左下葉口がともに開存していることを確認する. \n\n'
        '{{TABLE}}\n\n'
        '■ 気管チューブの確認\n'
        '通常の気管チューブでは先端, Murphy eye, carinaとの距離を確認する. 片肺挿管, カフの声門側脱出, 気管壁への先端接触, 分泌物・血液による閉塞を評価する. カプノグラムや聴診が正常でも, 深さや局所閉塞を気管支鏡で初めて確認できることがある. \n\n'
        '■ DLTで必ず見る所見\n'
        '左用DLTでは, 気管ルーメンからcarina, 右主気管支, 右上葉口, 左主気管支内の青いカフ上縁を確認する. 次に気管支ルーメンから左上葉口と左下葉口を確認する. 右用DLTでは右上葉換気孔と右上葉口の一致を確認する. 体位変換後と換気異常時は再度観察する. 詳細な手順は関連記事「DLT挿管手順」を参照. \n\n'
        '■ 記録テンプレート\n'
        '「挿入経路 / carina / 右上葉・中葉・下葉 / 左上葉・舌区・下葉 / 分泌物の量・色・粘度 / 血液の部位と活動性 / 粘膜発赤・浮腫 / 狭窄の部位・程度 / 動的虚脱 / 腫瘤・異物 / チューブ先端とカフ / 吸引・洗浄・位置調整後の変化」を記録する. 病変を認めたら時計方向だけでなく, carinaや葉口からの距離, 吸気・呼気での変化も残す. \n\n'
        '■ すぐ上級医・術者へ共有する所見\n'
        '活動性出血, 急速に増える血液, 完全閉塞, 高度狭窄, 気道損傷を疑う裂創, 原因不明の片側換気不良, 大量膿性分泌物, 異物, 換気に伴う高度虚脱. 気管支鏡像だけで腫瘍・感染・損傷を確定診断せず, CT, 手術所見, 培養・病理と統合する. \n\n'
        '■ 根拠\n'
        '気管支解剖: Anatomical considerations in bronchoscopy (PMCID: PMC5696545). DLT確認所見: BJA Education 2023 (PMCID: PMC10591134), anatomical landmarks study (PMCID: PMC9691920). 手技の安全管理: British Thoracic Society guideline for diagnostic flexible bronchoscopy in adults. ',
    table: ArticleTable(
      headers: ['所見', '見え方', '麻酔中に考えること'],
      rows: [
        ['分泌物・粘液栓', '白色/黄緑色, 粘稠, 内腔閉塞', '吸引前後の換気変化, 無気肺, 感染'],
        ['血液', '鮮血/暗赤色, 片側性/両側性, 湧出点', '活動性出血か流入血か, 術者へ即共有'],
        ['発赤・浮腫', '粘膜腫脹, 易出血性, 内腔狭小', '挿管損傷, 炎症, カフ圧, 再挿管リスク'],
        ['固定性狭窄・圧排', '吸呼気で変わらない局所狭窄', '腫瘤, 術後変化, 血管/縦隔からの圧排'],
        ['動的虚脱', '呼気で内腔が大きく狭くなる', '鎮静深度, 自発呼吸, PEEPで変化を再評価'],
      ],
    ),
    relatedArticleTitles: const ['DLT挿管手順'],
