    tags: const ['薬理学', '用量計算'],
    body:
        '■導入\n'
        '1.0-2.0mg/kgショット. 術前で意識状態が悪い人・低心機能では Prop 0.6mg/kg + Sev 2% のslow気味のrapidが安全. '
        '術前で興奮している人は高用量＋予防的昇圧. \n\n'
        '■維持\n'
        '①TCIあり: 導入5.0mcg/ml→就眠後3.0-3.5. 就眠濃度の2倍を下限に下げ, 皮膚縫合で2倍, Xp頃に1.5倍, Xp OKでoff. \n'
        '②TCIなし: 1.5-2.0mg/kgで導入し7mg/kgで30分→4mg/kg/h以上の維持量へ. \n\n'
        '■PRIS (プロポフォール注入症候群)\n'
        '4mg/kg/h以上で48h以上は使わない. 代謝性アシドーシス・高CK>5000・ミオグロビン尿 (横紋筋融解)で直ちに中止. \n'
        '※緑色尿はフェノール代謝物による良性の尿色変化で, PRISの中核症状でも腎機能悪化のサインでもない (それ自体は中止不要). ',
  ),
