  ColumnArticle(
    category: '鎮静',
    title: '麻酔の4段階と MAC / MAC awake',
    color: _cSed,
    tags: const ['生理学', '薬理学'],
    body:
        '■麻酔の4段階 (Guedel)\n'
        '無痛期 → 興奮期 → 外科期 → 麻痺期 (呼吸停止)の四段階. \n'
        '・無痛期: 意識はあるが痛覚が鈍る\n'
        '・興奮期: 意識消失〜外科期手前. 体動・不規則呼吸・嘔吐が出やすく, 刺激を避ける\n'
        '・外科期: 手術に適した安定した麻酔深度\n'
        '・麻痺期: 過量による延髄抑制 → 呼吸停止・循環虚脱 (避けるべき深度)\n\n'
        '■MAC / MAC awake\n'
        '・MAC: 麻酔薬の脊髄反射の抑制度と関連した値 (皮膚切開で50%が体動しない最小肺胞濃度). \n'
        '・MAC awake: 麻酔薬の大脳への作用と関連した値 (開眼・指示に反応する濃度). \n'
        '→ 体動の抑制は脊髄レベル, 意識 (覚醒)は大脳レベルで規定される. ',
