    title: '吸入麻酔薬の作用 (一般的性質・呼吸器)',
    color: _cSed,
    tags: const ['生理学', '薬理学', '呼吸'],
    body:
        '■一般的性質\n'
        '・悪性高熱症の原因になる. \n'
        '・Propofolよりも循環抑制はマイルド. \n'
        '・血液/ガス分配係数が小さいほど血液への溶解性が低く, 導入と覚醒が速くなり調節性が上がる (Des ＜ Sev ＜ Iso). \n\n'
        '■呼吸器への作用 ① 呼吸調整系\n'
        '・濃度依存性にVT (1回換気量)を減少させ, 代償性に呼吸回数は増加する (増加具合は薬剤により変わる). \n'
        '　→ 分時換気量の抑制・PaCO₂上昇の程度: \n'
        '　　エンフルラン ≒ Des ＞ Iso ＞ Sev ＞ ハロタン ＞ 笑気. \n\n'
        '■呼吸器への作用 ② CO₂への反応性\n'
        '・正常ではPaCO₂が1mmHg上昇すると分時換気量(MV)は約3L/min上昇する. \n'
        '　→ すべての吸入麻酔薬はこの換気応答反応を濃度依存性に抑制する. \n'
        '　→ 麻酔域下濃度(0.1MAC)でも抑制されるが, Des・Sevでは作用は小さそう. ',
