  // ───────── 鎮痛・オピオイド ─────────
  ColumnArticle(
    category: '鎮痛・オピオイド',
    title: 'オピオイドの薬理 (μ受容体と呼吸抑制)',
    color: _cOpioid,
    tags: const ['薬理学', '生理学', '呼吸'],
    body:
        'μ・δ・κ受容体があり鎮痛が最も強いのはμ. 鎮痛の主座は中枢性で, 脊髄後角の一次求心性終末 (シナプス前＋シナプス後)と上位中枢 (中脳PAG・延髄RVM)に作用する. 末梢のμ受容体 (炎症組織など)も補助的に関与する. \n\n'
        '痛みを感じなくなる最小有効鎮痛濃度をMEACといい, その個人差は比較的小さい (＝至適濃度は予測しやすい). \n\n'
        '■呼吸抑制\n'
        '効果部位濃度1.5ng/ml以上で用量依存性に出現 (延髄第四脳室のμ受容体). '
        '呼吸数減少のみなのでSpO2低下まで時間がかかる. RR<8ではナロキソン0.1mgショット→0.5-1.0mcg/kg/h. \n'
        '・鎮痛無効域でも嘔気と便秘は出る. ',
  ),
  ColumnArticle(
    category: '鎮痛・オピオイド',
    title: 'レミフェンタニルの特徴 (徐脈・シバリング・OIH)',
    color: _cOpioid,
    tags: const ['薬理学', '循環'],
    body:
        '半減期3min, 停止後5minでCeが半分, 年齢で代謝時間が変わらない. Cp=Ceで安定し流量(γ)×20-25で概ね安定. \n\n'
        '■徐脈・低血圧\n'
        '迷走神経賦活＋陰性変時作用＋血管平滑筋直接弛緩. SVとHRが各15%前後減少→Co25%減少→BP30%低下. '
        'アトロピン/エフェドリンの予防投与を考慮. \n\n'
        '■シバリング\n'
        'レミの急激な消失で発熱反応が抑制されなくなり起こる. 保温・transitional opioid・NSAIDs・Mg・ペチジン等で予防. \n\n'
        '■急性耐性・OIH (痛覚過敏)\n'
        '0.3γ以上で臨床的にOIHを起こす確率が増える. ケタミン併用が抑制する可能性 (エビデンスは弱い). ',
  ),
  ColumnArticle(
    category: '鎮痛・オピオイド',
    title: 'BBB通過性 (脂溶性・髄液移行)',
    color: _cOpioid,
    tags: const ['薬理学'],
    body:
        '・BBB透過性は脂溶性が高い薬剤ほど高い (脂溶性が高いほど中枢への移行・効果発現が速い). \n'
        '・髄液中へのとどまりやすさは水溶性薬剤のほうが高い (→モルヒネITは長時間効くが遅発性呼吸抑制). \n'
        '・レミフェンタニルは効果部位平衡が速く (t½ke0 ≈1分), 血中濃度と効果部位濃度がほぼ一致するため血中濃度を参考に投与できる (動態自体は3-コンパートメントモデル). ',
  ),
  ColumnArticle(
    category: '鎮痛・オピオイド',
    title: 'オピオイド換算が必要な理由 (耐性・依存・離脱)',
    color: _cOpioid,
    tags: const ['薬理学', '用量計算'],
    body:
        '■ ベースで常用している人に何が起きているか\n'
        'オピオイドを継続使用すると数日〜数週で耐性(tolerance)と身体依存が形成される. \n'
        '・μ受容体のダウンレギュレーション／脱感作 (β-arrestin を介した受容体の内在化). \n'
        '・細胞内では cAMP 系が代償的に上方制御され, オピオイドが切れると一気に cAMP が過剰となる (反跳). \n'
        '→ 同じ鎮痛を得るのに必要量が増え, 急に止めると過活動状態 (離脱)になる. \n\n'
        '■ ベースを切らすと起こること (退薬＝離脱)\n'
        '交感神経亢進 (頻脈・高血圧・発汗・散瞳), 強い痛み・痛覚過敏, 悪心・下痢・あくび・不穏・せん妄. \n'
        '→ 術中は覚醒・体動・循環変動, 術後は疼痛コントロール困難の原因になる. \n\n'
        '■ だから「換算して継続」する\n'
        '常用しているオピオイドを等鎮痛量のフェンタニル等に換算し, まず“ベースの分”を投与 (継続)した上で, '
        '手術侵襲に対する鎮痛を上乗せする. ベースを無視するとオピオイドが相対的に不足し, 麻酔が浅くなる・術後に破綻する. \n\n'
        '■ 注意: 不完全交差耐性・OIH\n'
        '・別のオピオイドへ変更する際は受容体サブタイプへの作用が完全には一致しないため, '
        '等鎮痛換算量から 25〜50% 減量して開始するのが安全. \n'
        '・高用量・急速使用では OIH (オピオイド誘発性痛覚過敏)が併存し, 増量しても痛みが取れないことがある (ケタミン併用等を考慮). ',
  ),

