  ColumnArticle(
    category: '筋弛緩',
    title: '筋弛緩の考え方 (適応と遷延リスク)',
    color: _cNmb,
    tags: const ['薬理学'],
    body:
        '■必須となる場面\n'
        '①腹腔鏡手術 (腹直筋を弛緩させないとop困難)②反射回避 (膀胱手術など)'
