        'TOF比0.7-0.9: 頭/下肢挙上可・舌圧子保持・握手可\n'
        'TOF比>0.9: 臨床所見での判定は不可能\n\n'
        '■PTC (post tetanic count)\n'
        'TOFcnt<1の深い筋弛緩の指標. PTC 1なら10分以内, PTC 5なら3-4分, PTC 7ならすぐTOFcntが1になる. \n\n'
        '■スガマデクスのリバース量\n'
        'TOFカウント2以上 (T2再出現＝中等度ブロック)で2mg/kg, PTC 1-2 (深いブロック)で4mg/kg, ロクロ1.2mg/kg投与3分後の緊急リバースで16mg/kg. ',
