  ColumnArticle(
    category: 'モニタリング',
    title: 'ECGモニター (3点/5点/12誘導・誘導と部位・異常波形)',
    color: _cMonitor,
    tags: const ['モニタリング', '循環', '生理学'],
    headerArt: 'ecg_leads',
    body:
        '■ 3点誘導 (モニター心電図)\n'
        '・電極3枚: 右鎖骨下 (RA), 左鎖骨下 (LA), 左下腹部〜左前腋窩下 (LL). 体動・電気メスを避け骨上に貼る. \n'
        '・色は規格で異なる (AHA: RA白・LA黒・LL赤 / IEC・JIS: RA赤・LA黄・LL緑). メーカー差があるので位置で覚える. \n'
        '・I/II/IIIから1つを選んで表示. 通常はP波が明瞭で不整脈監視に向くII誘導. \n'
        '・虚血検出は限定的 (主に下壁). \n\n'
        '■ 5点誘導 (術中標準)\n'
        '・四肢電極4枚 (RA・LA・RL・LL を体幹四隅へ) + 胸部電極1枚 (通常V5: 第5肋間 前腋窩線). \n'
        '・肢誘導 (II)と胸部誘導 (V5)を同時表示でき, II=調律/下壁, V5=前側壁虚血を監視. \n'
        '・II+V5で術中虚血の約80%, V4を加えると約96%を検出. \n\n'
        '■ 12誘導 (胸部電極の位置)\n'
        '・V1: 第4肋間 胸骨右縁. V2: 第4肋間 胸骨左縁. V3: V2とV4の中間. \n'
        '・V4: 第5肋間 左鎖骨中線. V5: V4と同じ高さの前腋窩線. V6: V4と同じ高さの中腋窩線. \n'
        '・追加誘導: 右室はV3R-V4R, 後壁はV7-V9 (背側)を追加する. \n\n'
        '■ 誘導と心臓の部位 (責任冠動脈)\n'
        '{{TABLE}}\n'
        '・aVRのST上昇は左主幹部/三枝病変・近位LADを示唆 (広範な対側性ST低下を伴う). \n\n'
        '■ 主な異常波形と典型パターン\n'
        '【急性虚血】\n'
        '・ST上昇 (STEMI): 隣接2誘導以上のJ点ST上昇. 超急性期は尖鋭高T (hyperacute T), 後に異常Q. 部位から責任冠動脈を推定. \n'
        '・ST低下/T陰転: 心内膜下虚血・NSTEMI/不安定狭心症. 水平〜下降型ST低下が有意. \n'
        '【不整脈】\n'
        '・心房細動: 不規則かつP波消失. 心房粗動: 鋸歯状F波. PSVT: narrow QRSの規則的頻拍. \n'
        '・心室頻拍 (VT): wide QRSの規則的頻拍 (3連発以上). 心室細動 (VF): 無秩序な波形. WPW: δ波+PR短縮. \n'
        '・房室ブロック: Mobitz II・III度 (完全房室ブロック)は高度. \n'
        '【電解質】\n'
        '・高K: テント状T → PR延長/P平低 → QRS開大 → サインカーブ → 心停止. \n'
        '・低K: U波出現・ST低下・T平低化. 低Ca: QT (ST)延長. 低Mg: QT延長・torsades誘発. \n'
        '【その他】\n'
        '・心膜炎: 広範なびまん性ST上昇+PR低下. 肺塞栓: 洞性頻脈・S1Q3T3・右心負荷. \n'
        '・たこつぼ: 広範なST上昇〜深い陰性T+QT延長. 脚ブロック (LBBB/RBBB), ペーシング波形, アーチファクト (体動・電メス)も鑑別. \n\n'
        '■ 上級医をすぐ呼ぶべき波形\n'
        '・新規のST上昇 (STEMIパターン)や有意なST低下/T陰転 (急性虚血). \n'
        '・VT/VF, 持続するwide QRS頻拍, 多形性VT (torsades). \n'
        '・完全房室ブロック・Mobitz II・高度徐脈/洞停止で血行動態不安定. \n'
        '・新規心房細動で頻脈/血行動態不安定. 新規の完全左脚ブロック (LBBB). \n'
        '・高K血症パターン (テント状T〜QRS開大〜サインカーブ), PEA. \n'
        '→ 「急性虚血」「血行動態を脅かす不整脈」「致死的電解質パターン」は迷わずcall. \n\n'
        '■ 採血を追加すべき波形\n'
        '・虚血パターン (ST上昇/低下・T陰転・新規Q) → トロポニン/CK-MB+12誘導確認. \n'
        '・テント状T・QRS開大 → K (高K), 併せてCa/Mg・腎機能・血ガス. \n'
        '・QT延長 → K/Ca/Mg・薬剤確認. U波/ST-T低下 → K (低K)・Mg. \n'
        '・新規Af/VTなど不整脈全般 → 電解質 (K/Mg/Ca)・甲状腺 (TSH)・必要時ジゴキシン濃度・血ガス/Hb. \n'
        '・洞性頻脈+右心負荷 (S1Q3T3) → Dダイマー・血ガス (肺塞栓を疑う). \n\n'
        '※ モニター異常は必ず12誘導で確認し, アーチファクトと鑑別したうえで判断する. ',
    table: ArticleTable(
      headers: ['誘導', '心臓の部位', '主な責任冠動脈'],
      rows: [
        ['II・III・aVF', '下壁', 'RCA (右冠動脈)'],
        ['V1・V2', '中隔', 'LAD 中隔枝'],
        ['V3・V4', '前壁', 'LAD (前下行枝)'],
        ['V5・V6', '側壁 (下部)', 'LCX (回旋枝) / LAD対角枝'],
        ['I・aVL', '高位側壁', 'LCX / 対角枝'],
        ['V7-V9 (V1-V3で高R・ST低下)', '後壁', 'LCX / RCA'],
        ['V3R・V4R', '右室', '近位部 RCA'],
        ['aVR (ST上昇)', '左主幹部/三枝病変の示唆', 'LMCA / 近位LAD'],
      ],
    ),
