    body:
        '・全身麻酔の維持はBIS 40-60が目安 (＜40は深すぎ, ＞60は浅麻酔で術中覚醒リスク). \n'
        '・筋電図(EMG)の混入はBISを偽性に高く表示させる. 電極インピーダンスは低く (おおむね5kΩ未満)保つと正確. \n'
