  ColumnArticle(
    category: 'モニタリング',
    title: 'BIS・INVOS/O3で後方循環は見えるか',
    color: _cMonitor,
    tags: const ['モニタリング', '脳循環', 'NIRS', 'BIS', '後方循環'],
    relatedArticleTitles: const ['BISについて'],
    body:
        '■結論\n'
        'BISが正常で左右のINVOS/O3が保たれていても, 後方循環を含む脳全体が正常とは言えない. '
        '「前額部で大きな変化を検出していない」と解釈する. \n\n'
        '■各モニターが実際に見ているもの\n'
        '{{TABLE}}\n\n'
        '■NIRSの解剖学的範囲\n'
        '成人のINVOS/O3センサーは前額部に貼り, 主にセンサー直下の前頭葉皮質の局所rSO2を測定する. '
        '前方循環全体を見ているわけではなく, ACA-MCA境界領域の限られたoptical fieldを観察している. '
        '信号は動脈・毛細血管・静脈血を含み, 主として静脈側に重みを持つ酸素需給バランスの指標である. '
        '脳血流量そのものではなく, 頭皮など頭蓋外組織の影響も受ける. \n\n'
        '■見逃し得る後方循環障害\n'
        '・PCA領域の後頭葉虚血・梗塞. \n'
        '・椎骨脳底動脈系の低灌流・塞栓. \n'
        '・小脳・脳幹の虚血. \n'
        '・一側性又は小範囲の塞栓性病変. \n'
        'これらは前額部BIS/NIRSが変化しないまま起こり得る. 後頭部へセンサーを移せば同等に測れるとは限らず, '
        '毛髪・筋・静脈洞の影響と機器ごとの承認部位・検証範囲を確認する. \n\n'
        '■それでもNIRSが有用な場面\n'
        '低心拍出, 低血圧, 低酸素血症, 貧血, 過換気による低PaCO2など全脳性の酸素供給低下では, '
        '前頭葉も低下するため脳をsentinel organとして早期警告に使える. '
        '左右差はセンサー不良のほか, 頭頸部位置, 頸動脈・送血管・片側灌流の問題を示唆する. '
        '絶対値だけでなく麻酔導入前baselineからの推移を見て, 機種間の数値を直接比較しない. \n\n'
        '■rSO2が低下したとき\n'
        '1. センサー接触・外光・左右位置・頭頸部の回旋を確認. \n'
        '2. MAP, 心拍出量又はポンプ流量, 送血管位置を確認. \n'
        '3. SpO2/PaO2, PaCO2, Hb, 体温, 麻酔深度と脳酸素消費を確認. \n'
        '4. 片側低下なら頸動脈・片側灌流, 両側低下なら全身性原因を優先して検索する. \n'
        '5. 数値だけを治療せず, 原因に対して介入し反応を再評価する. \n\n'
        '■後方循環リスクが高い場合の補完\n'
        '椎骨脳底動脈病変, 後頭蓋窩・脳幹手術, 大動脈弓手術, 選択的脳灌流, 座位手術などでは, '
        '前額部BIS/NIRSだけに依存しない. 術式に応じて, 経頭蓋ドプラ (側頭窓からPCA, 後頭下窓から椎骨・脳底動脈), '
        '後方誘導を含む多チャンネルEEG, SSEP/MEP, BAEP, TEE・送血流評価, 麻酔前後の神経診察を組み合わせる. '
        '多チャンネルEEGでも小脳・脳幹を直接監視するものではないため, 対象となる血管・神経経路に合わせて選択する. \n\n'
        '■研修医向けの一文\n'
        'NIRS低下は無視しない. しかしNIRS正常を後方循環障害の除外には使わない. '
        'BIS 40-60も「前額部EEGがその範囲」という意味であり, 脳灌流正常の証明ではない. \n\n'
        '■根拠\n'
        'POQI-6 cerebral oximetry consensus (PMID: 33079868). '
        'Masimo O3 Sensor IFU (LAB-10329A). Medtronic INVOS 7100 Pocket Guide. '
        'BIS/limited frontal EEG review (PMID: 22253267). TCD practice standards (PMID: 17238867). ',
    table: ArticleTable(
      headers: ['モニター', '主に見ているもの', '正常でも否定できないもの'],
      rows: [
        ['BIS', '前額部の限定EEGから算出した処理指標', '局所脳血流低下, 後頭葉・小脳・脳幹虚血'],
        ['INVOS / O3', '前額センサー直下の局所Hb酸素飽和度とその推移', '後方循環障害, 小範囲塞栓, 脳全体の正常'],
        ['SpO2', '末梢動脈血酸素飽和度', '脳灌流低下, 局所脳虚血'],
      ],
    ),
  ),
