  ColumnArticle(
    category: '薬理学',
    title: 'グルタミン酸・NMDA受容体と興奮毒性',
    color: _cPharm,
    tags: const ['生理学', '薬理学'],
    body:
        '虚血状態では細胞外グルタミン酸(Glu)濃度が著明に上昇する. \n'
        '虚血で細胞外K上昇→Glu取込阻害＋逆回転で無秩序な放出→Glu受容体が過剰活性化→濃度と暴露時間に依存して神経細胞のアポトーシスを誘導 (興奮毒性 excitotoxicity). \n\n'
        'NMDA型受容体はGluの結合に対しCa透過性が亢進する点が特殊で, 脳虚血・てんかん重積・変性疾患で重要. \n\n'
        'Mgは2価カチオンとしてNMDA受容体の内腔に結合し受容体を塞ぐ (非競合阻害). '
        '心臓手術の脳虚血リスク例で2g程度の投与が神経保護的な可能性 (PMID:28085730). ',
  ),
  ColumnArticle(
    category: '薬理学',
    title: 'PONV (術後悪心嘔吐)の機序と予防',
    color: _cPharm,
    tags: const ['術後', '薬理学'],
    body:
        '■PONVは約30%の頻度で生じる\n'
        '・機序としては延髄網様体にある嘔吐中枢が, 複数の求心性刺激経路によって刺激されることで生じる. \n'
        '　→PONVは術後オピオイドや服薬のアドヒアランスを低下させる. \n'
        '　→1つ以上のリスク因子があれば複数機序の薬剤による予防が推奨. \n\n'
        '■主な経路\n'
        '①延髄最後野の化学受容体引金帯 (CTZ)を介する経路\n'
        '②消化管粘膜から迷走神経を介する経路\n'
        '③前庭神経系から第Ⅷ脳神経を介する経路\n'
        '④心理的要因など大脳辺縁系を介する経路\n'
        '⑤視覚中枢からの経路\n\n'
        '■リスク因子 (Apfelスコア)\n'
        '女性 / 非喫煙者 / PONV・動揺病の既往 / 術後オピオイド使用 の4項目. '
        '該当数が増えるほどリスク上昇 (0→約10%, 4項目→約80%). \n\n'
        '■予防 (機序の異なる薬剤を併用)\n'
        '・5-HT3拮抗薬 (グラニセトロン)… CTZ・消化管経路\n'
        '・ステロイド (少量を導入時)… 機序は不明だが有効\n'
        '・ドロペリドール … CTZのD2受容体 (QT延長に注意)\n'
        '・メトクロプラミド … D2受容体＋消化管運動\n'
        '・プロポフォールによるTIVA, オピオイド減量, 十分な輸液も有効. ',
  ),

  // ───────── 区域麻酔 ─────────
  ColumnArticle(
    category: '区域麻酔',
    title: '局所麻酔薬の薬理 (概説)',
    color: _cReg,
    tags: const ['薬理学'],
    body:
        '・Naチャネルにはサブタイプが9種類あり, 局所麻酔薬の作用機序は完全には解明されていない. \n\n'
        '・塩基型として細胞膜を通過し, 陽イオン型としてNaチャネルのα-subunitに作用して遮断する. \n\n'
        '・解離定数(pKa)が大きいと陽イオン型が増えて効果発現が遅くなる. 脂溶性が高いと作用時間が長くなる. '
        '蛋白結合率が高いと, アシドーシスによる蛋白結合率の僅かな低下により全身毒性が大きく増す. \n\n'
        '・血中濃度の変化は投与経路により異なる. \n'
        '　硬膜外・星状神経節では比較的速い／腕神経叢ブロックでは比較的緩徐. \n\n'
        '・ロピバカイン, ブピバカインは特に「pKaが大きく, 脂溶性が高く, 蛋白結合率95%と高い」という特徴がある (＝長時間作用だが心毒性に注意). ',
  ),
  ColumnArticle(
    category: '区域麻酔',
    title: 'くも膜下腔投与 (脊椎麻酔)の一般論',
    color: _cReg,
    tags: const ['生理学', '薬理学'],
    body:
        '■力価の関係\n'
        '同量投与した時の力価は 静脈内 1 → 硬膜外 10 → 髄腔内 100. \n'
        'epi (硬膜外カテーテル)がくも膜下腔に迷入していた際には10倍量を投与したことになるため注意. \n\n'
        '■ブロックされる神経の順番\n'
        '(i) 交感神経遠心線維: 1-3min, 毛細血管拡張で下肢がポカポカしてくる\n'
        '(ii) 知覚神経(C繊維): 3-5min, 緩やかな温度変化の知覚の遮断\n'
        '(iii) 知覚神経(Aδ繊維): 5-10min, 侵害刺激(痛覚・急激な温度変化)知覚の遮断\n'
        '(iv) 知覚神経(Aβ繊維): 触覚や深部知覚の遮断\n'
        '(v) 運動神経: 髄鞘が厚く必ずしもブロックされない\n\n'
        '・アルコールによるテストはC繊維遮断を検知するため, 麻酔範囲を広く評価することが多い. \n'
        '・深部感覚がブロックされると体動を自覚できず, つま先が動かせるのに動かせないと言ったり, 深呼吸できるのに息苦しさを訴えることがある. \n'
        '・体性痛はAδ繊維(＋C繊維), 内臓痛はC繊維(＋Aδ繊維). \n\n'
        '■術中の嘔気\n'
        'C繊維とAδ繊維のブロックは前後しうるため, cold sign testで広がりを確認しても上腹部操作で嘔気を生じることがある. \n'
        '　→メトクロプラミド 1A iv. もしくは最初から0.5%マーカインを使わず fentanyl 10mcg＋morphine 100mcg (計0.3ml). \n\n'
        '■2nd tap / 手技のコツ\n'
        '・2nd tapは一椎間上から, ある程度効いていれば半量. 量が入りすぎると高位脊麻になり呼吸停止＋徐脈. \n'
        '　→head up, 硫酸アトロピン, 経皮ペーシング. \n'
        '・力んでいるときに入れると上方まで瞬時に広がる. いきんでいないタイミングで投与する. \n'
        '・原則はPDPH予防のため細い鉛筆先 (ペンシルポイント)針が望ましいが, 高齢でPDPHリスクが低く早期離床しない症例 (大腿骨頸部骨折など)では23Gも許容. \n'
        '　→帝王切開などPDPHリスクが高い患者では25G以下やペンシルポイント針にする. ',
  ),
  ColumnArticle(
    category: '区域麻酔',
    title: '硬膜外腔投与の一般論 (モルヒネ・フェンタニル)',
    color: _cReg,
    tags: const ['薬理学'],
    body:
        '■一般的なこと\n'
        '・拡散により脊髄に作用するためBBBは関係ない. 局麻のほか, モルヒネとフェンタニルが保険適応. \n'
        '・脊椎くも膜下腔投与よりも分節麻酔・分離麻酔に優れる. C2/3以下すべての分節の疼痛に対応可能. \n'
        '・胸椎レベルでは硬膜外腔が狭く, 腰椎レベルでは広い\n'
        '　→胸椎レベルはショットでよく広がる, 腰椎レベルはその場に留まる. \n'
        '・硬膜外→硬膜から髄液へ→脊髄後角の一次求心性神経(C繊維)のμ受容体. \n\n'
        '■迷入の注意\n'
        '力価は 静脈内 1 → 硬膜外 10 → 髄腔内 100. くも膜下迷入では10倍量投与になる. \n'
        '血圧が著明に低下する／髄液が引けるときは迷入を疑いその時点でoffとする. 呼吸抑制があれば挿管のまま帰室を考慮. \n\n'
        '■効果\n'
        '鎮痛＋筋弛緩 (局所麻酔薬が高濃度になるとおこる). \n'
        '　→鎮痛作用により吸入麻酔薬のMACを下げる. \n'
        '　→筋弛緩作用はメピバカイン・リドカインで強く, ロピバカイン・ブピバカイン・レボブピバカインでは弱い (ROC併用が必要なことが多い). \n\n'
        '■モルヒネ (硬膜外)\n'
        '水溶性のため硬膜通過に時間がかかる一方でCSF中には長く留まる→CSFの吻側拡散で広い鎮痛効果. \n'
        'CSF中で最高濃度まで90-120min, 鎮痛発現0.5-1.0h, 最大効果3h, 持続8-20h (用量依存性). \n\n'
        '■フェンタニル (硬膜外)\n'
        '脂溶性のため効果発現は早いが持続時間は短い. PCAとして用いる. \n'
        '鎮痛発現5-20min, 持続1.5-3.0h. ',
  ),
  ColumnArticle(
    category: '区域麻酔',
    title: '脊椎麻酔の合併症 (馬尾症候群・TNS・神経毒性)',
    color: _cReg,
    tags: const ['薬理学'],
    body:
        '■馬尾症候群\n'
        '・膀胱直腸障害, 会陰部の知覚障害, 下肢の運動・知覚障害\n'
        '　→1度発生すると症状の回復が非常に困難. \n\n'
        '■Transient Neurologic Symptoms (TNS)\n'
        '・臀部, 大腿, ふくらはぎ外側に放散する痛みおよび異常感覚. 脊椎麻酔からの回復後24h以内に発症. \n'
        '　→数日〜1週間程度で回復する. \n'
        '・リスク: 砕石位(＝神経根・馬尾の牽引), 肥満, 血管収縮薬添加. \n\n'
        '■局所麻酔薬による神経毒性\n'
        '・高濃度で神経毒性を呈することは明らかだが機序は不明\n'
        '　- 局所麻酔薬の界面活性作用による膜融解\n'
        '　- 細胞内Ca↑によるapoptosis / necrosis誘導\n'
        '　- p38 MAPKによる神経毒性\n'
        '　- 局所麻酔薬によるCSF中glutamate濃度上昇 …などの説がある. \n'
        '・臨床使用濃度基準で神経毒性を並べると\n'
        '　ジブカイン ＞ リドカイン ＝ テトラカイン ＞ ブピバカイン. \n'
        '　→R(+)よりS(-)体の方が神経毒性が弱く, S(-)のみ取り出したレボブピバカインもあるが硬膜外投与のみ適応. \n\n'
        '■対応\n'
        '術中の体位とその時間, 砕石位なら器具圧迫による神経障害の可能性は？等比重/高比重か, 投与量は過剰でなかったか…を調べる. \n'
        '　→神経内科医による診察＋vit B12内服開始\n'
        '　→神経伝導速度が正常なら神経障害の可能性は下がる\n'
        '　→MRIで腰椎・神経根の検索をする. ',
  ),

  // ───────── 輸血 ─────────
  ColumnArticle(
    category: '輸血',
    title: '血液型・不規則抗体・クロスマッチ',
    color: _cTrans,
    tags: const ['術前評価', '輸血'],
    body:
        '■規則抗体・不規則抗体\n'
        '規則抗体 … 自然抗体のことで, 抗A・抗Bを指す. \n'
        '不規則抗体 … 免疫抗体のことで, 輸血・妊娠により獲得する. 他者血液が侵入することでそれに対する抗体産生が起き, 出現する. \n\n'
        '■Rh型\n'
        '抗D (Rh)は不規則抗体の中でも臨床的に最重要 (溶血性副作用が重篤). 妊娠時の抗D抗体は胎児・新生児溶血の原因となり注意が必要 (本邦では抗E・抗Le など他の不規則抗体も高頻度に検出される). \n\n'
        '■クロスマッチ (交差適合試験)\n'
        'ABO血液型の不適合を検出することと, 37℃で反応する臨床的に意義のある不規則抗体をチェックすることが目的. \n\n'
        '■輸血の単位\n'
        '・献血200mlから作られる量が1単位\n'
        '・赤血球濃厚液: 1単位 140ml, 2単位 280ml\n'
        '・濃厚血小板: 10単位 約200ml (血小板 約2×10¹¹)\n'
        '・新鮮凍結血漿: 1単位 120ml, 2単位 240ml',
  ),
  ColumnArticle(
    category: '輸血',
    title: '輸血副作用',
    color: _cTrans,
    tags: const ['輸血'],
    body:
        '■急性反応 (輸血中〜24h以内)\n'
        '・溶血性輸血反応: ABO不適合が最重症. 発熱・腰背部痛・ヘモグロビン尿・DIC・ショック・腎不全. '
        '直ちに輸血中止, 大量輸液・利尿でヘモグロビン尿性腎症を防ぐ. \n'
        '・FNHTR (発熱性非溶血反応): 白血球抗体による発熱. 保存前白血球除去で減少. \n'
        '・アレルギー / アナフィラキシー: 蕁麻疹〜アナフィラキシー. IgA欠損患者で重篤. 抗ヒスタミン・アドレナリン. \n'
        '・TRALI (輸血関連急性肺障害): 輸血中〜6h以内の非心原性肺水腫・低酸素. 抗白血球抗体が主因. '
        '支持療法 (利尿は無効). \n'
        '・TACO (輸血関連循環過負荷): 心原性肺水腫. 高齢・心腎不全・急速大量で. 輸血速度制限・利尿. \n'
        '・クエン酸中毒 (低Ca血症)・高K血症・低体温: 大量輸血で出現. \n\n'
        '■遅発性反応\n'
        '・遅発性溶血反応 (数日後): 既往感作による不規則抗体の二次免疫応答. \n'
        '・輸血後GVHD: 供血リンパ球が生着し宿主を攻撃→致死的. 放射線照射製剤で予防. \n'
        '・感染症 (肝炎・HIVなど), 反復輸血による鉄過剰症. ',
  ),
  ColumnArticle(
    category: '輸血',
    title: '大量輸血プロトコル (MTP)',
    color: _cTrans,
    tags: const ['輸血'],
    body:
        '■大量輸血の定義\n'
        '24hで循環血液量相当 (成人で約10単位RBC), または1hで4単位以上, 3hで循環血液量の50%喪失. \n\n'
        '■MTP (Massive Transfusion Protocol)\n'
        '・RBC : FFP : PC ≒ 1 : 1 : 1 に近い比率で投与 (希釈性凝固障害を防ぐ). \n'
        '・早期にトラネキサム酸 (外傷では受傷3h以内に1g→1g). \n'
        '・フィブリノゲンを150-200mg/dL以上に保つ (クリオ/フィブリノゲン濃縮製剤). \n'
        '・Ca補正 (クエン酸中毒でiCa低下→グルコン酸Ca/塩化Ca), 加温, アシドーシス是正. \n'
        '・遊離Hb増加時はハプトグロビンで腎保護. \n\n'
        '■lethal triad (死の三徴)\n'
        '低体温・アシドーシス・凝固障害の悪循環を断つことが重要. \n'
        '輸血と並行して外科的/IVRによる止血を急ぐ. 止血までは permissive hypotension (許容的低血圧)も考慮する. ',
  ),

  // ───────── GL (ガイドライン) ─────────
  ColumnArticle(
    category: '区域麻酔GL',
    title: '区域麻酔・神経ブロックと抗血栓療法GL (概説)',
    color: _cGL,
    tags: const ['術前評価', 'ガイドライン'],
    body:
        '■ ガイドライン概要\n'
        '日本ペインクリニック学会・日本麻酔科学会・日本区域麻酔学会 合同 (平成28年)\n'
        '正式名称: 抗血栓療法中の区域麻酔・神経ブロックガイドライン\n\n'
        '■ 手技の出血リスク分類\n'
        '【高リスク群】\n'
        '・硬膜外麻酔 (通常・血小板低下時)\n'
        '・脊髄くも膜下麻酔 (血小板低下時 or 出血素因あり)\n'
        '・深部神経ブロック (血小板低下時)\n'
        '→ 深部神経ブロック: 斜角筋間/鎖骨上下/腰神経叢/星状神経節/傍脊椎/腰部交感神経節/三叉神経節など\n\n'
        '【中リスク群】\n'
        '・硬膜外麻酔 (通常)\n'
        '・脊髄くも膜下麻酔 (通常)\n'
        '・深部神経ブロック (通常)\n'
        '・体表面ブロック (血小板低下時 or 出血素因あり)\n\n'
        '【低リスク群】\n'
        '・体表面の神経ブロック (通常)\n'
        '→ 体表面ブロック: 浅頸神経叢/腋窩/大腿/TAP/腹直筋鞘/後頭神経/肋間など\n\n'
        '■ 血小板数の目安 (本GL推奨)\n'
        '・硬膜外・脊髄くも膜下穿刺とも 10.0×10⁴/μL 以上が望ましい\n'
        '・硬膜外穿刺: 8.0×10⁴/μL 未満は出血性合併症の危険が高く非推奨\n'
        '・脊髄くも膜下穿刺: 5.0×10⁴/μL 未満は非推奨\n'
        '・深部神経ブロック: 10.0×10⁴/μL 以上で施行が推奨\n'
        '→ 血腫リスク軽減のため, より小さい口径の穿刺針が望ましい\n\n'
        '■ 本GLの位置づけ\n'
        '「個別症例に対する適用では症例ごとの特性に基づき個別に判断する」とされており, '
        '添付文書の休薬期間とGLの推奨期間が乖離している薬剤もある点に注意. ',
  ),
  ColumnArticle(
