        '・ジピリダモール: 2日 / なし\n\n'
        '■ 脊髄くも膜下麻酔の指針 (表8)\n'
        '・アスピリン (NSAIDs含む): 禁忌ではない\n'
        '・シロスタゾール: 3日前に中止\n'
        '・チクロピジン: 14日前に中止\n'
        '・クロピドグレル: 7日前に中止 (添付文書は14日)\n\n'
        '■ 注意点\n'
        '冠動脈ステント留置患者やDAPT (2剤抗血小板療法)中は, 休薬による血栓性リスクと区域麻酔の出血リスクを個別に検討する. 5日程度の短い休薬も考慮される場合がある. ',
