  ColumnArticle(
    category: '術前評価',
    title: 'ASA-PS分類 (米国麻酔科学会 身体状態分類)',
    color: _cPreop,
    tags: const ['術前評価'],
    body:
        '■ ASA-PS分類とは\n'
        '麻酔・手術前の患者の全身状態を6段階で表す分類 (American Society of Anesthesiologists Physical Status). '
        '術前評価の共通言語として広く用いられ周術期リスクと相関するが, それ単独で予後を予測するものではない. \n\n'
        '■ 評価のポイント\n'
        '・併存疾患の重症度・機能制限の程度で判定する (手術の侵襲度は含めない). \n'
        '・主観が入りやすく評価者間でばらつく. \n\n'
        '■ E (緊急)モディファイア\n'
        '緊急手術ではクラスに E を付す (例: ASA III E). 緊急とは「治療の遅れが生命・身体への脅威を著しく増す状態」. \n'
        '・E は I〜V に付加できる. VI には付けない (脳死ドナーの摘出は常に緊急扱いのため単に VI と記載). \n\n'
        '■ 最新版\n'
        '現行の分類・例は ASA (2014年承認, 2020年12月13日改訂)に基づく. 成人例のほか小児例・産科例も別途定義されている. \n'
        '{{TABLE}}\n\n'
        '※ 例はあくまで代表例. 実際は個々の病態・機能制限から総合的に判定する. ',
    table: ArticleTable(
      headers: ['分類', '定義', '成人の例'],
      rows: [
        ['I', '健常人', '健康・非喫煙・飲酒なし〜少量'],
