          '3か月以内のMI/脳卒中/TIA/冠動脈ステント・進行中の心筋虚血や高度弁機能不全・高度のEF低下・敗血症・DIC・ショック・定期透析していないESRD',
        ],
        [
          'V',
          '手術なしでは生存が望めない瀕死状態',
          '腹部/胸部大動脈瘤破裂・多発外傷・mass effectを伴う頭蓋内出血・重篤な心病態や多臓器不全を伴う腸管虚血',
        ],
        ['VI', '脳死患者 (臓器提供のための摘出)', '脳死ドナー'],
      ],
