  ColumnArticle(
    category: '術前評価',
    title: '術前診察テンプレート: 麻酔薬との相性チェック',
    color: _cPreop,
    tags: const ['術前評価', 'チェックリスト', '薬物相互作用'],
    body:
        '■ このテンプレートの使い方\n'
        '短時間の術前診察で「ある/ない」を拾うための入口. Yesがあれば診断名, 重症度, 最終発作/増悪, 処方薬と最終服用時刻, 主治医記録を確認し, 下の病態別記事へ進む. このチェックだけで麻酔計画を確定しない. \n\n'
        '■ 0. 手術・麻酔歴\n'
        '□ 手術名, 体位, 出血量, 緊急度, 術後管理場所を確認した. \n'
        '□ 困難気道, PONV, 覚醒遅延, 抜管困難, 筋弛緩遷延の既往はない. \n'
        '□ 本人/血縁者に悪性高熱, 麻酔中の原因不明の高熱・高CO2・横紋筋融解はない. \n'
        '□ 薬剤, 筋弛緩薬, 抗菌薬, ラテックス, クロルヘキシジンのアレルギー歴を確認した. \n\n'
        '■ 1. 気道・呼吸\n'
        '□ 開口, 歯牙, 頸部可動域, いびき/OSA, CPAP, 誤嚥リスクを確認した. \n'
        '□ 喘息/COPDの最近の増悪, 喘鳴, SABA増加, 入院/挿管歴はない. \n'
        '□ アスピリン/NSAIDsで喘鳴や鼻閉を起こすAERD, 鼻茸, 慢性副鼻腔炎はない. \n'
        '□ 発熱, 上気道感染, 喫煙, 在宅酸素, 肺高血圧を確認した. \n\n'
        '■ 2. 循環\n'
        '□ 運動耐容能, 胸痛, 呼吸困難, 失神, 浮腫, 心不全増悪を確認した. \n'
        '□ 不整脈, QT延長, Brugada症候群, ICD/ペースメーカ, 家族突然死歴はない. \n'
        '□ 抗血小板薬/抗凝固薬は薬剤名だけでなく処方理由と最終服用時刻を確認した. \n\n'
        '■ 3. 神経・精神・筋\n'
        '□ Parkinsonismではレボドパ等を通常時刻に投与できる計画がある. \n'
        '□ てんかん/抗てんかん薬, 重症筋無力症, 筋ジストロフィー, 麻痺, 熱傷, 長期臥床を確認した. \n'
        '□ 抗精神病薬, 抗うつ薬, リチウム, MAOI, 睡眠薬/ベンゾジアゼピンの内服を確認した. \n'
        '□ 慢性ベンゾジアゼピン使用/依存が疑われる場合, フルマゼニルで急性離脱・痙攣を起こしうることを計画に反映した. \n\n'
        '■ 4. 眼科・遺伝性疾患\n'
        '□ 緑内障は開放隅角か閉塞隅角かを確認した. \n'
        '□ 網膜硝子体手術後のSF6/C3F8眼内ガスが残っていないことを確認した. 不明なら笑気を使用しない. \n'
        '□ 急性ポルフィリン症, 悪性高熱素因, 偽性コリンエステラーゼ欠損はない. \n\n'
        '■ 5. 腎・肝・内分泌\n'
        '□ 腎機能, 肝機能, 電解質, 糖尿病薬/インスリン, 甲状腺疾患を確認した. \n'
        '□ 長期/高用量ステロイド, 最近の中止, 副腎不全がなく, 必要例ではステロイドカバー計画がある. \n\n'
        '■ 6. 出血・血栓と区域麻酔\n'
        '□ 血小板, Hb, PT-INR/APTT, 出血歴, 血栓歴, 輸血準備を手術侵襲に応じて確認した. \n'
        '□ neuraxial/深部ブロックを行う場合, 抗血栓薬の休薬と再開を最新GL・腎機能・適応から確認した. \n\n'
        '■ 7. 最後に声に出して共有\n'
        'ASA-PS, 気道Plan A/B, 麻酔法, 注意する相互作用, 目標循環/換気, 鎮痛・PONV, 術後監視場所を上級医と共有する. ',
    relatedArticleTitles: const [
      '緑内障・眼内ガスと麻酔薬',
      '喘息・AERDと麻酔薬',
      'Parkinsonismと周術期薬',
      '向精神薬内服と麻酔薬',
      'てんかん・抗てんかん薬と麻酔',
      '神経筋疾患・熱傷・長期臥床と筋弛緩薬',
      '悪性高熱・急性ポルフィリン症',
      'QT延長・Brugada症候群と周術期薬',
      'OSA・高齢/フレイルと鎮静・鎮痛',
      '周術期アレルギー後の次回手術',
      '周術期ステロイドカバー (副腎不全の予防)',
      '区域麻酔・神経ブロックと抗血栓療法GL (概説)',
