  ColumnArticle(
    category: '術前評価',
    title: '周術期アレルギー後の次回手術',
    color: _cPreop,
    tags: const ['術前評価', 'アレルギー', 'アナフィラキシー', 'ロクロニウム', 'スガマデクス', '抗菌薬'],
    body:
        '■ 原則: 推測で1剤だけ入れ替えない\n'
        '周術期は導入薬, オピオイド, 筋弛緩薬, 抗菌薬, スガマデクス, 消毒薬, ラテックス, 輸血製剤などが短時間に重なる. 発症直前の1剤だけを原因と決めつけると, 真の原因薬を再投与したり, 不要な「全麻酔薬アレルギー」ラベルを残したりする. 待機手術は可能ならアレルギー評価を完了してから計画し, 原因候補・交差反応・検査陰性の代替薬を文書化する. \n\n'
        '■ 発症した手術で残す情報\n'
        '・症状発現までの分単位のタイムラインと, 投与薬・輸液・輸血・消毒・被覆材・カテーテル・ラテックス曝露を全て記録する. 抗菌薬は開始時刻と投与終了時刻も残す. \n'
        '・急性期トリプターゼを院内手順に沿って速やかに採血し, 1-2時間付近の検体と24時間以降または回復後の基礎値を比較できるようにする. 採血が正常でもアナフィラキシーを完全には否定できない. \n'
        '・麻酔記録, 投薬記録, 手術看護記録, 製品名・ロット, 蘇生経過をアレルギー専門診療へ渡す. 患者には「確定原因」と「精査中の回避薬」を区別した文書を渡す. \n\n'
        '■ 次回手術までの評価\n'
        '麻酔科とアレルギー専門医が, 臨床経過, トリプターゼ, 皮膚試験, 特異的IgEや好塩基球活性化試験, 必要時の薬物負荷試験を組み合わせる. 検査対象は発症時に曝露した全候補から選び, 筋弛緩薬では交差反応をみるため代替候補も検査する. 陰性試験でも反応をゼロにはできないため, 次回麻酔は原因回避だけでなく再発時の即応計画を持つ. \n\n'
        '{{TABLE}}\n\n'
        '■ ロクロニウム (ROC)が疑われる場合\n'
        '・ロクロニウムを避けるだけでベクロニウムやスキサメトニウムへ自動変更しない. 筋弛緩薬間の交差反応は予測困難で, 別薬にも反応しうる. \n'
        '・第一候補は筋弛緩薬を使わない麻酔・気道計画が成立するかの検討. 必要なら, アレルギー検査で陰性となった別の筋弛緩薬を定量TOF監視下で使う. シスアトラクリウム等は検査候補になり得るが, 未検査で「安全薬」とは扱わない. \n'
        '・スガマデクスはロクロニウムアナフィラキシーの標準治療でも予防薬でもない. 症例報告はあるが臨床経過を改善しない報告もあり, スガマデクス自体やROC-SGX複合体もアレルゲンになり得る. 急性期はアドレナリン, 気道・酸素化, 輸液を優先する. \n\n'
        '■ スガマデクス (SGX)が疑われる場合\n'
        '・スガマデクスと, 必要に応じてロクロニウムおよびROC-SGX複合体を専門施設で評価する. スガマデクス単体だけの陰性結果で複合体反応を完全には除外できない. \n'
        '・次回はスガマデクスを避け, 筋弛緩薬非使用, 自然回復を待てる計画, または適切な回復深度でネオスチグミン＋抗コリン薬を用いる計画を検討する. ネオスチグミンは深い筋弛緩を即時回復させる代替ではないため, 定量TOFと手術終了時刻から逆算する. \n\n'
        '■ 抗菌薬が疑われる場合\n'
        '・「ペニシリンアレルギー」だけでセファゾリンを一律除外しない. 交差反応は主に側鎖構造で決まり, セファゾリンのR1側鎖は他の多くのβラクタムと異なる. ただしセファゾリン自体の即時型反応, 重症遅延型反応 (SJS/TEN, DRESS, 臓器障害)の既往では別扱いとし, 専門評価と院内基準を優先する. \n'
        '・セファゾリンが原因と疑われる場合も, 全βラクタムを永久禁止にせず, 側鎖と検査結果に基づき別のβラクタムを候補にできるか評価する. \n'
        '・クリンダマイシンやバンコマイシン等への変更は手術部位, 想定菌, MRSAリスク, 投与開始時刻, 腎機能, 院内アンチバイオグラムで決める. これらはセファゾリンと同等の万能代替ではなく, 不必要な変更はSSIや有害事象を増やし得る. \n\n'
        '■ 精査前に緊急手術が必要な場合\n'
        '過去の記録から発症時間帯の全候補を洗い出し, 疑わしい薬剤と交差反応が懸念される薬剤を避ける. 使用薬を必要最小限にし, ラテックスフリー・クロルヘキシジンフリー等も原因候補に応じて明示する. アドレナリンを直ちに使える状態とし, 導入前ブリーフィングで「避ける物質, 使用する代替, 再発時の役割分担」を共有する. 抗ヒスタミン薬やステロイドの前投薬で再発を防げるとは考えない. \n\n'
        '■ 根拠\n'
        '日本麻酔科学会「アナフィラキシーに対する対応プラクティカルガイド」. Perioperative anaphylaxis review (PMCID: PMC7807982). ROC/SGX review (PMCID: PMC4819478). Sugammadex anaphylaxis systematic review (PMCID: PMC9728450). Drug Allergy: A 2022 Practice Parameter Update (J Allergy Clin Immunol 2022;150:1333-1393). ',
    table: ArticleTable(
      headers: ['疑う原因', '避けるもの', '次回の候補 (専門評価後)'],
      rows: [
        ['ロクロニウム', 'ROCと交差反応未評価の筋弛緩薬', '筋弛緩薬なし, または検査陰性の別NMBA'],
        ['スガマデクス', 'SGXと未評価のROC-SGX複合体', '自然回復, または適切な深度でネオスチグミン＋抗コリン薬'],
        ['セファゾリン', 'セファゾリン', '側鎖・検査で選んだ別βラクタム, または術式別の非βラクタム薬'],
        ['ペニシリン系', '確定原因薬と同一/類似側鎖薬', '重症遅延型反応を除き, セファゾリンを含め専門評価'],
        ['クロルヘキシジン/ラテックス', '皮膚・粘膜・器材を含む全曝露経路', '明示したフリー環境と代替消毒・器材'],
      ],
    ),
  ),
  ColumnArticle(
    category: '術前評価',
    title: '周術期ステロイドカバー (副腎不全の予防)',
    color: _cPreop,
    tags: const ['術前評価', 'ガイドライン', '薬理学'],
    body:
        '■ なぜ必要か\n'
        '長期のステロイド投与で視床下部-下垂体-副腎系 (HPA軸)が抑制されると, 手術侵襲というストレスに対して内因性コルチゾールを増やせず, 周術期に副腎クリーゼ (輸液・昇圧に不応の低血圧・ショック)を起こしうる. これを防ぐために外因性グルココルチコイドを上乗せするのがステロイドカバー. \n\n'
        '■ 対象 (HPA抑制のリスク)\n'
        '・プレドニゾロン 5mg/日以上 (相当量)を数週間〜1か月以上. \n'
        '・原発性/続発性副腎不全 (Addison病・下垂体機能低下・先天性副腎過形成). \n'
        '・最近まで長期ステロイド使用 (中止後もしばらく回復に時間がかかる). 高用量吸入・頻回の関節注射・広範な外用の長期も要注意. \n'
        '・低用量 (PSL 5mg未満)や短期のみなら, 通常は自前の反応で足り追加不要. 判断困難例は内分泌コンサルト/ACTH (迅速)刺激試験を考慮. \n\n'
        '■ 投与法 (英国2020ガイドライン+侵襲度別の考え方)\n'
        '・普段のステロイドは当日朝も継続 (経口不可なら静注換算で継続). \n'
        '・局麻の小手術/小侵襲: 通常の内服のみで可 (必要時 導入時ヒドロコルチゾン25-100mg). \n'
        '・中〜大手術: 導入時にヒドロコルチゾン100mg iv → 術後は 200mg/日持続 (または50mg 6hおき)を経口摂取が可能になるまで. その後は通常量へ (大手術では24-48h 常用量の2倍程度から漸減). \n'
        '・小児は導入時ヒドロコルチゾン 2mg/kg (最大100mg)など体重換算. \n\n'
        '■ 副腎クリーゼの認識と対応\n'
        '・原因不明で輸液・昇圧に反応しない低血圧, 低Na・高K・低血糖 → 副腎クリーゼを疑い, ヒドロコルチゾン100mg ivを直ちに投与し輸液. \n\n'
        '■ 過剰投与にも注意\n'
        '画一的な大量投与は創傷治癒遅延・高血糖・感染リスクを増やす. 侵襲度に応じて最小限とし, 常用ステロイドの継続を忘れない. ',
  ),
  ColumnArticle(
    category: '術前評価',
    title: '感染症スクリーニングの読み方 (HIV/HBV/HCV/梅毒)',
    color: _cPreop,
    tags: const ['術前評価'],
    body:
        '■ HBV (B型肝炎): 既感染 / ワクチン後 / 現感染 の判別\n'
        '・HBsAg (+): 現在感染 (キャリア or 急性). \n'
        '・HBsAb のみ (+) (HBsAg-, HBcAb-): ワクチン後の免疫. \n'
        '・HBcAb (+): 自然感染の既往. HBsAg(-)・HBsAb(±)なら既往感染 → 免疫抑制・化学療法時は de novo B型肝炎のリスクがあり HBV-DNA を監視. \n\n'
        '■ HCV (C型肝炎)\n'
        '・HCV抗体 (+): 既往 or 現感染 → HCV-RNA で確認 (RNA(+)で現感染, RNA(-)は既往 or 治癒). \n\n'
        '■ HIV\n'
        '・第4世代 Ag/Ab (p24抗原＋抗体)でスクリーニング → 陽性は確認検査 (核酸/Western blot). 感染初期はウインドウ期に注意. \n\n'
        '■ 梅毒 (RPR ＋ TP抗体)\n'
        '・RPR(+) かつ TP(+): 活動性 or 治療中・既往 (RPR定量で評価). \n'
        '・RPR(-) かつ TP(+): 治療後・既往感染. \n'
        '・RPR(+) かつ TP(-): 生物学的偽陽性 (妊娠・膠原病・急性感染初期など). \n\n'
        '※ 結果に関わらず標準予防策は全例で徹底. 針刺し・職業感染対策 (HBVワクチン/曝露後対応)を確認する. ',
  ),

