  ColumnArticle(
    category: '併存疾患・内服',
    title: '緑内障・眼内ガスと麻酔薬',
    color: _cComorb,
    tags: const ['術前評価', '眼科', '薬物相互作用'],
    body:
        '■ 最初に病型を分ける\n'
        '「緑内障あり」だけで全ての抗コリン薬を一律に禁忌としない. 問題になるのは主に閉塞隅角/狭隅角での散瞳と急性隅角閉塞であり, 開放隅角緑内障とは扱いが異なる. '
        'アトロピン注の本邦添付文書も禁忌を「閉塞隅角緑内障」としている. 病型不明なら眼科記録, 虹彩切開歴, 点眼内容を確認し上級医へ相談する. \n\n'
        '■ 術前に必ず聞く3点\n'
        '1. 閉塞隅角/狭隅角か, 開放隅角か. \n'
        '2. 網膜硝子体手術で SF6/C3F8 などの眼内ガスを入れていないか. \n'
        '3. 点眼薬は何か. チモロール点眼は徐脈・気管支攣縮, コリンエステラーゼ阻害点眼はスキサメトニウム遷延の原因になりうる. \n\n'
        '{{TABLE}}\n\n'
        '■ 急性隅角閉塞を見逃さない\n'
        '術後の片眼痛, 充血, 霧視/虹視, 頭痛, 悪心嘔吐, 固定した中等度散瞳を単なるPONVとして処理しない. 視機能を失いうる眼科救急なので直ちに眼科へ連絡する. \n\n'
        '■ 眼内ガスは日数で自己判断しない\n'
        '笑気は眼内ガスを急速に膨張させ, 眼圧上昇と失明を起こしうる. ガスが完全吸収されたと眼科医が確認するまで使用しない. ガス種・注入日が不明なら笑気なしで計画する. \n\n'
