  ColumnArticle(
    category: '併存疾患・内服',
    title: '喘息・AERDと麻酔薬',
    color: _cComorb,
    tags: const ['術前評価', '呼吸', '薬物相互作用'],
    body:
        '■ リスクは「喘息の有無」より現在のコントロール\n'
        '最近の増悪, 夜間症状, SABA使用増加, 喘鳴, 入院/挿管歴, 経口ステロイド歴を確認する. コントロール不良の予定手術は最適化を優先する. GINAは周術期もICSを含む通常治療の継続を推奨している. \n\n'
        '{{TABLE}}\n\n'
        '■ NSAIDsを全喘息患者で禁止しない\n'
        'アスピリン/NSAIDで喘鳴, 鼻閉, 蕁麻疹を起こした既往, 鼻茸・慢性副鼻腔炎を伴う AERD/NERD ではNSAIDsを避ける. 既往のない安定喘息まで一律に禁忌とする必要はないが, 初回投与は観察可能な環境で行う. \n\n'
        '■ 気道操作が最大の誘因になりうる\n'
        '十分な麻酔深度, 必要時の術前サルブタモール, 加温加湿, 長い呼気時間でair trappingを避ける. 深い鎮静で気道を確保しない状態より, 適切に管理された気道の方が安全な症例もある. \n\n'
        '■ ステロイド歴もセットで確認\n'
        '長期高用量ICSまたは過去6か月に2週間超の全身ステロイド歴があればHPA軸抑制を考え, ステロイドカバーの記事も確認する. \n\n'
        '根拠: GINA 2025 Strategy Report, perioperative asthma systematic review, PMDA各薬剤添付文書. ',
    table: const ArticleTable(
      headers: ['場面', '避ける/慎重', '選択・対策'],
