        ['併用薬', '非選択的β遮断薬, AERDでのNSAIDs', '吸入薬を継続. 適応があれば選択的薬を個別判断'],
      ],
    ),
  ),
  ColumnArticle(
    category: '併存疾患・内服',
    title: 'Parkinsonismと周術期薬',
    color: _cComorb,
    tags: const ['術前評価', '神経', '薬物相互作用'],
    body:
        '■ 最優先は「いつもの時刻」に投与すること\n'
        'レボドパやドパミン作動薬の遅延・中断は無動, 誤嚥, Parkinsonism-hyperpyrexia syndromeを招く. 手術当日も少量の水で通常時刻に継続し, 長時間手術/NPOなら可溶性レボドパの胃管投与やロチゴチン貼付への置換を術前に専門医と計画する. 自己判断で一括休薬しない. \n\n'
        '{{TABLE}}\n\n'
        '■ 制吐薬とせん妄治療で悪化させない\n'
        'ドパミン遮断薬は固縮・無動を悪化させる. ドロペリドール, ハロペリドール, メトクロプラミド, プロクロルペラジンを避ける. PONVはデキサメタゾン, 5-HT3拮抗薬などを検討するが, MAO-B阻害薬併用ではセロトニン毒性とQTを含め個別判断する. \n\n'
        '■ MAO-B阻害薬を見つけたら相互作用表を開く\n'
        'セレギリン, ラサギリン, サフィナミドではトラマドール, ペチジン, メサドン, デキストロメトルファン等を避ける. フェンタニルにも相互作用報告がある. 昇圧薬への反応が増強することがあるため, 少量から直接作動薬を滴定し上級医と計画する. \n\n'
        '■ 病態そのものの注意\n'
        '起立性低血圧, 胃排出遅延・嚥下障害, 流涎, 拘束性換気障害, 術後せん妄を見込む. 大量フェンタニルによる胸壁固縮, 中枢性抗コリン薬による混乱にも注意する. \n\n'
        '根拠: UKCPA Parkinson\'s Disease Overview/各薬剤monograph, Parkinson\'s UK surgery guidance. ',
    table: const ArticleTable(
      headers: ['確認薬', '問題になる薬', '対応'],
      rows: [
        ['レボドパ/ドパミン作動薬', '投与遅延・突然の中止', '通常時刻を守り, NPO代替を術前計画'],
