        ['MAO-B阻害薬', 'トラマドール, ペチジン, メサドン, デキストロメトルファン', '非セロトニン性鎮痛を優先し相互作用を確認'],
        ['自律神経障害', '急な血管拡張/大量昇圧薬', '直接作動薬を少量滴定, 体位変換を緩徐に'],
      ],
    ),
