  ColumnArticle(
    category: '併存疾患・内服',
    title: '向精神薬内服と麻酔薬',
    color: _cComorb,
    tags: const ['術前評価', '精神科', '薬物相互作用'],
    body:
        '■ 原則は薬剤名を同定し, 急に止めない\n'
        '向精神薬の多くは再燃・離脱を防ぐため継続する. 一方でリチウムと不可逆的MAOIは個別計画が必要. 「向精神薬あり」だけで一括中止せず, 一般名, 最終服用時刻, QTc, Na, 腎機能, 併用薬を確認する. \n\n'
        '{{TABLE}}\n\n'
        '■ セロトニン毒性を薬の組み合わせで考える\n'
        'SSRI/SNRI/MAOI, リチウム等にトラマドール, ペチジン, メサドン, タペンタドール, デキストロメトルファン, linezolid, methylene blueなどが重なると危険が上がる. フェンタニルや5-HT3拮抗薬も報告があるため, 単剤の「禁忌暗記」ではなく総負荷で判断する. 覚醒遅延に加え, 発熱, 発汗, agitation, clonus/過反射, 下痢を見たら疑う. \n\n'
        '■ リチウムは脱水と腎機能で急に危険になる\n'
        'UKCPAは小手術では継続, 大手術では24時間前中止を推奨する. Na/Cr/甲状腺/ECGを確認し, 脱水・低Naを避ける. NSAIDs, ACE阻害薬/ARB, 利尿薬で濃度が上がりやすく, 筋弛緩遷延と麻酔必要量低下にも注意する. 再開は腎機能・電解質・飲水が安定してから. \n\n'
        '■ QT延長を重ねない\n'
        '抗精神病薬/一部抗うつ薬にドロペリドール, オンダンセトロン等を重ねる前にQTcとK/Mg/Caを確認する. 高熱・筋強剛・自律神経不安定では悪性症候群も鑑別する. \n\n'
        '根拠: SPAQI psychiatric medication consensus (Mayo Clinic Proceedings 2022), UKCPA Lithium/Phenelzine monographs. ',
    table: const ArticleTable(
      headers: ['薬効群', '主なリスク', '周術期の考え方'],
      rows: [
