        ['不可逆的MAOI', '高血圧クリーゼ, セロトニン毒性', '精神科と事前計画. 急な中止を避けMAOI-safe麻酔'],
        ['抗精神病薬', 'QT, 低血圧, 抗コリン, 悪性症候群', '通常継続. ECG/電解質と重複薬を確認'],
        ['リチウム', '腎排泄, 筋弛緩遷延, 毒性', '大手術は24h前中止を検討. 水分/Na/腎機能を管理'],
        ['ベンゾジアゼピン', '呼吸抑制, せん妄, 離脱痙攣', '慢性内服は継続. 追加鎮静を減量'],
      ],
