  ColumnArticle(
    category: '併存疾患・内服',
    title: 'てんかん・抗てんかん薬と麻酔',
    color: _cComorb,
    tags: const ['術前評価', '神経', '薬物相互作用'],
    body:
        '■ 抗てんかん薬は手術当日も継続\n'
        '飲み忘れと急な中断が反跳性痙攣/statusの主要な回避可能因子. 通常時刻に少量の水で投与し, 絶食が長いなら静注代替の有無を確認する. カルバマゼピンには静注製剤がないため, 神経内科/薬剤師と代替を事前に決める. \n\n'
        '{{TABLE}}\n\n'
        '■ 麻酔薬は用量と状況で促進/抑制が変わる\n'
        'プロポフォールとバルビツレートは抗痙攣作用がありstatusにも用いられる. セボフルランは小児, 高濃度, 過換気/低CO₂で痙攣様脳波が増えるため高濃度を長く維持しない. 局所麻酔は禁忌ではないが, 極量超過や血管内注入によるLASTを避ける. \n\n'
        '■ 術後の「震え」を全て痙攣にしない\n'
        'シバリング, ジストニア, ミオクローヌス, emergence agitationも鑑別する. ただし痙攣が疑わしければ酸素化, 血糖, Na/Ca/Mg, 抗てんかん薬の最終投与を同時に確認する. \n\n'
        '根拠: UKCPA Antiepileptics Overview/Carbamazepine/Phenytoin/Valproate monographs. ',
    table: const ArticleTable(
      headers: ['背景薬', '相互作用/検査', '対応'],
      rows: [
        [
          'カルバマゼピン',
          '低Na, CYP誘導でミダゾラム/フェンタニル低下, 非脱分極性筋弛緩短縮',
