  ColumnArticle(
    category: '併存疾患・内服',
    title: '神経筋疾患・熱傷・長期臥床と筋弛緩薬',
    color: _cComorb,
    tags: const ['術前評価', '筋弛緩', '薬物相互作用'],
    body:
        '■ 筋弛緩薬を通常量で固定しない\n'
        '神経筋接合部疾患, 脱神経, 熱傷, 長期臥床では反応が正反対になる. 病名, 発症/受傷日, 筋力・球症状, 呼吸機能, 既往麻酔での遷延を確認し, 定量的TOFで投与と抜管を決める. \n\n'
        '{{TABLE}}\n\n'
        '■ 重症筋無力症 (MG)\n'
        '非脱分極性筋弛緩薬に強く感受性があり, 通常量で遷延しうる. 可能なら筋弛緩薬を避け, 必要ならロクロニウムを少量ずつ定量TOFで滴定しスガマデクスを準備する. スキサメトニウムは抵抗性とコリンエステラーゼ阻害薬による遷延が混在し予測困難. IV Mg, アミノグリコシド, 一部マクロライド/キノロン, β遮断薬は筋力悪化に注意する. \n\n'
        '■ スキサメトニウム高K血症を時間軸で考える\n'
        '広範熱傷, 脊髄損傷, 脳卒中後麻痺, GBS/ALS, 筋ジストロフィー, 長期不動では筋外ACh受容体が増え致死的高K血症を起こしうる. 熱傷では概ね受傷24-48時間後から危険となり, 少なくとも1年は回避する考え方が一般的. 緊急気道でもロクロニウム等の代替を先に計画する. \n\n'
        '■ 覚醒しているのに動けない状況を防ぐ\n'
        '偽性コリンエステラーゼ欠損ではスキサメトニウム/ミバクリウムが数時間遷延する. 拮抗薬を重ねず, 鎮静・人工呼吸を継続し定量TOF回復まで待つ. 本人と家族へ説明し医療アラート登録につなげる. \n\n'
        '根拠: European Neuromuscular Centre consensus, MGFA Cautionary Drugs, OrphanAnesthesia Pseudocholinesterase Deficiency. ',
    table: const ArticleTable(
      headers: ['背景', '危険な組合せ', '基本戦略'],
      rows: [
        ['MG/LEMS', '通常量の非脱分極性筋弛緩薬, IV Mg', '減量・定量TOF・術後呼吸計画'],
        ['熱傷/脱神経/長期不動', 'スキサメトニウム → 高K血症', 'ロクロニウム等へ変更. 発症日を確認'],
        [
          'Duchenne等筋ジストロフィー',
          'スキサメトニウム, 揮発性麻酔薬関連横紋筋融解',
