  ColumnArticle(
    category: '併存疾患・内服',
    title: '悪性高熱・急性ポルフィリン症',
    color: _cComorb,
    tags: const ['術前評価', '遺伝性疾患', '薬物相互作用'],
    body:
        '■ 悪性高熱素因 (MHS)\n'
        '本人/血縁者の悪性高熱, 原因不明の麻酔中高熱・高CO₂・横紋筋融解を確認する. セボフルラン, デスフルラン等の全揮発性麻酔薬とスキサメトニウムがtrigger. 笑気, 局所麻酔薬, 静脈麻酔薬, オピオイド, 非脱分極性筋弛緩薬はMHAUS上triggerではない. \n'
        'trigger-free麻酔, 麻酔器の準備/活性炭フィルタ, ダントロレンと危機対応手順を入室前に確認する. 過去に吸入麻酔を無事に受けていても素因は否定できない. \n\n'
        '■ 急性ポルフィリン症\n'
        'AIP/VP/HCP/ADPでは薬剤, 絶食, 脱水, 感染, ストレスが発作を誘発しうる. 「ポルフィリン症」の型を確認し, 最新の専用薬剤データベースで全薬を照合する. バルビツレート (チオペンタール/チアミラール)とエトミデートは避け, プロポフォール等の安全リスト薬を選ぶ. 十分な糖質と水分を確保し, 不必要な長期絶食を避ける. \n\n'
        '{{TABLE}}\n\n'
        '■ 似た危機を混同しない\n'
        '悪性高熱, 悪性症候群, セロトニン症候群, 甲状腺クリーゼは発熱・頻脈・筋症状が重なるが治療が異なる. ETCO₂急上昇, 筋強剛, 高K, CK, clonus/過反射, 原因薬と時間経過を並行評価する. \n\n'
        '根拠: MHAUS Safe and Unsafe Anesthetics, OrphanAnesthesia Porphyria 2026, British Porphyria Association safe-drug database. ',
    table: const ArticleTable(
      headers: ['背景', '避ける薬', '代替/準備'],
      rows: [
