        ['急性ポルフィリン症', 'バルビツレート, エトミデートなどunsafe薬', '最新DBで全薬照合. プロポフォール等safe薬'],
        ['どちらも', '病名不明のまま通常導入', '既往記録/家族歴を確認し上級医・専門医へ'],
      ],
    ),
  ),
  ColumnArticle(
    category: '併存疾患・内服',
    title: 'QT延長・Brugada症候群と周術期薬',
    color: _cComorb,
    tags: const ['術前評価', '循環', '薬物相互作用'],
    body:
        '■ まず12誘導ECGと薬剤リスト\n'
        '先天性か薬剤性か, 失神/心停止歴, ICD, 家族歴を確認する. K/Mg/Ca, 体温, 酸素化, 酸塩基異常を補正し, 除細動パッドとMgを準備する. QT延長薬は単剤より「重ね使い」で危険が増える. \n\n'
        '{{TABLE}}\n\n'
        '■ 先天性Long QT\n'
        'β遮断薬は原則継続. ドロペリドール, オンダンセトロン, 一部抗精神病薬/抗菌薬などQT延長薬の重複を避け, 最新のCredibleMedsで確認する. PONVはデキサメタゾン等QTへの影響が少ない選択肢を軸にする. 交感神経刺激, 徐脈, 電解質異常を避ける. \n\n'
        '■ Brugada症候群\n'
        '発熱, 徐脈/迷走神経緊張, 電解質異常が不整脈を誘発する. プロポフォールの単回導入は安全性データが蓄積しているが, 高用量長時間持続は慎重. 局所麻酔薬は最少有効量とし, 長時間作用性薬の大量投与よりリドカインを検討する. 根拠は症例集積が中心なので, BrugadaDrugs/専門医と個別に確認する. \n\n'
        '■ 「禁忌リスト」だけで終わらない\n'
        '十分な鎮痛・麻酔深度, 正常体温, 電解質管理, 連続ST/QT監視, 術後監視までを一つの計画にする. \n\n'
        '根拠: OrphanAnesthesia Long QT/Brugada recommendations, Brugada麻酔 systematic review (Saudi J Anaesth 2023), CredibleMeds. ',
    table: const ArticleTable(
      headers: ['背景', '注意薬/誘因', '対策'],
      rows: [
        ['Long QT', 'ドロペリドール, オンダンセトロン, QT延長薬の重複', 'QTc/電解質確認, β遮断薬継続, Mg準備'],
        ['Brugada', '発熱, 徐脈, Naチャネル遮断薬, 高用量長時間propofol', '正常体温, ST監視, 除細動準備'],
        ['ICDあり', '電気メス干渉', 'デバイス計画, パッド装着, 術後再設定確認'],
      ],
    ),
  ),
  ColumnArticle(
    category: '併存疾患・内服',
    title: 'OSA・高齢/フレイルと鎮静・鎮痛',
    color: _cComorb,
    tags: const ['術前評価', '呼吸', 'せん妄', '薬物相互作用'],
    body:
        '■ 少量の薬でも作用が重なる背景\n'
        'OSA, 肥満低換気, 高齢/フレイル, 認知症ではベンゾジアゼピン, オピオイド, 抗コリン薬, ガバペンチノイド等の鎮静・呼吸抑制が加算される. 「通常量を全部少しずつ」ではなく, 必要薬を絞り滴定する. \n\n'
        '{{TABLE}}\n\n'
        '■ OSAでは深い鎮静より確実な気道管理が安全なことがある\n'
        '表在手術では局所/区域麻酔を優先し, 鎮静するならcapnographyを使用する. 気道を機械的に脅かす処置では, 気道未確保の深い鎮静より確実な気道を伴う全身麻酔を検討する. 筋弛緩の完全拮抗を定量確認し覚醒抜管, 半座位/側臥位回復, 患者のCPAP再開を計画する. \n\n'
        '■ PCAの持続投与を安易に付けない\n'
        'OSA高リスクではopioid-sparing鎮痛を組み, IV-PCAのbackground infusionは避けるか極めて慎重にする. 酸素投与だけで低換気を見えにくくしないよう, 呼吸数・鎮静度・必要時capnographyも見る. \n\n'
        '■ 高齢者では抗コリン負荷も確認\n'
        'ベンゾジアゼピン, ジフェンヒドラミン/ヒドロキシジン, 不要なアトロピン, 高用量オピオイドはせん妄を悪化させうる. ただし慢性ベンゾジアゼピンを突然中止すると離脱・痙攣を起こすため, 定期薬継続と追加鎮静の抑制を分けて考える. \n\n'
        '根拠: ASA OSA Practice Guideline, SASM perioperative recommendations, SPAQI psychiatric medication consensus. ',
    table: const ArticleTable(
      headers: ['背景', '相性が悪い組合せ', '対応'],
      rows: [
        ['OSA/肥満低換気', 'ベンゾ+opioid, 気道未確保の深鎮静', '区域麻酔, capnography, CPAP, 覚醒抜管'],
        ['OSAのPCA', '基礎持続+追加bolus', '基礎持続を避けopioid-sparingと監視を強化'],
        ['高齢/フレイル', '抗コリン薬, ベンゾ, 高用量opioid', '少量滴定, 非薬物的せん妄予防'],
        ['慢性ベンゾ内服', '突然の中止', '定期薬は継続し追加鎮静のみ減らす'],
      ],
    ),
  ),

  // ───────── 区域麻酔 / 脊髄保護 ─────────
  ColumnArticle(
    category: '区域麻酔',
    title: 'Spinal drainage (脊髄ドレナージ / CSFドレナージ)',
    color: _cReg,
    tags: const ['モニタリング', '大血管', '術前評価'],
    body:
        '■ 目的・適応\n'
        '・主目的は胸腹部/下行大動脈手術 (開胸・TEVAR含む) での脊髄虚血＝対麻痺の予防・治療. '
        'くも膜下にカテーテルを留置して脳脊髄液 (CSF)を排液し, CSF圧を下げて脊髄灌流圧を保つ. \n'
        '・その他, 硬膜損傷後の髄液漏 (CSFリーク)管理などにも用いられる. \n\n'
        '■ 原理: 脊髄灌流圧 (SCPP)を守る\n'
        '・SCPP ＝ MAP − CSF圧 (静脈側を重視するなら CVP との大きい方を用いる). \n'
        '・大動脈遮断や側副血行の途絶で脊髄血流が低下する → 「CSF圧を下げる」＋「MAPを上げる」の両輪で SCPP を確保する. \n\n'
        '■ 留置とゼロ点\n'
        '・通常 L3/4 または L4/5 でくも膜下にカテーテルを留置. \n'
        '・トランスデューサの基準高 (外耳道 or 刺入部)を施設手順で固定し, ゼロ較正を確実に. 高さがずれると圧・排液量が大きく変わる. \n\n'
        '■ 管理目標 (代表例・施設により異なる)\n'
        '{{TABLE}}\n'
        '■ ドレナージの実際\n'
        '・重力式 (チャンバ高で圧設定)が基本. 目標CSF圧を超えた分だけ自然排液させる. \n'
        '・「過剰排液は禁物」: 1回・1時間あたりの排液量に上限を設け, 急速・大量排液 (硬膜下/頭蓋内出血の誘因)を避ける. \n'
        '・術中〜術後 (48–72hが高リスク期)まで継続し, 神経所見を見ながら漸減・抜去する. \n\n'
        '■ 対麻痺が出たら\n'
        '・MAPを上げる (昇圧), CSFドレナージを強化 (目標圧をさらに下げる), 貧血是正 (Hb), 正常体温・酸素化の最適化. \n'
        '・MEP/SSEPの併用で術中に虚血を早期検出できると対応が早い. \n\n'
        '■ 合併症 (リスクとして必ず説明)\n'
        '・硬膜下/硬膜外血腫, 過剰排液による頭蓋内出血・硬膜下血腫, 低髄圧頭痛, 髄膜炎・刺入部感染, カテーテル断裂, 神経損傷. \n'
        '・抗凝固/抗血小板薬との併用は区域麻酔GLに準じ, 留置・抜去のタイミング (休薬・再開)を厳格に管理する → 区域麻酔GLのコラム参照. \n\n'
        '※ 目標値・プロトコルは術式・施設で差がある. 最新のガイドライン・成書・施設手順を必ず確認すること. ',
    table: const ArticleTable(
      headers: ['項目', '目安'],
      rows: [
        ['CSF圧', '≦ 10 mmHg (施設により 8–12)'],
        ['排液速度', '≦ 10–15 mL/h ・ 過剰排液は避ける'],
        ['SCPP', 'MAP − CSF圧(or CVP)を十分に確保'],
        ['MAP', '高め維持 (例 80–90+ , 対麻痺時はさらに↑)'],
        ['留置部位', 'L3/4 または L4/5 くも膜下'],
        ['高リスク期', '術中〜術後 48–72h を重点監視'],
        ['抗凝固', '区域麻酔GLに準じ留置/抜去を調整'],
      ],
    ),
  ),

  // ───────── 循環器疾患 (疾患別の麻酔管理・術中トラブル) ─────────
  ColumnArticle(
    category: '循環器疾患',
    title: 'Fontan循環患者の麻酔管理',
    color: _cCardiac,
    tags: const ['先天性心疾患', 'Fontan循環', '循環器', '術前評価'],
    body: '■病態の要点\n'
        '・Fontan循環は単心室のみを駆動源とし, 全身静脈血は受動的に肺へ流入する非拍動性循環である. 肺血流は中心静脈圧 (CVP) と共通心房圧 (CAP) の較差 (経肺較差, 通常7mmHg前後) のみで維持され, PVR上昇は直ちに心拍出量 (CO) 低下に直結する.\n'
        '・前負荷は静脈系うっ滞に依存し, 陰圧吸気は肝静脈還流を増やし肺血流を押し上げる (安静時COの約30%が呼吸仕事由来) . 陽圧換気はこの駆動力を消失させ, 平均気道内圧が上がるほどCIは直線的に低下する.\n'
        '・フェネストレーション残存例では, PVR上昇時に右左短絡でCOを保つ代わりチアノーゼが悪化する.\n'
        '・心房内リエントリー頻拍 (IART) ・洞不全は高頻度 (Fontan後20年でIART約50%, 洞機能不全約40%) で, 心房収縮消失は経肺較差を直ちに下げCOを急落させる.\n'
        '・Fontan関連肝疾患 (FALD) , 蛋白漏出性腸症 (PLE) , 血栓症, 腎機能障害を高率に合併する.\n'
        '\n'
        '■術前の評価と準備 (リスクヘッジ)\n'
        '・直近の心臓カテーテル検査でCAP, CVP, 心室拡張末期圧, 弁機能, フェネストレーション開存の有無を確認する. 検査が古くても緊急手術は遅らせない.\n'
        '・血液検査: Hb/Ht, 凝固 (蛋白C/S・アンチトロンビンIII低下の可能性) , 総蛋白/アルブミン (PLE) , 肝機能・胆道系酵素 (FALD) , 腎機能.\n'
        '・静脈路開存の確認: 術後5年以内に約10%で中心静脈血栓性閉塞を来す. 鎖骨下・内頸静脈閉塞例があるため, 事前に血管マッピング (エコー/透視) を行う.\n'
        '・抗凝固/抗血小板薬の休薬計画: ワルファリンは通常5日前中止でINR確認, 未分画ヘパリンは可逆性が高く周術期ブリッジに適する. 抗血小板薬継続の可否は血栓/出血リスクを個別に判断する.\n'
        '・不整脈既往とペースメーカの有無を確認する. 依存例は術前に非同期モード (DOO/VOO) への一時変更とややレート高めの設定を依頼 (電気メス誤抑制の回避) .\n'
        '・大手術・開胸・片肺換気例では, 緊急時に大腿静脈脱血・動脈送血で部分体外循環〜VA-ECMOへ移行できる体制 (灌流技師待機, 大腿動静脈の位置確認) を組んでおく.\n'
        '・麻酔科・循環器/ACHD医・外科・体外循環技師を含む多職種術前カンファレンスを行う.\n'
        '\n'
        '■麻酔計画\n'
        '・目標は経肺較差の維持: 前負荷十分, SVR維持, PVR上昇回避, 洞調律 (心房収縮) 温存, 心拍数維持.\n'
        '・導入: 急激なSVR低下を避ける. プロポフォール大量投与は短絡方向を変化させうるため, フェンタニル/エトミデート中心の緩徐な導入が無難. ケタミンはSVR/PVRへの影響が少なく血行動態不安定例の選択肢.\n'
        '・換気: 平均気道内圧を最小化する. PEEPは最小限 (0〜5cmH2O) , 一回換気量は少なめ (6mL/kg前後) , 吸気時間を短くし吸気プラトーを避け, 可能なら圧規定換気または自発呼吸下の最小圧サポートを用いる. 過膨張・無気肺いずれもPVRを上げるため適正な肺気量を保つ. 軽度過換気 (pCO2 30〜35mmHg, pH 7.45前後) と高めのFiO2を基本とし, バルサルバ様の持続陽圧を避ける.\n'
        '・低体温はPVRを上げるため加温を徹底する.\n'
        '・区域麻酔: 前負荷が保たれていれば害は限定的だが, 循環血液量減少例では前負荷減少を助長する. 硬膜外は高位設定を避け, 少量分割投与・十分な補液下での導入を優先する.\n'
        '\n'
        '■静注薬による対応\n'
        '・低血圧: 昇圧はノルアドレナリン少量 (0.02〜0.1γ) から開始する. α作動薬は静脈容量血管収縮と後負荷増大で前向き血流をむしろ下げうるため必要最小量にとどめ, 不十分ならバソプレシン (0.01〜0.04単位/分) を併用する (肺血管への影響が少ない) .\n'
        '・収縮能低下: ミルリノン (負荷0.25〜0.5γを10分, 維持0.25〜0.5γ/分) は陽性変力・肺血管拡張・ルシトロピー作用を併せ持ち第一選択になりやすいが, 血圧低下にはバソプレシン併用で対応する. ドブタミン (2〜5γ) はPVRを下げつつ変力を得たい場合の代替.\n'
        '・PVR上昇・低酸素: NO吸入 (20〜40ppm) を早期または救助的に開始する. 中止時は反跳性肺高血圧に注意し漸減する.\n'
        '・不整脈: IART (心房細動/粗動) で血行動態が保たれていればβ遮断薬 (エスモロール0.5mg/kgボーラス, 維持50〜200γ/分) で心拍数調節を優先する. 不安定なら薬物より同期下カルディオバージョンを優先する.\n'
        '・カリウム, マグネシウムの補正を早期から行い不整脈誘発を予防する.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '・除細動パッドの事前貼付: 開胸歴が多く体外パドルでは有効通電が困難なため, 導入前に自己接着式除細動パッドを必ず貼付する. 2025年改訂版ACHDガイドラインは, 血行動態不安定な頻脈性不整脈リスクが高い患者 (Fallot型修復後・心室機能低下など) への除細動パッド事前貼付をクラスI/エビデンスレベルCで推奨.\n'
        '・IARTへの対応: 血行動態が破綻すれば直ちに同期下カルディオバージョン (二相性100〜200Jから開始) . 心房ペーシングリードがあれば心房オーバードライブペーシング, なければ経食道ペーシングによる停止も選択肢.\n'
        '・ペーシング: Fontan患者はエピカーディアルリードが標準 (経静脈リードは血栓性リスクと解剖学的制約から避ける) . ペースメーカ依存例は電気メス誤作動防止のため非同期モードへの変更を依頼する.\n'
        '・気泡除去の徹底: 静脈路への薬液・輸液投与前に空気を丁寧に除去し, ラインにエアフィルタを組み込む (フェネストレーションや遺残短絡による奇異性塞栓の危険) . 中心静脈カテーテルは血栓リスクのため使用後速やかに抜去する.\n'
        '・循環補助: 内科的治療に反応しない低心拍出症候群には大腿動静脈からのVA-ECMO導入を早期検討する (上大静脈系還流不良を避けるため上半身静脈の追加脱血が必要になりうる) .\n'
        '\n'
        '■トラブル時の初動\n'
        '・急激な低酸素: フェネストレーション/バッフルリークからの右左短絡増悪を最優先に疑う. FiO2 100%とし, 軽度過換気でpCO2を下げPVRを速やかに低下させる. 気管支挿管や無気肺, 気管支攣縮などの通常原因も並行して除外する.\n'
        '・低心拍出 (低血圧, CVP上昇, 乳酸上昇, 尿量低下) : まず平均気道内圧を下げる. 律動を確認し洞調律逸脱があれば同期下カルディオバージョンを検討, ミルリノンまたはドブタミン+少量ノルアドレナリン/バソプレシンで循環を支持する.\n'
        '・心停止・難治性ショック: 大腿動静脈からのVA-ECMO/部分体外循環への迅速な移行を想定し, 灌流技師と外科医をただちに招集する.\n'
        '\n'
        '■出典\n'
        '・2025年改訂版 成人先天性心疾患診療ガイドライン (日本循環器学会/日本小児循環器学会/日本成人先天性心疾患学会)\n'
        '・Muñoz Y, et al. Physiopathological Approach of the Fontan Patient for Noncardiac Surgery for the Anesthesiologist. IntechOpen, 2020.\n'
        '・Coulie R, et al. Anaesthetic Management of One-Lung Ventilation in a Fontan Patient. Cureus 2025;17(8):e89274.',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: '短絡性心疾患 (ASD/VSD/PDA) とEisenmenger症候群の麻酔管理',
    color: _cCardiac,
    tags: const ['先天性心疾患', 'Eisenmenger症候群', '肺高血圧', '循環器'],
    body: '■病態の要点\n'
        '・ASD/VSD/PDAは左右短絡疾患であり, 短絡量は欠損サイズとPVR/SVR比で決まる. 未修復例では長期の肺血流増加により肺血管リモデリングが進行しPVRが上昇し, ついに短絡が逆転して右左短絡優位となる (Eisenmenger症候群) .\n'
        '・Eisenmenger症候群ではPVRがSVRと拮抗またはこれを上回り, 慢性低酸素血症, 二次性多血症, 鉄欠乏, 過粘稠, 出血・血栓の両方向への凝固異常, 腎機能障害を高率に合併する. 非心臓・非産科手技でも待機手術で死亡率約2%, 緊急手術では最大15%と報告される.\n'
        '・左右短絡例ではSVR低下・PVR上昇のいずれも短絡量を減らす方向に働くが, 右左短絡優位 (Eisenmenger) 例ではSVR低下・PVR上昇のいずれも右左短絡とチアノーゼを悪化させる.\n'
        '\n'
        '■術前の評価と準備 (リスクヘッジ)\n'
        '・術前SpO2 (室内気) , Hb/Ht, 鉄欠乏の有無 (Hbが見かけ正常でも鉄欠乏があれば組織酸素供給は不十分) , 腎機能, 凝固能を確認する.\n'
        '・Eisenmenger疑い例は必ず専門施設または多職種 (循環器/ACHD医, 麻酔科, 外科) でリスク評価を行う. 緊急手術はこれを理由に遅らせない.\n'
        '・感染性心内膜炎予防抗菌薬を投与計画に組み込む (チアノーゼ性心疾患・人工物残存例で特に重要) .\n'
        '・脱水回避のため術前絶飲食時間を最小化し, 入室後早期に末梢静脈路を確保し補液を開始する. 過粘稠症状 (頭痛, 視覚異常, しびれ) があってもHt>65%かつ脱水補正後のみ瀉血を検討し, ルーチンの瀉血・アフェレーシスは行わない.\n'
        '・全ての静脈路にエアフィルタを装着し気泡混入を絶対に避ける. 短絡の左右にかかわらず, PVR上昇時に潜在的短絡が顕在化しうるため徹底する.\n'
        '・心臓カテーテル歴があれば肺体血流比 (Qp/Qs) , 肺血管反応性 (急性血管拡張試験) , 手術適応の可否を確認する.\n'
        '\n'
        '■麻酔計画\n'
        '・左右短絡優位例: SVR低下を許容しつつPVR上昇を避ける方針でよい. プロポフォールはSVR低下を介してQp/Qsを下げ短絡量を減らす方向に働くため使いやすい.\n'
        '・Eisenmenger (右左短絡優位) 例: 最重要目標はSVRを下げないこととPVRを上げないことの両立. プロポフォール急速大量投与によるSVR急落は右左短絡を増悪させ致命的な低酸素を招きうるため, オピオイド主体で緩徐に導入し血管収縮薬を併用してSVR低下を予防する. ケタミンはSVR/PVRへの影響が少なく有用な選択肢.\n'
        '・区域麻酔: 脊髄くも膜下麻酔のような急激な交感神経遮断はEisenmenger例では原則避ける. 硬膜外は少量分割投与で緩徐にレベルを上げれば施行可能だが, 常に血管収縮薬を即座に使える準備をしておく. 末梢神経ブロックは血行動態への影響が少なく積極的に併用する.\n'
        '・気道管理・換気: 低酸素・高二酸化炭素・気道内圧上昇はいずれもPVRを上げるため, 挿管操作は愛護的に行い, 抜管前に十分な鎮痛と気道反射の評価を行う.\n'
        '\n'
        '■静注薬による対応\n'
        '・SVR維持: フェニレフリン (少量ボーラス40〜100μg, 持続0.1〜0.5γ) またはノルアドレナリン少量 (0.02〜0.1γ) でSVRを支持する. 特にEisenmenger例では血圧低下を待たず予防的投与を検討する.\n'
        '・PVR低下: 低酸素・アシドーシスの是正に加え, NO吸入 (20〜40ppm) やイロプロスト吸入は選択的に肺血管を拡張しSVRを下げずに右左短絡を軽減できる. 静注プロスタグランジン系薬は全身血管拡張を伴うため単独では使いにくい.\n'
        '・右心不全兆候にはミルリノンを少量から開始するが, 全身血管拡張分をノルアドレナリン/バソプレシンで補うことを前提とする.\n'
        '・鎮痛: オピオイドはSVRへの影響が少なく多用してよい.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '・静脈路・輸液ラインへのエアフィルタ装着と, 薬液投与前の気泡除去を全例で徹底する (右左短絡が明らかでなくても奇異性塞栓のリスクを常に想定する) .\n'
        '・加温と十分な補液で脱水・低体温 (いずれもPVR上昇因子) を回避する.\n'
        '・感染性心内膜炎予防抗菌薬の周術期投与 (高リスク手技・チアノーゼ性心疾患で適応) .\n'
        '・血行動態が不安定なEisenmenger例, 大手術例では動脈ライン・中心静脈ラインによる侵襲的モニタリングを行う. 中心静脈路留置時は右左短絡による奇異性塞栓リスクを念頭に置き, 気泡混入対策を徹底する.\n'
        '・PVR急上昇 (肺高血圧クリーゼ) が疑われる重症例では, 除細動パッドを事前貼付し急変に備える.\n'
        '・難治性の低酸素・低心拍出に陥った場合に備え, VA-ECMO導入を視野に入れた体制 (灌流技師待機) をあらかじめ準備する.\n'
        '\n'
        '■トラブル時の初動\n'
        '・急激な低酸素・チアノーゼ増悪: PVR上昇 (低酸素・高二酸化炭素・アシドーシス・疼痛・浅麻酔) を疑い, FiO2上昇, 過換気, 鎮痛強化を行う. 同時にSVR低下がないか確認し, フェニレフリン/ノルアドレナリンで速やかに是正する.\n'
        '・循環虚脱: 血管収縮薬 (フェニレフリンボーラス, ノルアドレナリン増量) で速やかにSVRを回復させる. NO吸入または肺血管拡張薬でPVRを下げる. 改善なければVA-ECMOを検討する.\n'
        '\n'
        '■出典\n'
        '・Kaye AD, et al. Left-to-Right Cardiac Shunt: Perioperative Anesthetic Considerations. M.E.J. Anesth 2012;21(6):793-.\n'
        '・Eisenmenger Syndrome: Pathophysiology, Risk Assessment and Management (update review) . Int J Cardiol Congenit Heart Dis 2024.\n'
        '・Kaemmerer H, et al. Comments on the 2022 ESC PAH Guidelines Regarding ACHD, Part II. Cardiovasc Diagn Ther 2024;14(5):921-934.\n'
        '・2025年改訂版 成人先天性心疾患診療ガイドライン',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: 'Tetralogy of Fallot (TOF) と右心不全を伴う先天性心疾患の麻酔管理',
    color: _cCardiac,
    tags: const ['先天性心疾患', 'Fallot四徴症', '無酸素発作', '循環器'],
    body: '■病態の要点\n'
        '・未修復TOFは肺動脈狭窄/閉鎖, 心室中隔欠損, 大動脈騎乗, 右室肥大を4徴とし, 右室流出路狭窄 (RVOTO) の程度とSVR/PVR比が短絡方向を決める. 漏斗部筋束の動的狭窄がSVR低下・交感神経緊張・脱水を契機に急激に悪化すると, 無酸素発作 (Tetスペル) を起こす.\n'
        '・修復後遠隔期は肺動脈弁逆流による右室拡大・機能低下, 心室性/心房性不整脈, QRS幅延長 (180ms以上) に伴う心臓突然死リスクが問題となる. 修復後30年での不整脈死は6〜9%.\n'
        '・右心不全合併例では, 前負荷は保ちつつ後負荷 (PVR) を上げない管理が肝要である.\n'
        '\n'
        '■術前の評価と準備 (リスクヘッジ)\n'
        '・未修復/姑息術後例: 室内気SpO2, Hb/Ht (見かけ上正常でも鉄欠乏があれば酸素供給能は不十分, 鉄欠乏の合併に注意) , 凝固能, 腎機能を確認する. 無酸素発作の既往・頻度・誘因 (啼泣, 排便, 脱水, 発熱) を必ず聴取する.\n'
        '・修復後例: 直近の心エコー/MRIで肺動脈弁逆流の程度, 右室容量・機能, QRS幅, 不整脈既往を確認する. QRS幅180ms以上かつ有症候性の心室/右室機能低下例はプログラム心室刺激による突然死リスク評価の適応となりうる (2025年改訂版ACHDガイドライン, クラスIIa/エビデンスレベルB) . 該当例では術前に循環器医へICD適応の再評価を依頼する.\n'
        '・血行動態不安定な心室頻拍のリスクが高い患者 (Fallot修復後・心室機能低下など) には, 入室後・導入前に除細動パッドを貼付しておく (同ガイドライン, クラスI/エビデンスレベルC) .\n'
        '・脱水回避のため術前絶飲水時間を短縮し, 入室後早期に末梢静脈路を確保し補液を開始する. 発熱・啼泣・疼痛など交感神経刺激の誘因を事前に除去する.\n'
        '・慢性的にβ遮断薬 (プロプラノロール等) でスペル予防中の例が多く, 直近の内服時刻を確認する. 心内シャント残存例では静脈路のエアフィルタを準備する.\n'
        '・難治性徐脈・房室ブロック合併例や心臓再手術歴があり急な循環虚脱が懸念される例は, 術前に経静脈ペーシング (頸静脈アプローチ) の留置を循環器医に依頼するか, 体外ペーシングパッドを常時使用可能な状態にしておく.\n'
        '\n'
        '■麻酔計画\n'
        '・未修復/右左短絡優位例: SVRを下げずPVRを上げない緩徐な導入が基本. 吸入導入は末梢血管拡張・SVR低下を招きやすくスペル誘発リスクがあるため, 可能なら静脈路確保後の緩徐な静脈麻酔導入を優先する. ケタミンはSVR/心拍数を維持しやすく有用. 喉頭鏡操作自体がスペルの契機になるため十分な鎮痛下で行う.\n'
        '・修復後・右心不全合併例: 前負荷を適切に維持しつつ, 低酸素・高二酸化炭素・気道内圧上昇によるPVR上昇を避ける. 陽圧換気は必要最小限のPEEP・気道内圧を心がける.\n'
        '・換気: FiO2は高めに設定し, 軽度の過換気 (pCO2やや低め) でPVRを抑える. 気道内圧の急上昇 (咳嗽, 浅麻酔での体動) を避ける.\n'
        '・侵襲的動脈圧ラインを早期に確保し, 拍動ごとの血圧変動とスペル徴候 (急激なSpO2低下) を監視する.\n'
        '\n'
        '■静注薬による対応\n'
        '・Tetスペル: 100%酸素投与, 十分な鎮痛 (モルヒネ等) を行いつつ, フェニレフリンボーラス (成人目安1〜2μg/kg, 反応不良なら反復) でSVRを上げる. 効果不十分・遷延時はノルアドレナリンまたはバソプレシン持続投与に切り替える. 同時に晶質液の急速輸液 (10〜20mL/kg) で前負荷を補う.\n'
        '・漏斗部攣縮にはβ遮断薬 (エスモロール0.5mg/kgボーラス, または少量プロプラノロール0.01〜0.1mg/kg) を投与し心拍数を下げ, 右室流出路の動的狭窄を軽減する.\n'
        '・プロポフォールによる急激なSVR低下は避ける. やむを得ず使用する場合は少量分割投与とし, フェニレフリンを並行投与する.\n'
        '・右心不全兆候にはミルリノン少量から開始し, 全身血管拡張分はノルアドレナリン/バソプレシンで補う. PVR上昇が強い例はNO吸入 (20〜40ppm) を追加する.\n'
        '・薬物療法でスペルが停止しない場合, 全身麻酔導入・筋弛緩による酸素消費量低減を検討するが, 導入自体がSVRを下げうるため昇圧薬を用意したうえで行う.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '・除細動パッドの事前貼付: 血行動態不安定な心室性不整脈リスクの高い患者には導入前に貼付しておく (ガイドライン クラスI/エビデンスレベルC) .\n'
        '・スペル時の体位: 膝胸位 (knee-chest position) を取らせ静脈還流とSVRを増加させる. 成人では股関節屈曲位や下肢挙上で代用してもよい.\n'
        '・修復後で有症候性心室機能低下・QRS幅延長例は, 術前にプログラム心室刺激による評価やICD適応をあらかじめ確認しておく. 未評価のハイリスク例で高侵襲手術が予定される場合は電気生理専門医への術前相談を検討する.\n'
        '・難治性徐脈・房室ブロック合併例, 再手術歴があり急な循環虚脱が懸念される例は, 術前の経静脈ペーシング留置依頼または体外ペーシングパッドの常時待機を行う.\n'
        '・難治性スペル・低心拍出には体外式循環補助 (ECLS/VA-ECMO) を早期の選択肢として想定し, 灌流技師・外科医と連携できる体制を組む.\n'
        '\n'
        '■トラブル時の初動\n'
        '・急激なSpO2低下 (スペル疑い) : ただちに100%酸素, 十分な鎮痛, 膝胸位, フェニレフリンボーラス, 急速輸液を行う. 改善しなければβ遮断薬を追加し, 麻酔深度・刺激源 (浅麻酔, 気道内吸引など) を再評価する.\n'
        '・血行動態不安定な心室頻拍: 貼付済みの除細動パッドから直ちに非同期除細動 (成人200J二相性目安) を行う. 意識のある不安定な上室頻拍は同期下カルディオバージョンを優先する.\n'
        '・難治性低酸素・低心拍出: ECLS/VA-ECMO導入を早期に決定し, 大腿動静脈の確保と灌流技師招集を並行して進める.\n'
        '\n'
        '■出典\n'
        '・2025年改訂版 成人先天性心疾患診療ガイドライン\n'
        '・Kaiser E, et al. Uncorrected Tetralogy of Fallot in Adults. Cureus 2024;16(8):e67063.\n'
        '・Hammett CJK, Griksaitis MJ. Postoperative Management After Tetralogy of Fallot Repair. Front Pediatr 2023.\n'
        '・Verma N, et al. Anesthetic Challenges in an Infant With Tetralogy of Fallot Posted for Non-cardiac Surgery. Cureus 2023;15(10):e47327.',
