  ColumnArticle(
    category: '循環器疾患',
    title: '大動脈弁狭窄 (AS) 患者の麻酔管理',
    color: _cCardiac,
    tags: const ['循環器', '弁膜症', '大動脈弁狭窄', '麻酔管理'],
    body: '■病態の要点\n'
        '・大動脈弁狭窄 (AS) は弁口面積の減少により左室から大動脈への駆出路に固定された抵抗 (fixed afterload) が生じる病態である. 心拍出量は前負荷・心拍数・収縮性を変化させても弁口を超える血流にはほぼ影響を与えられず, 血行動態は非常に狭い許容域の中で維持されている.\n'
        '・代償として求心性肥大が進行し心室コンプライアンスが低下する. 十分な一回拍出量を得るには高い左室拡張末期圧 (LVEDP) が必要になる一方, 過大な前負荷は容易に肺水腫を招く.\n'
        '・肥厚心筋は心内膜下虚血に陥りやすく, 冠灌流圧 (拡張期血圧-LVEDP) の維持が生命線になる. 頻脈は拡張時間短縮による冠灌流低下と, 拡張障害による心房収縮 (atrial kick) 依存の喪失を通じて急速に破綻をきたす.\n'
        '・管理の原則は"速くしない・下げない・不整脈にしない"の3点に尽きる. 心拍数上昇, SVR低下による血圧低下, 洞調律の喪失のいずれもが冠灌流圧を落とし, 虚血→収縮力低下→さらなる血圧低下という悪循環に陥りやすい.\n'
        '\n'
        '■術前の評価と準備 (リスクヘッジ)\n'
        '・心エコーで大動脈弁口面積 (AVA), 平均圧較差 (mPG), 最大血流速度 (Vmax), LVEF, 肺動脈圧を確認する. 重症AS (AVA<1.0cm2, mPG≥40mmHg, Vmax≥4.0m/秒) かつ有症状の場合は, 待機的非心臓手術の前にAVR/TAVIを優先する (class I, ACC/AHA 2020).\n'
        '・無症状重症ASでLVEF≥50%であれば周術期の血行動態管理を徹底した上で待機的手術を許容できる. ただしCAD合併, 中等度以上のMR, 肺高血圧合併は追加リスクとして把握する.\n'
        '・重症AS患者, 特に伝導障害 (左脚ブロック, PR延長) 合併例やAVR/TAVI後早期の例では, 入室前に体外ペーシングパッドを貼付しておく. 高度房室ブロックの既往やTAVI周術期の症例では, 術前に循環器内科へ経静脈ペーシング (頸静脈アプローチ) 留置の要否を確認する.\n'
        '・観血的動脈圧ラインは導入前に確保する. 中等度リスク以上の手術では中心静脈カテーテル, 高リスク手術や低心機能合併例では肺動脈カテーテルまたは術中TEEを準備する.\n'
        '・フェニレフリン, ノルアドレナリンを希釈済みシリンジで手元に用意する. 出血が想定される術式では輸血準備を行い, 除細動器を即時使用可能な位置に配置する.\n'
        '・低流量低圧較差ASや心不全合併例では, 術前に循環器外科へのコンサルトの要否, 緊急ECMO導入体制 (灌流士・外科医の待機) を確認しておく.\n'
        '\n'
        '■麻酔計画\n'
        '・導入は緩徐に行い, 十分な鎮痛を先行させたオピオイド主体の麻酔とする. 挿管刺激による頻脈・高血圧と, 麻酔薬による急激なSVR低下による低血圧の双方を避ける. プロポフォールは単回投与を避け少量分割または持続投与で滴定する.\n'
        '・区域麻酔は禁忌ではないが, 交感神経遮断による急激な前負荷・後負荷低下を避けるため単回脊髄くも膜下麻酔は原則避ける. 硬膜外麻酔を用いる場合は高濃度局所麻酔薬の単回投与を避け, 希釈局所麻酔薬とオピオイドの併用で効果をゆっくり立ち上げる.\n'
        '・体位変換, 気腹, 出血などSVRが急変しうる場面を外科医とあらかじめ共有し, 血管収縮薬の先行投与で予防的に対応する.\n'
        '\n'
        '■静注薬による対応\n'
        '・第一選択はフェニレフリン (単回50-100μg, 持続0.3-1.5μg/kg/分) である. 純粋なα1刺激薬で心拍数を上げずに末梢血管抵抗を回復させ, 冠灌流圧を保ちながら心筋酸素需要を増やさないため, ASの後負荷固定病態と最も相性が良い.\n'
        '・ノルアドレナリン (0.03-0.3μg/kg/分) はβ1作用も併せ持ち, 低心機能合併例やフェニレフリンの反射性徐脈が望ましくない場合の代替として用いる.\n'
        '・エフェドリンは心拍数上昇を招くため基本的に避ける. イソプロテレノールなど純β刺激薬も頻脈を助長するため禁忌に近い.\n'
        '・容量負荷にもかかわらず心拍出量が確保できない, または慢性肺高血圧・右心機能低下を合併する例では, ドブタミンやミルリノンなど強心薬を少量から追加するが, 過度な陽性変時作用は避ける.\n'
        '・非代償性急性心不全ではニトログリセリンによる前負荷軽減や瀉血を併用しつつ, 血圧を保ちながら心機能改善を図る.\n'
        '・新規AF/SVTを発症した場合は薬物的レートコントロールを待たず早期の同期下カルディオバージョンを検討する. ASでは心拍出量の心房収縮依存度が高く, 血行動態破綻が急速に進むためである.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '・除細動/ペーシングパッドの事前貼付: 重症AS全例, 特にAVR/TAVI関連手術, 高度伝導障害合併例, 心房細動既往例では入室後速やかに, 可能なら入室前に貼付する.\n'
        '・術前の経静脈ペーシング留置: 高度房室ブロック既往, TAVI後早期, 弁輪部深部への手技が予定される症例では, 頸静脈アプローチによる経静脈ペーシングリードの事前留置を循環器内科に依頼する.\n'
        '・新規発症の心房細動・上室頻拍で血行動態が破綻した場合は同期下カルディオバージョン (100-200J二相性) を速やかに行う. 心室細動/無脈性心室頻拍では非同期除細動 (150-200J二相性) を直ちに行う.\n'
        '・迷走神経刺激手技や頸動脈マッサージは徐脈を助長し心拍出量をさらに低下させうるため, ASでの上室頻拍に用いる際は血行動態を見ながら慎重に行う.\n'
        '・IABPは中等度以上のAR合併では禁忌に近く, ASでは有効性が限定的だが低心機能合併例の橋渡しとして考慮しうる. 重症ASに伴う難治性肺水腫・心原性ショックでは, バルーン大動脈弁形成術 (BAV) をTAVI/AVRへの橋渡しとして考慮する.\n'
        '・薬剤抵抗性の心停止・循環虚脱に至った場合はVA-ECMO導入の閾値を早めに設定し, 灌流回路・カニュレーション要員をあらかじめ院内で確保しておく.\n'
        '・TAVI後は房室ブロックの遅発性発症があるため, 術後は少なくとも24-48時間の心電図モニタリングと一時ペーシングリードの留置状況確認を行う.\n'
        '\n'
        '■トラブル時の初動\n'
        '・急激な低血圧を認めたら, まず外科刺激を一時中断し100%酸素とし, フェニレフリンをボーラス投与する. 同時に心電図でリズムを確認する.\n'
        '・徐脈が主因であればアトロピン単独よりも先にフェニレフリン投与で血圧を保ちつつ, 過度な頻脈化を避けながら心拍数を評価する.\n'
        '・新規AF/SVTで血圧が保てない場合は薬物治療を待たず直ちに同期下カルディオバージョンを行う.\n'
        '・ASでは固定弁口による前方拍出制限のため胸骨圧迫による心拍出量が通常以上に得られにくい. 心停止に至った場合は早期の除細動・エピネフリン投与に加え, 反応不良であれば速やかにECMO導入を判断する.\n'
        '・原因検索として出血, アナフィラキシー, 迷走神経反射, 気腹による静脈還流低下などを並行して除外する.\n'
        '\n'
        '■出典\n'
        '・2020 ACC/AHA Guideline for the Management of Valvular Heart Disease (Circulation. 2021)\n'
        '・2020年改訂版 弁膜症治療のガイドライン (日本循環器学会/日本胸部外科学会/日本血管外科学会/日本心臓血管外科学会)\n'
        '・稲冨佑弦 編. 50の術式と疾患で学ぶ心臓麻酔. 克誠堂出版, 2022',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: '僧帽弁狭窄 (MS) と僧帽弁逆流 (MR) の麻酔管理',
    color: _cCardiac,
    tags: const ['循環器', '弁膜症', '僧帽弁狭窄', '僧帽弁逆流'],
    body: '■病態の要点\n'
        '・僧帽弁狭窄 (MS) は左房から左室への流入障害であり, 左室前負荷が僧帽弁口によって規定される"固定された前負荷"病態である. 頻脈は拡張期充満時間を短縮し左房圧を急上昇させ肺水腫を招く.\n'
        '・慢性の左房圧上昇は肺高血圧, 右室機能低下, 三尖弁逆流, 心房細動を惹起する. MSでは心房収縮が左室充満の約30%を担うため, 洞調律の喪失は心拍出量を大きく低下させる.\n'
        '・僧帽弁閉鎖不全 (MR) は逆流により前方拍出が減少する病態で, 後負荷 (SVR) の上昇は逆流率を増加させ前方拍出をさらに減少させる. 適度な後負荷低下は逆流を減らし前方拍出を増やす.\n'
        '・MRでは徐脈により拡張期の逆流時間が延長し左室容量負荷が増大するため, 適度な頻脈がむしろ有利に働くことがあり, MSとは正反対の血行動態管理が必要になる.\n'
        '・二次性MR (機能性MR) は虚血性心疾患や心筋症による左室リモデリングが主因であり, 原疾患の心不全治療 (β遮断薬, ACE阻害薬, ミネラルコルチコイド受容体拮抗薬) が前提となる.\n'
        '\n'
        '■術前の評価と準備 (リスクヘッジ)\n'
        '・MSでは心エコーで僧帽弁口面積 (MVA), 平均圧較差, 肺動脈圧, 右室機能を評価する. 重症MS (MVA<1.0cm2) で有症状, または中等症以上で肺高血圧 (収縮期肺動脈圧≥50mmHg) を合併する場合は待期的非心臓手術前の弁治療 (PTMC/外科手術) を検討する.\n'
        '・心房細動の有無, 抗凝固療法 (ワルファリン) の継続状況, 左房内血栓の有無を確認する. 区域麻酔を予定する場合はINRと休薬期間を事前に確認する.\n'
        '・MRでは一次性か二次性かを鑑別しLVEF, 左室収縮末期径 (Ds) を確認する. Ds>40-45mmやLVEF<60%は周術期リスクが高い指標として把握する.\n'
        '・MS/MRいずれも心房細動の頻度が高く, 新規発症・増悪時に速やかなレートコントロールとカルディオバージョンを行えるよう, 入室後早期に除細動パッドを貼付しておく.\n'
        '・重症MSで高度肺高血圧合併例, 二次性MRで低左心機能合併例では, 観血的動脈圧に加え中心静脈圧, 可能であれば肺動脈カテーテルまたは術中TEEを準備する.\n'
        '・房室ブロックのリスクがある弁輪部石灰化の強い非リウマチ性MSや再手術例では, 体外ペーシングパッドの事前貼付に加え, 高度徐脈のリスクを麻酔科・外科・循環器内科であらかじめ共有する.\n'
        '・β遮断薬内服中の患者は手術当日まで継続する. レートコントロール目的のジゴキシン, カルシウム拮抗薬の内服状況も確認する.\n'
        '\n'
        '■麻酔計画\n'
        '・MSでは頻脈を来す侵襲 (挿管, 執刀) の直前に十分な鎮痛を確保し麻酔深度を安定させる. 容量負荷による前負荷増加は肺水腫を助長するため輸液は少量ずつ慎重に行う.\n'
        '・MRでは適度な血管拡張が前方拍出を助けるため全身麻酔・区域麻酔とも比較的耐用性が良い. ただし前負荷は維持し徐脈を避ける.\n'
        '・両疾患とも洞調律の維持が重要であり, 麻酔深度は頻脈・徐脈いずれも来さないよう安定させる.\n'
        '・機能性MRでは基礎心疾患 (虚血性心疾患・心筋症) の管理を並行し, 過度な交感神経刺激を避けるため十分な鎮痛を確保する.\n'
        '\n'
        '■静注薬による対応\n'
        '・MSでは血管収縮薬 (フェニレフリンまたはノルアドレナリン) で末梢血管抵抗を維持しながら冠灌流圧を保つ. 前負荷増加による心拍出量増加が見込みにくいため, 輸液よりも血管収縮薬による血圧維持を優先する.\n'
        '・MSの心拍数管理は動脈圧・肺動脈圧をモニタリングしながら60-80/分を目安に, ランジオロールなど短時間作用型β遮断薬で調整する.\n'
        '・MSで新規AF, 頻脈性AFを来した場合はまずレートコントロール (β遮断薬静注, ジゴキシン) を試みるが, 血行動態が破綻していれば直ちに同期下カルディオバージョンへ移行する.\n'
        '・MRでは後負荷軽減が有利であり, 血圧低下時は純粋な血管収縮薬よりも軽度のβ作用を併せ持つノルアドレナリンの少量投与, または血管拡張作用のあるドブタミン・ミルリノン・オルプリノンなどのイノデュレーターを優先する.\n'
        '・二次性MRや低左心機能合併の重症MRでは, 人工心肺離脱時や術後循環管理にドブタミン (2-10μg/kg/分) やミルリノン (0.25-0.75μg/kg/分, 負荷投与50μg/kgを10分で) などのPDE3阻害薬を用い, 後負荷軽減と心収縮力増強を図る.\n'
        '・MRで避けるべきは純粋なα刺激薬単独投与であり, 後負荷を急上昇させ逆流を増悪させるため使用は最小限にとどめる.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '・除細動パッドの事前貼付: MS/MRいずれも心房細動の頻度が高く, 特にMSは新規AFで急速に血行動態が破綻するため, 入室後早期にパッドを貼付し, 同期下カルディオバージョン (心房細動100-150J二相性, 心房粗動50-100J二相性) を即座に行える体制を整える.\n'
        '・房室ブロックリスクの高い症例 (高度弁輪石灰化, 再手術, 刺激伝導系近傍の手技) では, 術前に頸静脈アプローチでの経静脈ペーシングリード留置を循環器内科に依頼することを検討する.\n'
        '・術後心房細動の予防にはマグネシウム, カリウムの補正に加え, オーバードライブサプレッションを意識した心房ペーシングが有用である.\n'
        '・術中TEEでMSでは弁口面積・圧較差, MRでは逆流機序 (Carpentier分類) と部位診断, 縮流部幅 (vena contracta≥7mm), PISA (40cm/秒設定で半径≥10mm) による重症度確認を行い, Surgeon\'s viewで外科医に情報提供する.\n'
        '・肺高血圧合併例で右心不全が疑われる場合は一酸化窒素吸入などの肺血管拡張療法を考慮する.\n'
        '・待期手術前の重症MSでカテーテル治療 (PTMC) が適応となる例では, 弁治療の先行を循環器内科と協議する.\n'
        '\n'
        '■トラブル時の初動\n'
        '・MSで急激な低血圧・肺水腫を認めたら, まず頻脈の有無を確認し, 頻脈があればβ遮断薬で速やかにレートコントロールする. 同時に血管収縮薬で血圧を維持し過剰輸液を中止する.\n'
        '・MRで急激な低血圧を認めたら後負荷の急上昇がないか確認し, 血管拡張・イノデュレーターによる対応を優先する.\n'
        '・新規AFで血行動態が不安定な場合はいずれの疾患でも薬物治療を待たず同期下カルディオバージョンを行う.\n'
        '・重度の右心不全徴候 (CVP上昇, 低血圧) を認めた場合はPVR上昇要因 (低酸素, 高二酸化炭素血症, アシドーシス, 疼痛刺激) を是正し, 必要に応じてドブタミンやPDE3阻害薬で右心保護を行う.\n'
        '\n'
        '■出典\n'
        '・2020 ACC/AHA Guideline for the Management of Valvular Heart Disease (Circulation. 2021)\n'
        '・2020年改訂版 弁膜症治療のガイドライン (日本循環器学会ほか)\n'
        '・稲冨佑弦 編. 50の術式と疾患で学ぶ心臓麻酔. 克誠堂出版, 2022\n'
        '・JCS/JHFS 2025 Guideline on Diagnosis and Treatment of Heart Failure (Circulation Journal 2025)',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: '肥大型心筋症 (HCM/HOCM) の麻酔管理',
    color: _cCardiac,
    tags: const ['循環器', '心筋症', '肥大型心筋症', 'LVOTO'],
    body: '■病態の要点\n'
        '・肥大型心筋症 (HCM) は左室ないし右室心筋の肥大と拡張能低下を特徴とする心筋疾患であり, 左室壁厚15mm以上 (条件により13mm以上) で診断される. 左室流出路狭窄 (LVOTO) の有無により閉塞性 (HOCM) と非閉塞性に分類される.\n'
        '・LVOTOは安静時圧較差30mmHg以上を目安とするが, 安静時に有意でなくても運動や誘発で圧較差を認める例が多く, 圧較差は複数の因子で容易に変動する"動的狭窄"である.\n'
        '・LVOTO増悪因子は前負荷減少, 後負荷減少, 頻脈, 収縮力増強の4つであり, いずれもLVOT断面積をさらに狭小化させ, 収縮期前方運動 (SAM) による僧帽弁逆流 (MR) を悪化させる悪循環を生む.\n'
        '・SAMは左室駆出血流が僧帽弁前尖を心室中隔側へ押し上げるdrag effectが主因とされ, LVOT断面積のさらなる減少と加速血流を招く.\n'
        '・強心薬・カテコラミンはEFを高め心室内腔をさらに狭小化させるため禁忌に近い. 麻酔管理は"前負荷を保つ, 後負荷を下げない, 頻脈にしない, 過収縮にしない"の4原則に集約される.\n'
        '\n'
        '■術前の評価と準備 (リスクヘッジ)\n'
        '・安静時に有意な圧較差を認めない例ではバルサルバ手技や頭高位での負荷心エコーによりLVOTOの有無を確認しておく.\n'
        '・β遮断薬は手術当日も継続する. 内服中断は術中頻脈・LVOTO増悪の予防に反するため避ける.\n'
        '・SAMに伴うMRの程度, mitral complexの異常 (僧帽弁前尖の過長, 乳頭筋位置異常) を事前に把握しておく.\n'
        '・ICD植込み患者では, 電気メスによる誤作動やペーシング抑制の可能性があるため, 術前にデバイスのプログラムでICD頻拍治療機能の一時無効化 (マグネットまたはプログラマー) と, 術中の外部除細動パッド貼付・体外ペーシング体制を確認する. 無効化中は必ず外部除細動器を即使用可能な状態にしておく.\n'
        '・薬物治療抵抗性で圧較差50mmHg超の症候性例では, 術前に循環器内科・心臓血管外科に中隔縮小術 (外科的中隔心筋切除術またはアルコール中隔焼灼術) の適応を相談しておく.\n'
        '・観血的動脈圧ラインを導入前に確保する. 動脈圧波形はLVOTOに特徴的なspike-and-dome patternを呈するため, 術中のLVOTO評価に有用であることを念頭に置く.\n'
        '・術前絶飲食時間が長くなる場合は補液を行い, 麻酔導入時点で循環血液量を減らさないようにする.\n'
        '\n'
        '■麻酔計画\n'
        '・導入は緩徐に行う. プロポフォールは単回投与を避け持続投与で滴定し, レミフェンタニルなどのオピオイドを併用して挿管刺激による頻脈・カテコラミン分泌を徹底して抑える.\n'
        '・区域麻酔, 特に単回脊髄くも膜下麻酔は交感神経遮断による急激な前負荷・後負荷低下を招きLVOTOを増悪させるため原則として避ける. 硬膜外麻酔を用いる場合は希釈局所麻酔薬を少量ずつ滴定する.\n'
        '・輸液はやや多めを許容し血管内容量を保つ. ただし過剰輸液は術後抜管遅延, 胸水貯留につながるため必要最小限にとどめる.\n'
        '・抜管時の頻脈もLVOTO再燃の契機となるため, デクスメデトミジン持続投与下での抜管を選択肢とする.\n'
        '\n'
        '■静注薬による対応\n'
        '・低血圧時の第一選択はフェニレフリン (持続0.5-1.5mg/時, または単回50-100μg) である. 純粋なα1刺激薬 (pure α stimulant) であり心拍数を上げずに後負荷を回復できるため, HOCMの生理に最も合致する.\n'
        '・ノルアドレナリンは軽度のβ作用があり頻脈を助長しうるため, フェニレフリンで管理困難な場合の代替とする.\n'
        '・過収縮や頻脈を認める場合は陰性変時・変力作用を期待して短時間作用型β遮断薬を用いる. 第一選択はランジオロールであり, それでも過収縮によるLVOTO増悪が持続する場合にエスモロールへの変更を検討する. エスモロールはランジオロールより半減期が長く陰性変力作用が強く出ることがあるため, まずランジオロールから開始する.\n'
        '・ドブタミン, ミルリノン, アドレナリンなどのカテコラミン・強心薬は収縮力増強によりLVOTOを悪化させるため, 人工心肺離脱時の特別な評価目的以外は原則として投与しない. 循環虚脱時であっても安易な強心薬投与は避け, まず輸液とフェニレフリンで対応する.\n'
        '・術中に心房細動を発症した場合は, 拡張障害のある左室でatrial kickの喪失が致命的となりうるため, 薬理学的あるいは電気的除細動の閾値を下げ早期の洞調律復帰を図る. 血清カリウム・マグネシウム値の是正も併せて行う.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '・全例で入室後早期に除細動/ペーシングパッドを貼付する. ICD患者では特に, デバイス無効化中の外部バックアップとして必須である.\n'
        '・ICD植込み患者の周術期管理: 電気メス使用時はICDの頻拍治療機能を一時的に無効化し, 電気メスの使用も最小限にとどめることを考慮する. 無効化中は必ず外部除細動パッドを貼付し, 経皮ペーシング機能付き除細動器をベッドサイドに配置する.\n'
        '・術中は観血的動脈圧波形のspike-and-dome patternの変化からLVOTOの増悪を早期に察知する.\n'
        '・大動脈遮断解除後のTEEで中隔切除とmitral complexへの操作の効果を評価する. 圧較差が残存する場合は中隔切除不足やmitral complex修復不成功を疑う.\n'
        '・薬物治療抵抗性かつ症候性 (NYHA III/IV) で圧較差50mmHg超の例では外科的中隔心筋切除術, 手術リスクが高い例ではアルコール中隔心筋焼灼術 (PTSMA) を非心臓手術に先行して検討する.\n'
        '・術後は突然の心室性不整脈のリスクを念頭に置き, 少なくとも術直後は連続心電図モニタリングを継続する.\n'
        '\n'
        '■トラブル時の初動\n'
        '・急激な低血圧を認めたらまず頻脈化を避けつつフェニレフリンを速やかに投与し, 輸液を追加する. 強心薬の反射的投与は避ける.\n'
        '・頻脈を認めたら十分な鎮痛を確認した上でランジオロールを追加投与する.\n'
        '・新規AFで血行動態が破綻した場合は薬物治療を待たず早期に同期下カルディオバージョンを行う.\n'
        '・心停止時は通常の心肺蘇生アルゴリズムに従うが, LVOTOが循環虚脱の主因である可能性を常に念頭に置き, 胸骨圧迫中も輸液とフェニレフリンでの前負荷・後負荷維持を並行する. 自己心拍再開後は不要な高用量カテコラミン持続投与は避ける.\n'
        '・ICD植込み患者で頻拍治療が作動すべき状況になった場合, デバイスが無効化されていれば外部除細動器での対応に直ちに移行する.\n'
        '\n'
        '■出典\n'
        '・2024 AHA/ACC/AMSSM/HRS/PACES/SCMR Guideline for the Management of Hypertrophic Cardiomyopathy (Circulation, 2024)\n'
        '・稲冨佑弦 編. 50の術式と疾患で学ぶ心臓麻酔. 克誠堂出版, 2022',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: '心不全 (HFrEF) ・拡張型心筋症患者の麻酔管理',
    color: _cCardiac,
    tags: const ['循環器', '心不全', '拡張型心筋症', '強心薬'],
    body: '■病態の要点\n'
        '・HFrEF (左室駆出率が低下した心不全) は収縮能低下により心拍出量の維持が前負荷に依存する状態 (preload dependent) であり, 同時にわずかな後負荷上昇でも左室拡張末期圧・容積が上昇しやすい状態 (afterload sensitive) である.\n'
        '・代償として交感神経系が持続的に亢進しており体血管抵抗を保つことで血圧を維持している. 一方で心臓β受容体のdown regulationにより外因性カテコラミンへの反応性は健常人より低下している.\n'
        '・麻酔薬による急激な交感神経遮断・血管拡張は容易に低血圧, 冠灌流圧低下, さらなる心機能低下という悪循環を招く.\n'
        '・拡張型心筋症 (DCM) は特発性の収縮不全を主体とする心筋症であり, 二次性MR (機能性MR) や心室性不整脈, 伝導障害 (CRT適応) を合併しやすい.\n'
        '\n'
        '■術前の評価と準備 (リスクヘッジ)\n'
        '・NYHA分類, 直近の心不全増悪歴, NT-proBNP, LVEF, 右心機能, 肺高血圧の有無を確認する. 強心薬依存の有無など重症度 (J-MACS/INTERMACS profile相当) を把握しておく.\n'
        '・内服薬の継続/休薬: β遮断薬は手術当日まで継続する. 急な中止は反射性頻脈・虚血・不整脈のリスクを高める. ACE阻害薬/ARB/ARNI (サクビトリルバルサルタン) は術中の高度な血管拡張・難治性低血圧を助長しうるため, 中等度リスク以上の手術では前日または当日朝の内服を中止する施設が多い. ただし重症HFrEFで内服中断が心不全増悪に直結すると判断される場合は継続も選択肢であり, 麻酔科・循環器内科・患者背景を踏まえ個別に判断する. SGLT2阻害薬は周術期の正常血糖ケトアシドーシスのリスクがあるため術前3-4日前から休薬する.\n'
        '・CRT/ICD植込み患者では, デバイス情報 (適応, 設定, 電池残量, 最終作動歴) を確認し, 電気メス使用に伴う頻拍治療機能の一時無効化, 経皮ペーシング対応可能な除細動器の準備, ペースメーカー依存例でのペーシング設定変更の要否を術前にデバイス業者・循環器内科と確認する.\n'
        '・入室後早期に除細動/ペーシングパッドを貼付する. 特にICD無効化予定例, 心室性不整脈既往例では必須である.\n'
        '・強心薬持続静注中の症例や補助循環装着例 (IABP, Impella, VA-ECMO, LVAD) では, 術前に循環器内科・心臓血管外科・臨床工学技士を含むハートチームで評価し, 周術期の補助循環継続・増強方針をあらかじめ決めておく.\n'
        '・観血的動脈圧ラインを導入前に確保する. 中等度リスク以上の手術では中心静脈カテーテルおよび術中TEE, 高リスク例では心拍出量モニタまたは肺動脈カテーテルを準備する.\n'
        '\n'
        '■麻酔計画\n'
        '・導入はオピオイド主体とし少量の鎮静薬 (ミダゾラムなど) を併用して血行動態変動を最小化する. 揮発性麻酔薬・プロポフォールは容量血管拡張と体血管抵抗低下により血圧低下を来しやすいため緩徐に滴定する.\n'
        '・前負荷を維持するため急激な体位変換 (頭低位など) は避け, 前負荷減少に対しては適度な輸液で対応する. ただし急激な輸液負荷はFrank-Starling下行脚への移行を招くため少量ずつ評価しながら行う.\n'
        '・麻酔導入から侵襲的処置開始までは十分な麻酔深度を保ち, 疼痛刺激による急激な後負荷上昇を避ける.\n'
        '・術中は少なくとも1時間ごとの循環評価 (動脈圧波形, 心拍出量, 乳酸値) を行い, 早期に強心薬・血管作動薬を調整する.\n'
        '\n'
        '■静注薬による対応\n'
        '・ドブタミン (2-10μg/kg/分, 最大20μg/kg/分) はβ1刺激による陽性変力・軽度血管拡張作用を持つ第一選択の強心薬である. ただし長期使用は予後悪化との関連が指摘されており必要最小用量, 最短期間の使用にとどめる.\n'
        '・ミルリノン (負荷投与を行う場合50μg/kgを10分かけて, 維持0.25-0.75μg/kg/分) はPDE3阻害薬でありβ受容体を介さないため, β遮断薬内服中やカテコラミン抵抗性の症例でも有効である. 後負荷軽減も期待できるが腎排泄のため腎機能障害例では減量し, 低血圧・新規不整脈に注意する.\n'
        '・オルプリノンはミルリノンと同じPDE3阻害薬で日本で頻用される. 維持量0.1-0.3μg/kg/分を目安に血管拡張・陽性変力作用を期待して用いる.\n'
        '・ノルアドレナリン (0.03-0.3μg/kg/分) は輸液を十分に行っても血圧が保てないショック例, 特に末梢血管拡張が主体の病態で第一選択となる. 心原性ショックのサブグループでは死亡率低下と不整脈減少が報告されている.\n'
        '・ドパミンは腎保護目的での有用性は否定されており, HFrEF/HFmrEFで腎機能障害がある場合の利尿補助以外には積極的な適応はない.\n'
        '・強心薬・血管作動薬はいずれも必要最小用量・最短時間を原則とし, 漫然とした高用量投与は避ける.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '・除細動/ペーシングパッドの事前貼付: 全例, 特にICD植込み例, 心室性不整脈既往例, CRT-D植込み例では入室後速やかに貼付する.\n'
        '・CRT植込み患者では電気メスによるペーシング抑制やモード変化に注意し, 非同期モードへの一時変更や磁石対応の要否を事前にデバイス業者と確認する.\n'
        '・IABPは後負荷軽減と冠灌流圧補助を目的に, カテコラミン抵抗性の低心拍出状態で導入を検討する. 中等度以上のARがあれば禁忌である.\n'
        '・Impella (経皮的左室補助) は薬物治療抵抗性の心原性ショック (J-MACS/INTERMACS profile 1-2) で早期導入により転帰改善が示されており, IABPで改善が乏しい場合の次段階として考慮する.\n'
        '・VA-ECMOは循環虚脱が急速に進行する場合, 心停止や重症心原性ショックへの導入閾値を術前から施設内で共有しておく. 緊急カニュレーションに備え灌流士・外科医の待機体制を確認する.\n'
        '・LVAD装着患者の非心臓手術では, ポンプ流量・脈圧の変化から前負荷不足やRV不全を早期に察知し, 過度の前負荷増大 (トレンデレンブルグ体位) を避ける.\n'
        '・モニタリング: 観血的動脈圧, 中心静脈圧に加え, 高リスク例では術中TEEまたは肺動脈カテーテルによる心拍出量・肺動脈楔入圧の連続評価を行う.\n'
        '\n'
        '■トラブル時の初動\n'
        '・急激な低血圧を認めたら, まず容量不足か後負荷上昇かを鑑別し, 前負荷不足が疑われれば少量ずつ輸液, 血管拡張が主因であればノルアドレナリンを優先する.\n'
        '・低心拍出状態が輸液・血管作動薬で改善しない場合はドブタミンまたはミルリノン/オルプリノンを追加する.\n'
        '・新規の心室性不整脈, 心室細動を認めた場合は速やかに非同期除細動を行う. ICD/CRT-D植込み例でデバイスが無効化されている場合は外部除細動器での即時対応に切り替える.\n'
        '・薬物治療・電気治療に反応しない循環虚脱では早期にIABP, Impella, VA-ECMO導入の要否をハートチームで判断する.\n'
        '\n'
        '■出典\n'
        '・JCS/JHFS 2025 Guideline on Diagnosis and Treatment of Heart Failure (Circulation Journal 2025)\n'
        '・2020 ACC/AHA Guideline for the Management of Valvular Heart Disease (Circulation, 2021)\n'
        '・稲冨佑弦 編. 50の術式と疾患で学ぶ心臓麻酔. 克誠堂出版, 2022',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: '虚血性心疾患・冠動脈ステント留置後患者の麻酔管理',
    color: _cCardiac,
    tags: const ['循環器', '虚血性心疾患', '冠動脈ステント', '抗血小板薬'],
    body: '■病態の要点\n'
        '虚血性心疾患患者, とくに冠動脈ステント留置後の患者では, 周術期における最大の課題は "抗血小板薬を止めて出血を減らすか, 続けてステント血栓症を防ぐか" のバランスである. 心筋酸素需給不均衡(頻脈, 低血圧または高血圧, 貧血, 低体温, 疼痛による交感神経緊張)は虚血の主要な誘因であり, 麻酔管理全体を通じてこれを最小化することが基本方針になる.\n'
        '\n'
        '■術前の評価と準備(リスクヘッジ)\n'
        '・ステント種類(BMS/DES/薬剤コーティングバルーンDCB), 留置日, 適応(安定CAD/ACS), DAPT(アスピリン+P2Y12阻害薬)の継続状況を確認する.\n'
        '・JCS 2020フォーカスアップデートでは, 待機的非心臓手術はステント留置後1か月以内は施行しない(Class III Harm). BMSは1か月以上, できれば3か月以上, POBA単独は2週間以上, できれば1か月以上の延期を推奨する.\n'
        '・DES留置後は低血栓リスク例で3か月以上, 高血栓リスク(ACSでのPCI, 複雑病変へのPCI)例では6か月以上の延期が望ましい(Class I B / IIa B).\n'
        '・アスピリンは出血リスクが許容できる限り周術期も継続し, 術後は24-72時間以内に再開する(Class I B). P2Y12阻害薬は中止するならチカグレロル3日, クロピドグレル5日, プラスグレル7日前を目安にする(Class IIa B). 抗血小板薬の周術期ヘパリン置換(ブリッジ)は推奨されない(Class III No benefit).\n'
        '・出血リスクを低/中/高で分類し, 個々の血栓リスクと突き合わせて継続方針を決める. 脊髄くも膜下麻酔, 頭蓋内, 眼後房手術など出血が致命的になり得る術式では高血栓リスクでもDAPTを中止する.\n'
        '・循環器内科, 外科, 麻酔科によるハートチームでの術前カンファレンスを組む(Class IIa C). ステント後1か月以内の緊急/準緊急手術は24時間カテ室対応可能な施設で行う.\n'
        '・入室前に: 12誘導様式(II, V5相当)のST解析付きモニタを準備し, ハイリスク例(左主幹部病変, 高度左室機能低下, 最近のACS)ではTEEプローブを用意する. 除細動パッドをあらかじめ貼付しておく. 循環器内科当直医とカテ室の待機体制を確認し, 緊急PCI搬送経路を共有しておく. 高度左室機能低下や血行動態不安定例では術前IABP挿入または大腿動脈シース確保を検討する.\n'
        '\n'
        '■麻酔計画\n'
        '末梢神経ブロック単独で完結できる術式ではDAPT継続下でも施行しやすい. 硬膜外・脊髄くも膜下麻酔はP2Y12阻害薬の休薬が前提になる. 導入は頻脈・血圧変動を避けて緩徐に行い, 喉頭鏡刺激前にオピオイドを十分効かせる. 維持は普段の血圧の±20%以内, 心拍数60-80/分程度を目標にする.\n'
        '\n'
        '■静注薬による対応\n'
        '・ニトログリセリン: 0.5-2μg/kg/分持続静注で前負荷軽減と冠攣縮予防. 低血圧に注意し, フェニレフリン併用で血圧を保ちながら使うこともある.\n'
        '・ランジオロール: 頻脈時に1μg/kg/分から開始し漸増(超短時間作用性β1選択性, 心収縮力低下例では慎重投与).\n'
        '・フェニレフリン: 頻脈を伴わない低血圧に単回50-100μg, 反射性徐脈に注意. 持続なら0.1-0.5μg/kg/分.\n'
        '・頻脈合併の低血圧にはノルアドレナリン0.02-0.2μg/kg/分を選択する.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '12誘導様式のSTモニタは全例必須, ハイリスク例はTEEで新規壁運動異常を早期に捉える. 除細動パッドの事前貼付は, 側臥位・腹臥位など緊急時アクセスが困難な体位の手術, 高度左室機能低下例, 最近のACS例で特に重要である. IABPは血行動態不安定な冠動脈疾患, 左主幹部病変, EF30%未満の高リスク症例で術前挿入を検討する. 循環器内科・カテ室への連絡体制と緊急搬送手順を事前に確立しておく.\n'
        '\n'
        '■トラブル時の初動\n'
        'ST変化が出現した場合の具体的な対応(FiO2, HR/BP最適化, 冠攣縮への対処, IABP/緊急PCI判断)は次項の "術中心筋虚血への対応" に準拠する.\n'
        '\n'
        '■出典\n'
        'JCS 2020 Guideline Focused Update on Antithrombotic Therapy in Patients With Coronary Artery Disease(Circ J 2020)/ JCS 2022 Guideline Focused Update on Diagnosis and Treatment in Patients With Stable Coronary Artery Disease/ 術中低血圧予測モニター使用指針2023(日本麻酔科学会, 日本心臓血管麻酔学会)',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: '術中心筋虚血(ST変化)への対応',
    color: _cCardiac,
    tags: const ['循環器', '術中虚血', '冠攣縮', 'ST変化'],
    body: '■病態の要点\n'
        '術中のST変化は "需給不均衡型" (頻脈, 低血圧, 貧血, 低体温による酸素供給低下)と "血栓性冠動脈閉塞型" (ステント血栓症, プラーク破綻)で対応が大きく異なる. 冠攣縮性狭心症は正常冠動脈でも夜間・早朝安静時に多いが, 全身麻酔下では自律神経バランスの変化や機械的刺激で誘発されることがある. ST上昇は貫壁性(閉塞性)虚血を, ST低下は主に心内膜下虚血(需給不均衡)を示唆する. II, III, aVF上昇は下壁(右冠動脈), V1-4上昇は前壁(左前下行枝), I, aVL, V5-6上昇は側壁(回旋枝)領域の虚血を反映する.\n'
        '\n'
        '■術前の評価と準備(リスクヘッジ)\n'
        '虚血性心疾患・冠動脈ステント患者では入室前に12誘導様式のST解析付きモニタとTEEプローブを準備し, 除細動パッドを貼付しておく. ニトログリセリン, ヘパリン, ジルチアゼム, ニコランジルなど緊急時静注薬を手元にそろえ, 循環器内科医とカテ室の待機状況, 緊急PCI搬送経路を事前に共有しておく.\n'
        '\n'
        '■静注薬による対応\n'
        '即座にやること\n'
        '・FiO2を100%に上げる.\n'
        '・頻脈があれば心拍数を下げる: β遮断禁忌がなければランジオロール1μg/kg/分から開始.\n'
        '・低血圧なら昇圧(フェニレフリン単回50-100μg, またはノルアドレナリン0.02-0.2μg/kg/分), 高血圧なら鎮痛を深め前負荷を軽減する.\n'
        '・ニトログリセリン持続静注0.5-2μg/kg/分を開始し, 収縮期血圧90mmHg以上を保ちながら漸増する.\n'
        '・血栓性閉塞が疑われる場合は外科医と相談のうえヘパリン50-100単位/kg静注を検討する(出血リスクとの兼ね合いが必要).\n'
        '・貧血を補正する(目標Hbは個別化するが8-10g/dL以上を目安に).\n'
        '\n'
        '冠攣縮への対応\n'
        '・ニトログリセリン100-200μg単回静注, 効果不十分なら持続静注へ切り替える.\n'
        '・ニコランジル4-6mg静注後2mg/時で持続(硝酸薬抵抗性の冠攣縮に日本で汎用されるATP感受性Kチャネル開口薬).\n'
        '・ジルチアゼム10mgを3分程度かけて緩徐静注, 反復可, その後5-10mg/時で持続. 房室伝導障害・低血圧に注意する.\n'
        '・難治例には硫酸マグネシウム1-2g静注を追加する(torsades de pointes合併時にも有用).\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '・循環器医へのコールと術式の中断・短縮を外科医に申し出る.\n'
        '・TEEで新規の局所壁運動異常を確認し, 需給不均衡か血栓性かの鑑別材料にする.\n'
        '・薬物療法抵抗性で血行動態が破綻する, あるいは心原性ショックを合併する場合はIABP挿入を検討する.\n'
        '・血栓性閉塞が疑われST変化・血行動態破綻が遷延する場合は, 緊急PCIへの搬送をためらわない.\n'
        '・除細動パッド未貼付なら直ちに貼付し, VF/VTに備える.\n'
        '\n'
        '■トラブル時の初動\n'
        '①モニタ確認とアーチファクト除外, ②FiO2を上げる, ③HRとBPの最適化, ④ニトログリセリン開始, ⑤循環器医をコール, ⑥外科医に手術進行の一時中断を相談, ⑦TEEで評価, ⑧ヘパリン投与を検討, ⑨改善なければIABPまたは緊急PCIへの搬送を判断する, という順で対応する.\n'
        '\n'
        '■出典\n'
        'JCS/CVIT/JCC 2023 Guideline Focused Update on Diagnosis and Treatment of Vasospastic Angina(Coronary Spastic Angina)and Coronary Microvascular Dysfunction(Circ J 2023)/ JCS 2020 Antithrombotic therapy guideline/ JCS 2022 Stable CAD guideline',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: '肺高血圧症患者の麻酔管理',
    color: _cCardiac,
    tags: const ['循環器', '肺高血圧', '右心不全', '先天性心疾患'],
    body: '■病態の要点\n'
        '肺高血圧症(PH)の周術期リスクの本態は, 肺血管抵抗(PVR)上昇による右室後負荷増大とそれに続く急性右心不全である. 低酸素, 高CO2, アシドーシス, 低体温, 疼痛・浅麻酔による交感神経緊張, 過大な陽圧換気(高い気道内圧・肺過膨張)はいずれもPVRを急上昇させ, "PH crisis" から循環虚脱に至りうる. Eisenmenger症候群など右左短絡を合併する例ではPVR上昇がシャントを右左方向に逆転させ, 高度低酸素血症を招く.\n'
        '\n'
        '■術前の評価と準備(リスクヘッジ)\n'
        '・術前心エコーで右室機能, 推定肺動脈圧, 可能であれば右心カテーテル検査データ(mPAP, PVR, CI)とNT-proBNP, WHO機能分類を確認する.\n'
        '・循環器内科, 麻酔科, 外科による多職種カンファレンスで手術適応と個別リスクを評価する. 高リスク例は肺高血圧専門施設での実施とICU病床の確保を事前に確認する.\n'
        '・肺高血圧治療薬(PDE5阻害薬, エンドセリン受容体拮抗薬, プロスタサイクリン系)は中断せず継続する.\n'
        '・VA-ECMO対応可能な施設か確認し, 自施設で困難なら搬送体制をあらかじめ検討しておく.\n'
        '・入室前に除細動パッドを貼付し, 動脈ライン・中心静脈路を確保する準備をしておく.\n'
        '\n'
        '■麻酔計画\n'
        '導入は血管拡張・心抑制の強い薬剤の急速投与を避け緩徐に行う. 循環抑制が少ないエトミデートやオピオイドを主体とした導入を選択肢とする. 陽圧換気は1回換気量6-8mL/kgを目安に抑え, PEEPは必要最小限とし, 高いプラトー圧や肺の過膨張を避ける. 高CO2血症を許容する戦略(permissive hypercapnia)はアシドーシスを介してPVRを上げるため避ける. 疼痛・交感神経刺激を避けるため十分な鎮痛を行い, 可能な術式では気管挿管・陽圧換気を回避し自発呼吸下の区域麻酔で完結させることも検討する.\n'
        '\n'
        '■静注薬による対応\n'
        '・右心を守る昇圧: ノルアドレナリン0.02-0.3μg/kg/分を第一選択とする(冠灌流圧を保ちPVRへの影響が少ない). バソプレシン少量0.01-0.04単位/分は体血管を選択的に収縮しPVRに影響しにくく併用に有用.\n'
        '・右心収縮力低下にはドブタミン2-5μg/kg/分, またはミルリノン0.25-0.5μg/kg/分(負荷投与は血圧低下を招くため省略も可, 肺血管拡張作用も併せ持つ).\n'
        '・急性増悪時, 使用可能な施設ではエポプロステノール(静注プロスタサイクリン)を低用量から開始し漸増する.\n'
        '・吸入NO 10-20ppmを右心不全・PH crisis時に開始する. 選択的肺血管拡張が得られるが, 急な中止でリバウンド肺高血圧を招くため漸減して終了する.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '陽圧換気は低1回換気量・適正PEEPを基本とし, 過膨張を避ける. 極端な頭低位・腹臥位はPVR上昇と静脈還流障害を招くため体位変換は緩徐に行う. 薬物療法とiNOに反応しない急性右心不全, 心係数低下, 乳酸上昇, 尿量低下が持続する場合はVA-ECMO導入を早期に検討し, 反応をみすぎて待たない. 除細動・ペーシングパッドは全例で事前貼付し, 右心不全に伴う心室性不整脈・徐脈に備える.\n'
        '\n'
        '■トラブル時の初動(PH crisis)\n'
        'FiO2を100%に上げ, 過換気にはせず適正な換気でCO2とpHを整える. 疼痛・浅麻酔を是正し, 昇圧薬(ノルアドレナリン)で体血圧を維持して冠灌流圧を確保しつつ, iNOを開始または増量する. 右心不全が増悪すればミルリノンやドブタミンを追加する. 改善がなければ直ちに循環器医をコールし, VA-ECMO導入を検討する.\n'
        '\n'
        '■出典\n'
        'JCS/JPCPHS 2025 Guideline on Pulmonary Hypertension and Pulmonary Embolism/Deep Vein Thrombosis/ Pulmonary hypertension in adults with congenital heart defects(ACHDs)review part II(Cardiovasc Diagn Ther 2024)/ WHO clinical classification review(Simonneau, JACC 2019)',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: '術中の低血圧・循環虚脱の鑑別とアプローチ',
    color: _cCardiac,
    tags: const ['循環器', '術中低血圧', '循環虚脱', 'アナフィラキシー'],
    body: '■病態の要点\n'
        '術中低血圧・循環虚脱は "前負荷" "後負荷" "収縮力" "レート/リズム" "閉塞性(気胸, タンポナーデ, 肺塞栓)" の5系統で系統的に鑑別する. これにアナフィラキシーや局所麻酔薬中毒(LAST)のような薬剤関連の急変を加えて考える. 閉塞性ショックと薬剤性アナフィラキシー/LASTは進行が急激で, 数分の遅れが転帰を左右する.\n'
        '\n'
        '■術前の評価と準備(リスクヘッジ)\n'
        '・高リスク症例(高齢, 心疾患既往, 大量出血が予測される術式, 局所麻酔薬を大量に使用する予定のブロック)では動脈ラインとTEE/POCUSをあらかじめ準備しておく.\n'
        '・局所麻酔薬を使用するすべての手術室に20%脂肪乳剤(イントラリポス)を常備し, アドレナリンをすぐ使える場所に置く.\n'
        '・麻酔導入前に出血源, 体位, 手術操作(気腹, 用手圧排)を外科医と共有しておく.\n'
        '\n'
        '■静注薬による対応(病態別)\n'
        '・単純な血管拡張(麻酔薬による)にはフェニレフリン50-100μg単回を反復投与する.\n'
        '・徐脈傾向を伴う低血圧にはエフェドリン4-8mg単回(β1刺激で心拍数も維持できる).\n'
        '・血管拡張性ショック(敗血症性など)にはノルアドレナリン0.02-0.3μg/kg/分を持続投与する.\n'
        '・アナフィラキシー: アドレナリンが第一選択. 軽症-中等症は10-100μgを反応をみながら静注反復, 重症・循環虚脱では0.1mgから増量, 心停止に至れば通常のACLS用量1mgを静注する. 静脈路がなければ筋注0.3-0.5mg(0.01mg/kg)を大腿外側に. 十分な急速輸液(晶質液)を併用し, ヒスタミンH1/H2拮抗薬とステロイドは二次的治療と位置づける.\n'
        '・LAST(局所麻酔薬中毒): まず投与を中止し応援要請. 20%脂肪乳剤1.5mL/kg(体重70kgで約100mL)を1分かけて静注後, 0.25mL/kg/分(約1000mL/時)で持続投与を開始する. 5分後も循環が改善しなければ再度1.5mL/kgを投与し持続量を0.5mL/kg/分に倍増する. 総投与量の目安は最大12mL/kg. 痙攣にはベンゾジアゼピンを用い, 血圧・心拍が不安定な場合プロポフォールは使用しない. 不整脈治療にリドカインは用いない. アドレナリンは少量から通常のACLS用量で投与する.\n'
        '・高カリウム血症・大量輸血後の低イオン化カルシウム血症が疑われる場合は塩化カルシウムまたはグルコン酸カルシウムを静注する.\n'
        '・カテコラミン抵抗性の血管拡張性ショックにはバソプレシン0.01-0.04単位/分を追加する.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        'TEE/POCUSによる迅速評価は次の順で行う: ①左室内腔の虚脱(前負荷不足), ②右室拡大とD-shape(急性後負荷増大, 肺塞栓を示唆), ③心嚢液貯留と拡張期虚脱(タンポナーデ), ④左室収縮力低下(心不全, 虚血), ⑤下大静脈の虚脱/怒張. 気胸(緊張性)を疑えば患側の呼吸音減弱, 気道内圧上昇, 皮下気腫を確認し緊急脱気(穿刺)を行う. 術者には気腹圧の低下, 用手圧排の解除, 体位の水平化を申し出る. 出血性ショックには急速輸血を行い, 循環虚脱が遷延する場合はVA-ECMOの適応を検討し, 早期に導入可能な施設・チームへ連絡する.\n'
        '\n'
        '■トラブル時の初動\n'
        'ABCを確認しつつ, 気道内圧, 呼吸音, 皮膚色, 蕁麻疹, 直近投与薬剤を素早く見直す. TEE/POCUSがあれば直ちに評価し, 系統的鑑別に沿って原因群を絞り込む. 並行して適切な昇圧薬・輸液を開始し, 外科医と情報共有しながら原因の除去(圧排解除, 気腹圧低下, 止血)を進める.\n'
        '\n'
        '■出典\n'
        '局所麻酔薬中毒への対応プラクティカルガイド(日本麻酔科学会, 2017年6月制定)/ アナフィラキシーに対する対応プラクティカルガイド(日本麻酔科学会)/ 術中低血圧予測モニター使用指針2023(日本麻酔科学会, 日本心臓血管麻酔学会)',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: '術中心停止(ACLS)と麻酔科特有の原因への対応',
    color: _cCardiac,
    tags: const ['循環器', '術中心停止', 'ACLS', '悪性高熱症'],
    body: '■病態の要点\n'
        '術中心停止は市中心停止と異なり, 目撃・モニタ下での発生がほとんどであり, 原因の多くが麻酔科的に可逆的である. 迅速な胸骨圧迫の開始とアドレナリン投与を進めながら, 同時並行で麻酔科特有の原因(LAST, アナフィラキシー, 高カリウム血症, 悪性高熱症, 気胸, タンポナーデ, オピオイド/局所麻酔中毒, 低血糖, 空気/肺塞栓)を検索することが生存率を左右する.\n'
        '\n'
        '■術前の評価と準備(リスクヘッジ)\n'
        '・高リスク症例(重症ASA-PS, 局所麻酔薬を大量に使用する予定, 既知の不整脈疾患, 悪性高熱の既往・家族歴)には除細動パッドをあらかじめ貼付しておく.\n'
        '・脂肪乳剤とダントロレンの保管場所, 溶解・投与手順を手術室スタッフ全員が把握しておく.\n'
        '・腹臥位, 側臥位で行う手術では, 仰臥位に戻す具体的な手順とかかる時間をあらかじめ確認しておく.\n'
        '\n'
        '■静注薬による対応\n'
        '基本アルゴリズム(JRC/ACLSに準拠)\n'
        '・除細動適応リズム(VF/無脈性VT): 直ちに除細動(二相性150-200J, 機種の推奨値に従う), 2分間のCPRサイクルごとにリズムチェックする. 2回目の除細動後も持続すればアドレナリン1mgを静注し, 以降3-5分ごとに反復する. 3回目の除細動後も持続すればアミオダロン300mg(初回), 以降150mgを静注する. アミオダロンが使えなければリドカイン1-1.5mg/kgで代替してよい.\n'
        '・除細動非適応リズム(PEA/心静止): アドレナリン1mgを直ちに静注し, 以降3-5分ごとに反復する.\n'
        '・torsades de pointes疑いには硫酸マグネシウム1-2g静注, 難治性VT/VFにはニフェカラント0.15-0.3mg/kg静注も選択肢になる.\n'
        '\n'
        '麻酔科特有の可逆的原因への即時治療\n'
        '・LAST: 20%脂肪乳剤1.5mL/kgを1分で静注後0.25mL/kg/分で持続, 改善なければ再ボーラスし持続量を倍増(最大12mL/kg). アドレナリンは少量から.\n'
        '・アナフィラキシー: アドレナリンを増量投与(心停止なら通常のACLS用量1mg), 大量急速輸液を併用する.\n'
        '・高カリウム血症: グルコン酸カルシウムまたは塩化カルシウムを静注し, グルコース・インスリン, 過換気, 重炭酸で細胞内シフトを図る.\n'
        '・悪性高熱症: ダントロレン1mg/kg(できれば2mg/kg)を10分で静注し, 効果を10分ごとに再評価して同量を追加, 最大7mg/kgまで. 原因薬剤(揮発性麻酔薬, サクシニルコリン)を中止し静脈麻酔へ変更, 高流量酸素で分時換気量を2倍以上に過換気, 冷却生理食塩水(最大50-60mL/kg)投与と体表冷却, 高カリウム血症の治療と利尿を並行する.\n'
        '・緊張性気胸: 緊急脱気(穿刺)を行う. ・心タンポナーデ: 心嚢穿刺または開胸を検討する.\n'
        '・オピオイド中毒にはナロキソン, 局所麻酔中毒には脂肪乳剤を用いる. ・低血糖にはブドウ糖を静注する. ・空気/肺塞栓では左側臥位頭低位とし, 中心静脈カテーテルからの空気吸引を試みながら循環をサポートする.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '除細動エネルギーは二相性150-200J(単相性は360J)を基本とする. 開胸心マッサージは, 心臓手術直後・開胸手術中, 胸郭変形や大量血胸でCPRの効果が不十分な場合, タンポナーデが疑われ迅速な穿刺が困難な場合に適応となる. VA-ECMO(ECPR)は, LAST, 高カリウム血症, 低体温, 肺塞栓など可逆性が期待できる原因で通常のCPRに反応せず, 目撃ありでCPR開始が早く低灌流時間が短い症例が良い適応であり, 早期に専門チームへ連絡し, 自施設で対応できなければ搬送体制を確認する. 腹臥位での心停止は可能な限り速やかに仰臥位へ戻すことを優先するが, 戻すまでに時間を要する場合は両手掌基部で背側から胸骨相当部を圧迫する代替法が報告されている. 側臥位も同様に速やかに仰臥位へ戻す.\n'
        '\n'
        '■トラブル時の初動\n'
        '質の高い胸骨圧迫(100-120/分, 深さ5-6cm, 中断を最小化)を直ちに開始し応援を要請する. 麻酔薬投与を中止し100%酸素で気道確保する. リズムチェックでショック適応/非適応を判断し, 並行して麻酔科的視点で可逆的原因(直前投与薬剤, 体位, 出血, 気道内圧)を検索する. 改善が得られなければECMO導入を早期に検討する.\n'
        '\n'
        '■出典\n'
        '局所麻酔薬中毒への対応プラクティカルガイド(日本麻酔科学会, 2017)/ 悪性高熱症ガイドライン(日本麻酔科学会)/ アナフィラキシーに対する対応プラクティカルガイド(日本麻酔科学会)/ 術中心停止に対するプラクティカルガイド(日本麻酔科学会)/ ELSO Interim Guidelines for VA ECMO for Cardiac Failure',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: 'ペースメーカ・ICD植込み患者の周術期管理',
    color: _cCardiac,
    tags: const ['循環器', '不整脈', 'デバイス', '術中トラブル'],
    body: '■病態の要点\n'
        'CIED (cardiac implantable electronic device) にはPPM (恒久ペースメーカ), ICD (植込み型除細動器), CRT-P/D (心臓再同期療法), leadless PM, ILR (植込み型ループレコーダ)がある. NBGコードは5文字で, 1桁目ペーシング部位, 2桁目センシング部位, 3桁目応答様式 (I: 抑制, T: トリガ, D: 両方), 4桁目レートレスポンス, 5桁目マルチサイトペーシングを示す. 手術室内の電磁干渉 (EMI)をデバイスが自己興奮と誤認すると, PPMではペーシング抑制からアシストール, ICDでは不適切な頻拍治療 (ATP/ショック)を来しうる. CIED患者は基礎心疾患・不整脈リスクが高く, 循環変動そのものが致死性不整脈の誘因にもなる.\n'
        '\n'
        '■術前の評価と準備 (リスクヘッジ)\n'
        '・デバイス手帳と胸部X線でメーカー・機種・リード構成を確認する (ICDは太いショックコイル, CRTは冠静脈洞に第3のリード, leadless PMは右室内カプセル)\n'
        '・最終デバイスチェックがPPMで12か月, ICD/CRTで6か月を超えている, または電池残量不明なら術前に照会・点検を依頼する\n'
        '・12誘導心電図でペーシングスパイクの有無を確認し, ペーシング依存 (自己脈40/分未満または自己脈なし)かを評価する\n'
        '・磁石適用時の反応はメーカー・個体設定で異なるため, 事前にCIED担当医へ術式・体位・EMI発生部位を伝え, 磁石の効果と対応方針を確認する\n'
        '・磁石を手術室に常備し, 場所と使用法を全スタッフに周知する\n'
        '・ペーシング依存例かつへそより上の手術でモノポーラ電気メスを使う予定なら, 術前に非同期モード (VOO/DOOなど)への一時的リプログラミングを依頼する\n'
        '・ICD患者で頻拍治療 (ATP/ショック)を術中offにする方針なら, 除細動パッドの事前貼付と体外式除細動器の即応体制を必ずセットで準備する\n'
        '\n'
        '■麻酔計画\n'
        '低心機能のICD患者は頻脈による心筋酸素需給の破綻から致死性不整脈を来しやすく, 挿管・抜管刺激, 循環血液量不足, 疼痛など頻脈誘因を避ける. 末梢神経刺激装置もEMI源となるためICD近傍での使用は避ける. モニタはSpO2波形や動脈圧波形を併用し, ペーシングスパイクとQRSの二重カウントによる心拍数過大評価に注意する.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '・除細動パッドは前後方 (anteroposterior)に, デバイス本体から8cm以上離し直上を避けて貼付する\n'
        '・磁石適用: PPMは非同期固定モードとなり, レートはBoston Scientific 100/分, Medtronic 85/分, Abbott 100/分, Microport(Sorin) 96/分などメーカーで異なる (電池残量低下で低下する). ICDは頻拍治療 (検出/ATP/ショック)のみoffとなりペーシング機能には影響しない (Biotronikは磁石除去後8時間で自動再開する機種がある). Leadless PMは磁石に反応しないため専用プログラマが必要\n'
        '・モノポーラ電気メスは短いバースト (5秒未満)を5秒以上あけて使用し, 対極板はデバイス・リードを電流が通過しない位置に貼付する. 可能な限りバイポーラ電気メスを優先する\n'
        '・ペーシング不全やICD不適切作動を認めたら電気メス使用を即中止し, 経皮ペーシングパッドをスタンバイさせる\n'
        '\n'
        '■トラブル時の初動\n'
        '1. ペーシング抑制/アシストール疑い: 電気メス中止, 磁石適用で非同期化, 無効なら経皮ペーシング作動とアトロピン/アドレナリン準備\n'
        '2. ICD不適切ショック疑い: 電気メス中止, 磁石適用で頻拍治療off, 血行動態不安定なら外部除細動器で対応し二次損傷を防ぐ\n'
        '3. 術後は磁石使用例, 重大な不整脈イベント発生例で退室前にデバイス再チェック (interrogation)を行い, 抑制していた機能をCIEDチームに速やかに復帰依頼する\n'
        '\n'
        '■出典\n'
        '・Kim M, Kwon CH. Perioperative management of patients with cardiac implantable electronic devices. Korean J Anesthesiol 2024; 77(3): 306-315\n'
        '・ASA Practice Advisory for the Perioperative Management of Patients with CIEDs 2020\n'
        '・HRS/ASA Expert Consensus Statement on the Perioperative Management of Patients with CIEDs 2011\n'
        '・日本循環器学会/日本不整脈心電学会 不整脈非薬物治療ガイドライン 2018年改訂版',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: '術中の頻脈性不整脈への対応 (静注薬と非薬物療法)',
    color: _cCardiac,
    tags: const ['循環器', '不整脈', '術中トラブル', '緊急対応'],
    body: '■病態の要点\n'
        '術中頻脈はnarrow QRS regular (房室結節リエントリー性/回帰性頻拍), irregular (心房細動AF・心房粗動AFL, 多源性心房頻拍), wide QRS (心室頻拍VT, 変行伝導を伴うSVT)に大別する. 治療の前に必ず可逆的誘因を検索する: 麻酔深度不足, 循環血液量不足, 低酸素, 高CO2, 発熱, 貧血, 手術操作 (牽引・迷走神経/交感神経刺激), 薬剤性 (カテコラミン, 抗コリン薬, ケタミン), 電解質異常 (低K, 低Mg), 甲状腺クリーゼ, 悪性高熱. これらの是正のみで停止することも多い.\n'
        '\n'
        '■術前の評価と準備 (リスクヘッジ)\n'
        '・AF/AFL, 発作性SVTの既往を問診し, 12誘導心電図でWPW型pre-excitationの有無を確認する\n'
        '・AF/AFL既往例, 低心機能例, 心臓・大血管手術, 電解質変動リスクが高い長時間手術では除細動パッドを入室前に貼付しておく\n'
        '・ATP, ランジオロール, アミオダロン, ニフェカラント, 硫酸マグネシウムを含む緊急薬剤カートと除細動器の同期モード動作をtimeoutで確認する\n'
        '・WPW症候群既往患者ではCa拮抗薬・ジゴキシン・β遮断薬単独が禁忌となりうるため, 薬剤選択方針を事前にチームで共有する\n'
        '\n'
        '■静注薬による対応\n'
        'narrow QRS regular: 迷走神経刺激手技 (頸動脈洞マッサージ, Valsalva. 眼球圧迫は網膜剥離リスクがあり行わない)が無効ならATP 10mgを1-2秒で急速静注し直後に生食でフラッシュする. 無効なら20mgに増量して反復する (WPW合併AFには禁忌). ATP不応・非適応例はベラパミル5mgを5分以上かけて緩徐静注, または低心機能例を避けジルチアゼム10mgを約3分で静注する.\n'
        'AF/AFLのレートコントロール: 低心機能例はランジオロール1γから開始し1-10γで漸増する (Ca拮抗薬は陰性変力作用のため避ける). 心機能温存例はランジオロールのほかジルチアゼム10mg/3分後に持続, またはベラパミル5mg/5分でよい. ジゴキシン0.25mgを2-4時間毎に静注 (飽和量1-2mg)し心不全合併例の補助とするが, 効果発現が緩徐でカテコラミン過剰状態の急性期には不向き. 目標安静時心拍数は<110/分を目安とする.\n'
        '血行動態不安定なら鎮静下 (ミダゾラム/プロポフォール少量)に同期式カルディオバージョンを行う: AFは二相性100J, AFLは二相性50-100Jから開始し, パッドは前後方配置とする.\n'
        'wide QRS: アミオダロン125mg (2.5mL)を5%ブドウ糖100mLに希釈し10分で点滴する (生食は沈殿を生じるため不可). 再発時は追加投与可, その後750mg/6時間, 維持600mg/24時間へ移行する. 心機能低下例や血圧維持を優先する場合はニフェカラント0.3mg/kgを5分かけて静注し (生食で溶解可), 持続0.4mg/kg/時とする (QT>0.6秒で減量・中止). いずれも使用できない場合の代替がリドカイン1-1.5mg/kgを1-2分で静注 (持続1-4mg/分)である. wide QRSにATP・Ca拮抗薬・β遮断薬単独投与は原則避ける.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '・除細動パッドの事前貼付は上記リスク患者全例で行う. カルディオバージョンは常に同期モードを確認してから施行する\n'
        '・オーバードライブペーシング: 心臓手術の心外膜ペーシングワイヤーや経食道ペーシング電極を用い, 自己レートより10-20/分速いレートで一時ペーシングしAFL・心房頻拍を停止させる\n'
        '・電解質補正: K 4.0-4.5mEq/L以上, Mg 2.0mg/dL以上を目標に, 硫酸マグネシウム1-2gを5-20分かけて緩徐静注する\n'
        '\n'
        '■トラブル時の初動\n'
        '1. 意識・血圧・SpO2を確認し血行動態不安定 (収縮期血圧低下, 意識低下, 虚血兆候)なら迷わず同期カルディオバージョンへ\n'
        '2. 安定していればモニタ心電図でQRS幅とリズムの整/不整を確認し上記アルゴリズムに沿って薬剤を選択する\n'
        '3. 並行して麻酔深度, 換気, 出血量, 電解質, 体温を是正する\n'
        '4. 除細動パッド未貼付なら直ちに貼付し除細動器を手元に配置する\n'
        '\n'
        '■出典\n'
        '・日本循環器学会/日本不整脈心電学会 2020年改訂版 不整脈薬物治療ガイドライン\n'
        '・同 2024年JCS/JHRSフォーカスアップデート版 不整脈治療\n'
        '・JRC蘇生ガイドライン2020\n'
        '・各薬剤電子添文 (PMDA)',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: '術中の徐脈・房室ブロックへの対応 (静注薬と非薬物療法)',
    color: _cCardiac,
    tags: const ['循環器', '不整脈', '術中トラブル', '緊急対応'],
    body: '■病態の要点\n'
        '術中徐脈の原因は, 迷走神経反射 (腹腔鏡気腹, 頸部・眼科手術操作, 直腸/子宮頸管牽引), 薬剤性 (オピオイド, デクスメデトミジン, β遮断薬・Ca拮抗薬, ネオスチグミン, スキサメトニウム反復投与), 高カリウム血症, 低体温, 心筋虚血 (特に下壁梗塞で房室結節枝が巻き込まれAVBを来しやすい), 高位脊髄くも膜下麻酔・硬膜外麻酔による交感神経遮断, 眼球圧迫 (oculocardiac reflex)など多岐にわたる. まず原因検索と是正を優先する.\n'
        '\n'
        '■術前の評価と準備 (リスクヘッジ)\n'
        '12誘導心電図でPR延長, Mobitz II型2度房室ブロック, 完全房室ブロック, 二束/三束ブロックの有無を確認し, 失神・めまいなど症候性徐脈の既往を問診する.\n'
        '術前に経静脈ペーシング (内頸静脈から)の留置を依頼すべき症例:\n'
        '・Mobitz II型2度房室ブロック (進行して完全ブロックに至るリスクが高い)\n'
        '・完全 (3度)房室ブロック (無症候性でも全身麻酔前の留置を推奨)\n'
        '・症候性の高度徐脈・洞不全症候群で恒久ペースメーカ植込みまでの橋渡しが必要な場合\n'
        '・二束ブロックに失神や高度房室ブロックの既往を伴い全身麻酔を要する場合, 新規の交代性脚ブロック\n'
        '・急性下壁心筋梗塞後で高度房室ブロックが遷延している場合\n'
        '経静脈ペーシングカテーテルは内頸静脈から右室心尖部に進め, 捕捉閾値 (通常1mA未満)を確認し出力を閾値の2-3倍に設定する.\n'
        'ペーシングパッドを入室前に貼付しておくべき症例: 上記の経静脈ペーシング適応全例のバックアップ, 症候性洞徐脈・高度I/II度房室ブロック, 迷走神経刺激が強い術式 (腹腔鏡気腹, 頸動脈内膜剥離術, 斜視手術, 脳幹部手術), 高位区域麻酔予定例, 電池残量やリード機能に懸念のあるPM植込み患者.\n'
        '\n'
        '■麻酔計画\n'
        '迷走神経刺激手技 (気腹開始, 牽引)の直前にアトロピンを準備しておく. 高位区域麻酔が予想される場合は麻酔レベル拡大を避ける工夫 (体位, 局麻量調整)をし, 交感神経遮断による徐脈に備える. レミフェンタニルなど強オピオイドのボーラス投与による徐脈を予測し, 執刀直前投与は避けるかアトロピン前投与を検討する.\n'
        '\n'
        '■静注薬による対応\n'
        'アトロピン0.5mgずつ静注し, 効果不十分なら反復する (総量3mgまでが迷走神経遮断上限の目安, 0.5mg未満の少量投与は逆説的に徐脈を悪化させうるため避ける). 房室結節より末梢のブロックでアトロピンが無効な場合はアドレナリン0.05-0.1mgずつ静注または0.05-0.1γの持続を開始する. イソプロテレノールは0.2mg/5mLを希釈し1-2μg/分 (目安0.01-0.02μg/kg/分)から持続静注し心拍数を見ながら調節する (心筋虚血・不整脈誘発に注意). 高カリウム血症が疑われれば塩化カルシウム/グルコン酸カルシウムの投与と電解質補正を優先する.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '・体外 (経皮)ペーシング: パッドを前後方に貼付し捕捉が得られるまで出力を漸増する (目安50-100mA), レート60-80/分に設定. 疼痛を伴うため意識下では十分な鎮静・鎮痛を併用する\n'
        '・経静脈ペーシング: VVIモードでレート60-80/分, 出力は捕捉閾値の2-3倍\n'
        '・経食道ペーシングは心房ペーシングが主体で房室伝導が保たれた洞徐脈に有効だが, 完全房室ブロックには無効なことが多い\n'
        '・PM患者で術中にペーシング不全 (capture不全, sensing/output不全)が出た場合: 電気メス使用を中止しリズムを再評価, 磁石を適用し非同期モードへ切替, 改善なければ経皮ペーシングを作動しアトロピン/イソプロテレノールを併用, 高カリウム血症・局所麻酔薬血中濃度上昇・虚血・酸塩基異常など閾値上昇の原因を検索する\n'
        '\n'
        '■トラブル時の初動\n'
        '1. 意識・血圧・SpO2を確認し症候性か (低血圧, 意識低下, 虚血)を判断する\n'
        '2. 症候性徐脈: アトロピン0.5mgを即座に静注しつつ経皮ペーシングパッドの準備・貼付を並行して指示する\n'
        '3. 高度/完全房室ブロックでアトロピン無効: 経皮ペーシングを作動し, イソプロテレノールまたはアドレナリン持続を開始する\n'
        '4. 気腹, 牽引, 眼球圧迫など手技的誘因があれば術者に中断を依頼する\n'
        '5. 心停止に至れば直ちに胸骨圧迫を開始し通常の心停止アルゴリズムに移行する\n'
        '\n'
        '■出典\n'
        '・日本循環器学会/日本不整脈心電学会 不整脈非薬物治療ガイドライン 2018年改訂版\n'
        '・同 2021年JCS/JHRSフォーカスアップデート版 不整脈非薬物治療\n'
        '・ACC/AHA/HRS 2018 Guideline on the Evaluation and Management of Patients with Bradycardia and Cardiac Conduction Delay\n'
        '・JRC蘇生ガイドライン2020',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: '先天性QT延長症候群 (LQTS) の麻酔管理',
    color: _cCardiac,
    tags: const ['循環器', '不整脈', '先天性', '術中トラブル'],
    body: '■病態の要点\n'
        '先天性QT延長症候群 (LQTS)は心室再分極遅延により多形性心室頻拍(torsade de pointes: TdP)を来し, 失神やVF・突然死の原因となる. 有病率は約1000-2000人に1人. 主要3型で臨床像が異なる.\n'
        '・LQT1 (KCNQ1, IKs電流低下): 運動・水泳中に誘発されやすい. T波は幅広い. β遮断薬が著効(推奨クラスI).\n'
        '・LQT2 (KCNH2, IKr電流低下): 情動・驚愕・産褥期・安静/睡眠中の音刺激で誘発. ノッチ型T波. 非選択性β遮断薬(ナドロール)が推奨.\n'
        '・LQT3 (SCN5A): 安静・睡眠中の徐脈依存性に誘発. 遅発性T波. β遮断薬の効果は限定的で, メキシレチン(Na電流抑制)が有効な場合がある.\n'
        'TdPはPVC後のshort-long-short型休止や, 洞頻脈に伴うT波交互脈から誘発される.\n'
        '\n'
        '■術前の評価と準備 (リスクヘッジ)\n'
        '・12誘導心電図でQTc(目安470ms以上)と型(LQT1-3)を確認し, 家族歴・失神歴を聴取する.\n'
        '・内服中のβ遮断薬は周術期も中断しない. 絶食中は静注(プロプラノロール, ランジオロール)で継続する.\n'
        '・電解質を確認し, 血清K+ ≥4.0mEq/Lを目標に補正, Mgも補正しておく.\n'
        '・QT延長を来す周術期薬剤を洗い出し代替薬を用意する: 制吐薬(ドロペリドール, メトクロプラミド, オンダンセトロン等の5-HT3拮抗薬は減量/回避しデキサメタゾン等へ), 抗菌薬(マクロライド系, フルオロキノロン系は可能なら回避), 抗精神病薬(ハロペリドール, ドロペリドールは避ける), 吸入麻酔薬(セボフルランはQT延長作用があり急速な高濃度導入を避ける).\n'
        '・症候性例(失神/TdP既往), QTc著明延長例, ICD植込み例では, 入室前から除細動パッドを貼付しておく.\n'
        '・ICD患者は設定(抗頻拍治療・マグネット反応)を事前に不整脈科と確認し, 電気メス使用時のEMI対策を計画する.\n'
        '\n'
        '■麻酔計画\n'
        '・交感神経刺激を最小化する緩徐導入: 挿管前に十分なオピオイド(レミフェンタニル等)とリドカイン静注で喉頭鏡刺激への反射を抑える.\n'
        '・浅麻酔・体動・疼痛はQT延長とTdPの誘因となるため, 深度モニタリング下に十分な麻酔深度を維持する.\n'
        '・プロポフォールベースのTIVA, または通常濃度の揮発性麻酔薬いずれも使用可能だが, セボフルランの急速な高濃度導入は避ける.\n'
        '・筋弛緩拮抗はネオスチグミン+抗コリン薬による徐脈化を避け, スガマデクスを優先する.\n'
        '・抜管時も咳嗽・交感神経刺激を避け, 愛護的に行う.\n'
        '\n'
        '■静注薬による対応\n'
        '・TdP出現時: 硫酸マグネシウム2g(体重換算30-40mg/kg)を5-10分で静注し, 以後3-20mg/分で持続投与する.\n'
        '・徐脈依存性TdP(とくにLQT3・β遮断薬内服中)には, オーバードライブペーシング(心拍数100-110/分程度)を優先する. β遮断薬内服中はイソプロテレノール単独では徐脈依存性のTdPを助長しうるため, ペーシングが使えない状況でのみ慎重に少量から使用する.\n'
        '・K+ ≥4.0mEq/Lへ補正する.\n'
        '・再発予防にβ遮断薬(プロプラノロール, ランジオロール)静注を追加する. LQT3ではリドカイン/メキシレチンが有効なことがある.\n'
        '・VFへ移行したら薬物より除細動を優先する.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '・除細動パッドの事前貼付(症候性例, QTc高度延長, ICD患者は必須).\n'
        '・体外(経皮)ペーシングをすぐ使用できる状態で準備する. 高リスク例では術前に経静脈ペーシング留置を依頼する.\n'
        '・オーバードライブペーシングで心拍数を上げQT/RR比を是正しTdPを抑制する.\n'
        '・ICD患者は電気メス使用時の誤作動・誤ショックに備え, マグネット又は事前プログラム変更で抗頻拍治療を一時停止し, 除細動パッドを常時使用可能に保つ.\n'
        '\n'
        '■トラブル時の初動\n'
        '・TdP出現→硫酸マグネシウム2g静注, 誘因薬剤の中止, K+補正, 除細動パッド装着確認.\n'
        '・持続/VF移行→非同期除細動(二相性150-200J).\n'
        '・徐脈性TdP→経皮ペーシング開始, 困難ならイソプロテレノールを少量から.\n'
        '\n'
        '■出典\n'
        '・2026年改訂版 遺伝性不整脈の診療に関するガイドライン(日本循環器学会/日本不整脈心電学会)\n'
        '・2020年改訂版 不整脈薬物治療ガイドライン(日本循環器学会/日本不整脈心電学会)',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: 'Brugada症候群の麻酔管理',
    color: _cCardiac,
    tags: const ['循環器', '不整脈', '先天性', '術中トラブル'],
    body: '■病態の要点\n'
        'Brugada症候群はSCN5A等のNaチャネル機能低下により右室流出路でcoved型ST上昇(Type I心電図)を来し, 主に夜間・安静時・発熱時にVFを誘発する. 日本を含むアジア人の若年-中年男性に多い(男:女=9:1). 約90%は無症候性だが, 失神/心停止既往例は突然死高リスクでICD絶対適応となる.\n'
        '\n'
        '■術前の評価と準備 (リスクヘッジ)\n'
        '・12誘導心電図でType I波形の有無, 失神・突然死家族歴を確認する.\n'
        '・発熱を絶対に避ける方針を周術期を通じて徹底する: 解熱薬(アセトアミノフェン静注)をすぐ使えるよう準備し, 感染兆候があれば早期に対処する.\n'
        '・Naチャネル遮断作用を持つ薬剤リストを確認し回避する: ブピバカイン(高濃度・大量投与), プロカインアミド, フレカイニド, 三環系抗うつ薬, 一部の抗ヒスタミン薬. リドカインは通常の局所麻酔用量では概ね容認されるが全身への大量投与は避ける.\n'
        '・局所麻酔薬はロピバカインなど心毒性・Na遮断作用の弱い薬剤を優先し, ブピバカインの高用量投与を避ける.\n'
        '・症候性例, Type I心電図+失神歴, ICD植込み例では入室前から除細動パッドを貼付しておく.\n'
        '・ICD患者は設定(抗頻拍治療・マグネット反応)を不整脈科と事前確認し, 電気メス使用計画を立てる.\n'
        '\n'
        '■麻酔計画\n'
        '・プロポフォールは通常導入用量では概ね安全とされるが, 大量・急速投与でST上昇を誘発した報告があり緩徐に投与する.\n'
        '・揮発性麻酔薬(セボフルラン等)は比較的安全とされ第一選択になりうる.\n'
        '・脊髄くも膜下麻酔でType I波形が顕在化した報告があるが絶対禁忌ではない. 硬膜外を選択する場合は低濃度局所麻酔薬とし高用量ブピバカインは避ける.\n'
        '・迷走神経緊張の急激な亢進(強い咽頭反射, 過度の鎮痛薬減量による疼痛刺激)はST上昇・VF誘発因子となるため避ける.\n'
        '・筋弛緩拮抗はネオスチグミンによる迷走神経緊張亢進を避け, スガマデクスを優先する.\n'
        '\n'
        '■静注薬による対応\n'
        '・VF出現時: ただちに非同期除細動(二相性150-200J)を行う.\n'
        '・電気ストーム/頻回VFにはイソプロテレノール持続静注(0.02-0.2μg/kg/分程度から開始, 心拍数を上げてItoに関連したST上昇を軽減する)が有効(推奨クラスIIa).\n'
        '・キニジンはNaチャネルだけでなくItoも抑制し発作抑制に有効(推奨クラスIIa)だが内服薬であり, 周術期の急性対応はイソプロテレノールが中心となる.\n'
        '・発熱時はアセトアミノフェン静注に加え, 冷却ブランケット・氷嚢・冷所輸液による積極的な体表冷却を併用し速やかに解熱する.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '・除細動パッドの事前貼付を強く推奨する(症候性例, Type I心電図, ICD植込み例は入室前から必須).\n'
        '・中心温をモニタリングし, 加温はシバリング予防程度にとどめ過加温を避ける. 逆に低体温による不整脈誘発も避け, 適正体温を維持する.\n'
        '・ICD患者は電気メス使用時の誤作動・誤ショックに備え, マグネット又は事前プログラム変更で抗頻拍治療を一時停止し, 除細動パッドを常時使用可能な状態に保つ.\n'
        '・カテーテルアブレーション後患者はVF再発が減少するが根治ではなくICD適応・周術期の注意は変わらない.\n'
        '・入室前に12誘導心電図でType Iの有無を再確認し, 麻酔記録に残す.\n'
        '\n'
        '■トラブル時の初動\n'
        '・Type I ST上昇に伴うVF→非同期除細動, 発熱・誘因薬剤の除去, イソプロテレノール開始.\n'
        '・電気ストーム→イソプロテレノール持続静注を継続しつつ麻酔深度と体温を確認, ICD作動状況を確認する.\n'
        '・軽微なType I波形出現のみで血行動態安定なら, 誘因(発熱・薬剤・迷走神経刺激)の除去を優先し経過観察する.\n'
        '\n'
        '■出典\n'
        '・2026年改訂版 遺伝性不整脈の診療に関するガイドライン(日本循環器学会/日本不整脈心電学会)\n'
        '・2020年改訂版 不整脈薬物治療ガイドライン(日本循環器学会/日本不整脈心電学会)',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: 'カテコラミン誘発性多形性心室頻拍 (CPVT) の麻酔管理',
    color: _cCardiac,
    tags: const ['循環器', '不整脈', '先天性', '術中トラブル'],
    body: '■病態の要点\n'
        'カテコラミン誘発性多形性心室頻拍(CPVT)はRyR2(常染色体優性, 診断例の60-70%)やCASQ2等の異常により, 交感神経刺激下で筋小胞体からCa過剰放出が起こり, 特徴的な二方向性/多形性VTからVFに至る. 安静時心電図はほぼ正常で診断は運動負荷試験が有用. 有病率約1万人に1人, 発症年齢中央値は10代. 診断されずに運動中突然死する例が一定数含まれるとされる.\n'
        '\n'
        '■術前の評価と準備 (リスクヘッジ)\n'
        '・内服中の非選択性β遮断薬(プロプラノロール, ナドロール)の継続を最優先とする. 中断は絶対に避け, 絶食中は静注(プロプラノロール, ランジオロール)で置き換える.\n'
        '・診断確定例は全例で, 入室前から除細動パッドを貼付しておく.\n'
        '・ICD植込みの有無, 頻回作動歴, 左心臓交感神経節切除(LCSD)術後かを確認する.\n'
        '・カテコラミン系薬剤(アドレナリン, ドパミン, エフェドリン, 局所麻酔薬へのアドレナリン添加)を極力回避する方針を手術チームで共有し, 代替の純α1刺激薬(フェニレフリン)を用意する.\n'
        '・強い不安・疼痛予期が発作誘因となるため, 入室前の説明と十分な前投薬でストレス反応を事前に抑える.\n'
        '\n'
        '■麻酔計画\n'
        '・侵害刺激とカテコラミンサージを最小化する緩徐導入: オピオイド(レミフェンタニル等)を十分に併用し, 喉頭鏡刺激への交感神経反射を抑える.\n'
        '・浅麻酔・体動・疼痛の徹底回避. 麻酔深度モニタリング下で終始十分な深度を維持する(最大の発作誘因は交感神経緊張).\n'
        '・局所麻酔薬へのアドレナリン添加は避けるか最小限にとどめる.\n'
        '・抜管時の咳嗽・体動もVT誘因となるため, 深麻酔下抜管やリドカイン静注併用を検討する.\n'
        '・昇圧が必要な場面ではエフェドリン・アドレナリンではなくフェニレフリン等の純α1刺激薬を優先する.\n'
        '\n'
        '■静注薬による対応\n'
        '・VT/VF出現時: β遮断薬静注(プロプラノロール等)を追加投与し交感神経緊張を強力に抑制する(推奨クラスIIa).\n'
        '・硫酸マグネシウム静注も併用を考慮する(推奨クラスIIb).\n'
        '・治療抵抗例ではフレカイニド(RyR2を直接抑制)の追加投与を考慮する(推奨クラスIIa).\n'
        '・持続VT/VFには非同期除細動, 血行動態が保たれた単形性VTには同期下カルディオバージョンを行う.\n'
        '・カテコラミン系昇圧薬・強心薬の投与は必要最小限にとどめ, 使用時は少量から漸増する.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '・除細動パッドの事前貼付は全例で行う.\n'
        '・ICD患者は頻回作動歴・LCSD既往を把握し, 設定(抗頻拍治療・マグネット反応)を事前に確認する.\n'
        '・深い鎮痛・鎮静でストレス反応を抑えることが最大の非薬物的対策であり, BIS等の深度モニタリングを活用する.\n'
        '・体温管理・十分な疼痛管理を徹底し, 術後回復室でも交感神経刺激因子(疼痛, 嘔気, 低体温)を最小化する.\n'
        '\n'
        '■トラブル時の初動\n'
        '・二方向性/多形性VT出現→ただちにβ遮断薬静注, 麻酔深度を深め, 使用中の昇圧薬・カテコラミンを中止する.\n'
        '・血行動態破綻/VF→非同期除細動を最優先し, 復帰後にβ遮断薬とマグネシウムを投与する.\n'
        '・除細動抵抗性の場合は誘因(疼痛, 浅麻酔, カテコラミン投与)の再確認と除去を行う.\n'
        '\n'
        '■出典\n'
        '・2026年改訂版 遺伝性不整脈の診療に関するガイドライン(日本循環器学会/日本不整脈心電学会)\n'
        '・2020年改訂版 不整脈薬物治療ガイドライン(日本循環器学会/日本不整脈心電学会)',
  ),
  ColumnArticle(
    category: '循環器疾患',
    title: 'WPW症候群の麻酔管理',
    color: _cCardiac,
    tags: const ['循環器', '不整脈', '先天性', '術中トラブル'],
    body: '■病態の要点\n'
        'WPW症候群はKent束等の副伝導路によりΔ波と発作性上室頻拍(AVRT)を来す. narrow QRSの房室回帰性頻拍/房室結節リエントリー頻拍は房室結節を含む回路で生じ, 房室結節を抑制する薬剤で停止できる. 一方, 順行性伝導のある(顕性)WPWに心房細動(AF)が合併すると, 副伝導路を介して心室が高頻度に興奮し, wide QRSの偽性心室頻拍様調律からVFに移行しうる致死的病態となる.\n'
        '\n'
        '■術前の評価と準備 (リスクヘッジ)\n'
        '・12誘導心電図でΔ波の有無, 発作性頻拍の既往を確認する. アブレーション既往があれば根治術式・遺残伝導路の可能性を確認する.\n'
        '・未アブレーションで頻拍発作の既往がある顕性WPWでは, 入室前から除細動器をすぐ使用できるよう準備し, 除細動パッドを貼付しておく.\n'
        '・房室結節遮断薬(ベラパミル, ジルチアゼム, ジゴキシン, β遮断薬, アデノシン/ATP)を, AF合併時には禁忌に準じる薬剤として周術期指示に明記し, 手術・麻酔チーム全体で共有する.\n'
        '・挿管刺激・疼痛・浅麻酔などAF/SVT誘発因子を想定した鎮痛計画をあらかじめ立てる.\n'
        '・プロカインアミドまたはニフェカラントを緊急時にすぐ用意できる体制を整える.\n'
        '\n'
        '■麻酔計画\n'
        '・浅麻酔・侵害刺激を避け, 頻脈性不整脈の誘因を減らす.\n'
        '・揮発性麻酔薬・プロポフォールいずれも使用可能で, 特に禁忌となる麻酔薬はない.\n'
        '・narrow QRS SVTが循環動態安定下に出現した場合は, 迷走神経刺激手技(バルサルバ様の腹圧, 頸動脈マッサージ, 冷水刺激)を第一選択として試みてよい.\n'
        '\n'
        '■静注薬による対応\n'
        '・narrow QRS SVT(AVRT/AVNRT): 迷走神経刺激手技で無効なら, ATP(アデノシン三リン酸)10mgを末梢静脈から急速静注し生食でフラッシュする. 無効なら20mgへ増量して再投与する.\n'
        '・wide QRS頻拍やpreexcited AFでは, 房室結節遮断薬(Ca拮抗薬, ジゴキシン, β遮断薬, ATP)は使用しない. 副伝導路のみを介した伝導が相対的に促進され心室応答が増加しVFへ移行するリスクがあるためである.\n'
        '・血行動態が安定していれば, 副伝導路の伝導を抑制するNaチャネル遮断薬を用いる: プロカインアミド10-15mg/kgを50mg/分以下で静注, またはニフェカラント0.3mg/kgを5分で静注し以後0.4mg/kg/時で持続投与する.\n'
        '・血行動態不安定なら薬物投与より電気的治療を優先する.\n'
        '\n'
        '■非薬物療法・デバイス\n'
        '・同期式カルディオバージョン: 血行動態不安定なnarrow/wide QRS regular tachycardiaに対し二相性100-200Jで同期下に施行する.\n'
        '・除細動(非同期): AF/VFへ移行した場合は二相性120-200Jで行う.\n'
        '・未アブレーションの症候性WPW(頻拍発作既往あり)は入室前から除細動パッドを貼付しておく.\n'
        '・アブレーション後患者は通常, 周術期リスクは低いが, 複数副伝導路や不完全焼灼が疑われる例では事前貼付を検討する.\n'
        '\n'
        '■トラブル時の初動\n'
        '・narrow QRS SVT→迷走神経刺激手技→無効ならATP10mg, 反応なければ20mgへ増量.\n'
        '・wide QRS/preexcited AF→房室結節遮断薬は使用せず, プロカインアミドまたはニフェカラント, もしくは直ちに同期カルディオバージョンへ移行する.\n'
        '・VFへ移行→非同期除細動を最優先する.\n'
        '\n'
        '■出典\n'
        '・2020年改訂版 不整脈薬物治療ガイドライン(日本循環器学会/日本不整脈心電学会)\n'
        '・2026年改訂版 遺伝性不整脈の診療に関するガイドライン(日本循環器学会/日本不整脈心電学会)\n'
        '・50の術式と疾患で学ぶ心臓麻酔(Ebstein奇形合併WPWの項)',
  ),

  // ───────── 集中治療・せん妄 ─────────
  ColumnArticle(
    category: '集中治療・せん妄',
    title: 'ICUの夜間: 不眠・覚醒・せん妄への対応ラダー',
    color: _cIcu,
    tags: const ['せん妄', '鎮静', 'ICU', '不眠'],
    body: '■まず非薬物療法から (ABCDEFバンドル)\n'
        '・ICUの夜間対応は薬剤より先に環境と行動から着手する. ABCDEFバンドル (A: 痛みの評価/予防/管理, B: 自発覚醒と自発呼吸トライアルの併用, C: 鎮静・鎮痛薬の選択, D: せん妄の評価/予防/管理, E: 早期離床と運動, F: 家族の関与) を毎日のケアの骨格にする. 遵守率が高い施設ほど院内死亡やせん妄発生が少ない.\n'
        '・夜間は照明とアラーム音を落とし, 日中は離床とリハビリで昼夜のリズムをつける. 耳栓の使用や処置の日中集約など睡眠を守る介入で, せん妄/昏睡のない日数が有意に増える.\n'
        '・眼鏡/補聴器を装用させ, 時計・カレンダー・家族の面会など見当識の手がかりを置く. 面会制限の緩和は患者のせん妄発症率の低下とICU滞在日数の短縮に関連し, 感染症増加とは関連しなかった.\n'
        '・不穏の原因のうち痛みとせん妄が最多である. NRS/BPS/CPOTで痛みを先に評価し, 鎮痛を最適化してから鎮静を考える (鎮痛優先の鎮静).\n'
        '・不要な身体抑制と不要なカテーテル/ラインは早期に見直す. 身体抑制は最後の手段であり, 継続の要否は8時間ごとに再評価する. 抜管可能なら早期抜管を優先する.\n'
        '・薬剤性せん妄の原因を見直す. 抗コリン薬 (ジフェンヒドラミン, ヒドロキシジンなど), ベンゾジアゼピン系, ステロイド, オピオイド過量はせん妄を悪化させうる. 高齢入院患者では抗コリン薬負荷スコアがせん妄群で有意に高い.\n'
        '\n'
        '■評価のしかた\n'
        '・せん妄はCAM-ICUまたはICDSCで評価する. いずれもICU患者に妥当性が確認された代表的ツールで, 少なくとも1日1回, できれば勤務帯ごとに評価する.\n'
        '・CAM-ICUは急性発症/変動する経過+注意力欠如+ (無秩序な思考または意識レベルの変化) でせん妄陽性 (感度75.5-81%, 特異度95.8-98%). ICDSCは意識レベル・注意力・失見当識・幻覚妄想・精神運動興奮または遅滞・不適切な会話・睡眠覚醒サイクル障害・症状の変動の8項目, 4点以上でせん妄.\n'
        '・鎮静深度はRASSで, 目標は原則0から-2の浅い鎮静とする. 深い鎮静 (-3から-5) はICU在室期間延長やPTSDと関連しうるため必要最小限にする. 浅すぎても深すぎても評価は不正確になりやすく, 評価前に鎮静深度を確認する.\n'
        '・痛みは自己申告できる患者はNRS (3超で介入), できない患者はBPS (5超) やCPOT (2超) で評価する.\n'
        '\n'
        '■せん妄と不眠を分けて考える\n'
        '・せん妄は過活動型 (興奮・不穏・幻覚), 低活動型 (活動低下・無気力・会話減少), 混合型に分類される. スクリーニングツールを使わないと多くが見逃され, 特に低活動型で見逃されやすい. 「大人しいから大丈夫」ではなく毎回評価する.\n'
        '・「眠れない」と「せん妄」は病態も治療も異なる. 単なる不眠に抗精神病薬を最初から使わない. まず疼痛, 低酸素, 頻回な処置やアラームなど不眠の原因を探す.\n'
        '・アルコール多飲歴とICUせん妄の関連は日本人でも報告されている. 通常のせん妄対応 (抗精神病薬中心) とは逆に, アルコール離脱せん妄が疑われる場合はベンゾジアゼピン系を選ぶ. 鑑別の頼りは詳細な飲酒歴の聴取である.\n'
        '・ベンゾジアゼピン系とオピオイドの使用はICUせん妄発症の治療関連因子である. ミダゾラム使用は外傷患者でせん妄移行の独立危険因子であったとする報告もある.\n'
        '\n'
        '■せん妄出現時の推奨処方ラダー (下記をそのまま使う)\n'
        '①基本: クエチアピン (QTP) 25mg 2錠 1日4回まで\n'
        '②DMあり腎不全なし: チアプリド (グラマリール) 25mg 2錠 1日4回まで\n'
        '③DMあり腎不全あり: ペロスピロン (ルーラン) 4mg 4錠 1日4回まで\n'
        '④パーキンソニズムあり: トラゾドン 25mg 2錠 1日4回まで\n'
        '⑤内服困難: アセナピン (シクレスト) 5mg 1錠 舌下 1日4回まで\n'
        '⑥上記無効: ハロペリドール (セレネース) 5mg + 生食50mL 30分で点滴 1日4回まで\n'
        '・腎不全はeGFR 30をcut offとする. クエチアピン/オランザピンは添付文書上, 糖尿病 (既往含む) に禁忌 (高血糖, 糖尿病性ケトアシドーシス, 昏睡の報告のため) のためDM患者では②③に進む. チアプリドは主に未変化体で腎排泄され腎不全で蓄積しパーキンソニズムやQT延長のリスクが増すため, 腎不全合併例では主に肝代謝のペロスピロンに切り替える.\n'
        '\n'
        '■せん妄ハイリスク患者の不眠時 (上記の半量, いずれも1日4回まで)\n'
        '①クエチアピン 25mg 1錠 ②チアプリド 25mg 1錠 ③ペロスピロン 4mg 1錠\n'
        '④トラゾドン 25mg 1錠 ⑤アセナピン 5mg 0.5錠 舌下 ⑥ハロペリドール 2.5mg + 生食50mL 30分\n'
        '\n'
        '■せん妄ローリスク患者の睡眠薬\n'
        '・エスゾピクロン (ルネスタ) 1mg 1錠. 65歳未満は1日3回まで, 65歳以上は1日2回まで.\n'
        '・レンボレキサント (デエビゴ) 5mg 1錠 1日2回まで.\n'
        '\n'
        '■睡眠薬のラダー (せん妄リスクが低い場合)\n'
        '①基本: レンボレキサント (デエビゴ) 5-10mg, ラメルテオン (ロゼレム) 8mg, トラゾドン (レスリン) 25mg\n'
        '②無理なら非BZ系: エスゾピクロン (ルネスタ)\n'
        '③それでも無理ならMARTAもしくはBZ系\n'
        '\n'
        '■人工呼吸中の鎮静薬の選択\n'
        '・鎮静薬はデクスメデトミジンとプロポフォールを軸にする. ベンゾジアゼピン系 (ミダゾラム) はICUせん妄の危険因子として一貫して報告され, 第一選択にしない.\n'
        '・デクスメデトミジンの利点は自然睡眠に近い脳波パターンと呼吸抑制の少なさ, 欠点は徐脈と低血圧 (メタ解析で徐脈リスク比1.72, 低血圧リスク比1.28). 周術期投与は主観的睡眠の質を改善し術後せん妄発生をリスク比0.66に抑えたとするメタ解析があるが, ICU人工呼吸下でのせん妄"期間"短縮が日本承認用量内でベンゾジアゼピンより優れるかは明確でない.\n'
        '・夜間のみ持続投与し日中は中止して覚醒・離床を優先する運用が, 昼夜のリズムをつけつつ鎮静薬を最小化する現実的な方法である.\n'
        '\n'
        '■やってはいけないこと\n'
        '・せん妄予防目的での抗精神病薬のルーチン投与. ハロペリドール, ジプラシドン, プラセボの3群比較RCTでせん妄フリー日数, 人工呼吸器フリー日数, 入院期間, 死亡率のいずれにも有意差はなかった. 心臓外科術後せん妄でも予防的なクロニジンや抗精神病薬を支持する複数のRCTはない.\n'
        '・低活動型せん妄への抗精神病薬投与. 興奮を伴わないため薬理学的介入より先に原因検索 (疼痛, 低酸素, 循環不全, 感染, 電解質異常) を行う.\n'
        '・不眠にベンゾジアゼピン系を漫然と使うこと. せん妄と転倒のリスクを増やす.\n'
        '・パーキンソン病, レビー小体型認知症へのハロペリドールなどD2遮断薬の投与. 錐体外路症状の増悪や重篤な過敏反応のリスクがある.\n'
        '\n'
        '■出典\n'
        '・日本集中治療医学会 J-PADガイドライン作成委員会. 痛み・不穏・せん妄管理のための臨床ガイドライン. 日集中医誌 2014;21:539-579.\n'
        '・日本版敗血症診療ガイドライン2024 (J-SSCG2024) FRQ7-1, CQ8-2.\n'
        '・Grant MC, et al. Perioperative Care in Cardiac Surgery: Joint Consensus Statement (ERAS/STS). Ann Thorac Surg 2024;117:669-89.\n'
        '・Wang L, et al. Perioperative dexmedetomidine and sleep quality after noncardiac surgery: SR/MA. PLoS ONE 2024;19(12):e0314814.\n'
        '・Ieong C, et al. Anticholinergic drug burden and delirium in older hospitalized patients: SR/MA. BMC Geriatrics 2024;24:599.',
  ),
  ColumnArticle(
    category: '集中治療・せん妄',
    title: 'せん妄のリスク評価と予防 (周術期・ICU)',
    color: _cIcu,
    tags: const ['せん妄', '術前評価', 'ICU', '区域麻酔'],
    body: '■せん妄のリスク因子 (準備因子/誘発因子/直接因子)\n'
        '・準備因子 (患者側の素因): 高齢, フレイル, 既存の認知機能低下や気分障害, 過度のアルコール摂取. 心臓外科の周術期ケアに関する国際コンセンサス声明は, 術前リスク評価に「せん妄リスク因子」を独立項目として掲げ, 年齢・フレイル・既存の認知/気分障害・過度の飲酒を挙げている.\n'
        '・誘発因子 (病態・環境側の負荷): 手術侵襲, 疼痛コントロール不良, 睡眠遮断, 不動化, 不要なカテーテル/ライン, 感染, 代謝異常, 低酸素血症. ICUせん妄の予測モデルPRE-DELIRICは年齢・重症度・入院形態・昏睡・感染・代謝性アシドーシス・鎮静薬/モルヒネ使用・尿素窒素値・入院様態の10因子でAUC 0.87の高い予測能を示した.\n'
        '・直接因子 (治療関連因子): ベンゾジアゼピン系鎮静薬とオピオイドはICUせん妄の独立した治療関連危険因子である. 抗コリン薬負荷が高いほどせん妄発症と有意に関連する (SMD 0.21).\n'
        '・心臓外科術後のせん妄発症率は約20-50%と報告され, 院内/長期生存, 再入院回避, 認知/機能回復の低下と関連する.\n'
        '\n'
        '■術前からできる予防\n'
        '・ハイリスクの拾い上げ: 高齢, フレイル, 既存の認知機能低下, 気分障害, 過度の飲酒歴を術前評価に組み込む.\n'
        '・内服の見直し: 抗コリン薬 (市販薬含む) の重複を減らす. 慢性ベンゾジアゼピンの急な中止は離脱を招くため, 定期薬は継続しつつ追加の鎮静薬を絞る.\n'
        '・睡眠環境: 入院後から昼夜のリズムを崩さない環境調整を早期に始める.\n'
        '・家族の関与: 術前オリエンテーションに家族を含め, 見当識の手がかり (時計・カレンダー) や術後の面会計画をあらかじめ共有する.\n'
        '\n'
        '■術中にできること\n'
        '・必要以上に深い麻酔を避ける. 処理脳波などの麻酔深度モニタリングでバーストサプレッションを避けることが術後せん妄対策の一つとして提唱されている.\n'
        '・術中低血圧を避け, 脳灌流を維持する.\n'
        '・ベンゾジアゼピン系の術中投与は最小限にする. せん妄の危険因子であることはICUデータで一貫して示されている.\n'
        '・区域麻酔 (硬膜外麻酔, 末梢神経ブロックなど) を活用しオピオイド消費量を減らす. 腹部大動脈手術での胸部硬膜外麻酔は非経口オピオイド単独より優れた鎮痛効果を示す良質なエビデンスがある.\n'
        '・吸入麻酔薬とプロポフォールのどちらが術後せん妄/認知機能障害を減らすかは報告が一致していない. 特定の薬剤選択よりも麻酔深度の適正化と血行動態の安定を優先する.\n'
        '\n'
        '■術後・ICUでの予防\n'
        '・ABCDEFバンドルを実践する (A 痛みの評価/予防/管理, B 自発覚醒/自発呼吸トライアルの併用, C 鎮静・鎮痛薬の選択, D せん妄の評価/予防/管理, E 早期離床・運動, F 家族の関与). 遵守率が高い施設で院内死亡やせん妄発生の減少が報告されている.\n'
        '・早期離床とリハビリテーションはせん妄の発症・持続期間を減らすために推奨される.\n'
        '・NRS/BPS/CPOTで疼痛を定期評価し, 鎮痛優先の鎮静を実践する.\n'
        '・睡眠プロトコル: 夜間の遮光・消音, 日中のブラインド開放, 処置の日中集約, 耳栓使用などの多角的介入でせん妄/昏睡のない日数が有意に増える.\n'
        '・面会制限の緩和は患者のせん妄発症率の低下とICU滞在日数の短縮に関連し, 感染症増加とは関連しない. 心臓外科ICUでも家族支援介入がコミュニケーション満足度の向上とICU滞在期間短縮に関連したと報告されている.\n'
        '\n'
        '■薬物予防のエビデンス\n'
        '・非定型抗精神病薬のルーチン予防投与は推奨しない. ハロペリドール, ジプラシドン, プラセボの3群比較RCTでせん妄フリー日数, 人工呼吸器フリー日数, 入院期間, 死亡率のいずれにも有意差はなかった.\n'
        '・心臓外科術後せん妄でも, 予防的なクロニジンや抗精神病薬を支持する複数のRCTはなく, 抗精神病薬の使用は苦痛の強い症状や安全上のリスクがある患者に限定すべきとされる.\n'
        '・少量ハロペリドールの予防投与は報告が割れている. 非心臓の腹部/胸部手術後高齢者への少量投与でせん妄発症率が有意に低下した報告がある一方, 全体としてハロペリドール予防投与がせん妄発症を予防するとは言い切れない.\n'
        '・デクスメデトミジンの位置づけ: せん妄"予防"目的のルーチン使用は日本承認用量内での効果が明確でない. 一方, 周術期投与は主観的睡眠の質を改善し術後せん妄発生をリスク比0.66に抑えたとするメタ解析があり, 徐脈/低血圧増加とのバランスの上で, 人工呼吸中の鎮静薬としてベンゾジアゼピン系より優先する位置づけが妥当である.\n'
        '\n'
        '■出典\n'
        '・日本集中治療医学会 J-PADガイドライン作成委員会. 痛み・不穏・せん妄管理のための臨床ガイドライン. 日集中医誌 2014;21:539-579.\n'
        '・日本版敗血症診療ガイドライン2024 (J-SSCG2024) FRQ7-1, CQ8-2.\n'
        '・Grant MC, et al. Perioperative Care in Cardiac Surgery: Joint Consensus Statement (ERAS/STS). Ann Thorac Surg 2024;117:669-89.\n'
        '・Wang L, et al. Perioperative dexmedetomidine and sleep quality after noncardiac surgery: SR/MA. PLoS ONE 2024;19(12):e0314814.\n'
        '・Ieong C, et al. Anticholinergic drug burden and delirium in older hospitalized patients: SR/MA. BMC Geriatrics 2024;24:599.\n'
        '・Brioni JD, et al. A review of the pharmacology of sevoflurane. J Anesth 2017;31:764-778.',
  ),
  ColumnArticle(
    category: '集中治療・せん妄',
    title: 'せん妄の種類と鑑別 (低活動型を見逃さない)',
    color: _cIcu,
    tags: const ['せん妄', '低活動型せん妄', 'CAM-ICU', 'ICDSC'],
    body: '■せん妄の定義と診断\n'
        'せん妄は, 注意を集中・維持・転導する能力の低下を伴う意識障害に, 記憶障害・失見当識・言語障害・知覚障害などの認知の変化が加わった状態である. 発症は急性 (通常数時間から数日) で, 症状は1日のうちで変動するのが核心的特徴であり, 背景に感染・代謝異常・薬剤など身体疾患による直接の生理学的原因があることが診断上必須である. ICUでは急性発症する脳機能不全, すなわち多臓器障害の一分症として捉えられ, 人工呼吸患者では発症率80%以上との報告もある. せん妄はICU/入院期間の延長, 死亡率上昇 (持続日数に応じて1日あたり約10%リスク上昇との報告), 退室後の認知機能障害と関連する予後不良の独立危険因子であり, 見逃してはならない.\n'
        '\n'
        '■3つの運動性亜型\n'
        '・過活動型 (hyperactive): 易刺激性, 興奮, 錯乱, 不穏, 幻覚が目立つ. ライン自己抜去や体動で周囲が気づきやすい.\n'
        '・低活動型 (hypoactive): 注意低下, 傾眠, 無気力, 発語減少, 動きの乏しさが主体. 実は最多の病型だが, スクリーニングツールを使わない場合はせん妄の約75%が見逃され, 特に低活動型に多い. 予後もより不良とする報告がある.\n'
        '・混合型 (mixed): 同一患者内で過活動と低活動が時間経過とともに入れ替わる.\n'
        '\n'
        '■評価: CAM-ICUとICDSCの使い分け\n'
        'まずRASSで覚醒・鎮静深度を確認する. RASS -4/-5 (昏睡) はせん妄評価の対象外, RASS -2/-3の患者はせん妄と誤判定されやすいとの報告があり解釈に注意する.\n'
        '・CAM-ICU: 感度75.5-81%, 特異度95.8-98%. 任意の一時点の状態を評価するツールで, 所見1 (急性発症/変動) + 所見2 (注意力欠如) + (所見3: 無秩序な思考, または所見4: 意識レベル変化) を満たせば陽性.\n'
        '・ICDSC: 感度74-80.1%, 特異度74.6-81.9%. 過去24時間の状態を8項目 (各0/1点) でチェックし, 4点以上でせん妄, 1-3点は亜症候性せん妄として経過観察する.\n'
        '両者の一致率はκ=0.55-0.80だが, 人工呼吸中や深い鎮静下では一致率が下がる. 評価は各勤務帯 (8-12時間毎) に1回以上, RASS評価とセットで定期的に行い, 看護師によるルーチン評価にはツールのトレーニングが必要である.\n'
        '\n'
        '■鑑別: どう見分けるか\n'
        '・認知症: 発症は月~年単位で緩徐, 意識レベルは清明で注意も比較的保たれる (進行例は障害されうる). せん妄の危険因子であり合併しうるため, 家族から「いつもと違うか, いつからか」を聴取する.\n'
        '・うつ病 (低活動型との鑑別): 発症は亜急性~慢性で, 症状は気分に一致した日内変動 (朝に増悪) を示し, 意識・注意は保たれやすい. せん妄は数時間~数日の急性発症で意識・注意障害が主体, 変動は不規則. 判断に迷う低活動例はまずせん妄として除外検索する.\n'
        '・非けいれん性てんかん重積 (NCSE): 遷延する意識障害, 眼球偏視や自動症, けいれん後に意識が戻らない例では必ず疑い, 持続または反復脳波で確認する.\n'
        '・脳血管障害/頭蓋内病変: 突然発症, 片麻痺・構音障害・瞳孔不同などの局所徴候を伴えば疑う. 頭部外傷後, 抗凝固薬使用中, 原因不明の遷延性意識障害では頭部CTの閾値を下げる.\n'
        '・薬剤性: 抗コリン薬, ベンゾジアゼピン系, ステロイド, オピオイド, H2遮断薬が代表. 開始・増量とせん妄発症の時間関係を確認し被疑薬の中止・変更を検討する.\n'
        '・離脱: アルコール, ベンゾジアゼピン系, ニコチンの急な中断. アルコール離脱は入室後48-96時間で振戦せん妄として顕在化しやすく, 頻脈・発汗・振戦・幻視を伴う. 飲酒歴の聴取が鍵.\n'
        '・代謝性: 低血糖, Na異常, 高アンモニア血症, 甲状腺機能異常, ビタミンB1欠乏によるWernicke脳症 (眼球運動障害・失調・意識障害の3徴, 揃わない例も多い) を確認する.\n'
        '・低酸素/高CO2血症, 感染/敗血症, 疼痛, 尿閉/便秘: いずれも見逃されやすい身体的原因で, 先に除外・治療すべきである.\n'
        '\n'
        '■最初に出す検査セットと身体所見\n'
        '血液ガス (酸素化, CO2, 乳酸, pH), 血糖, 電解質 (Na, K, Ca), 腎機能・肝機能, アンモニア, 甲状腺機能, CRP/プロカルシトニン, 尿検査・培養, 胸部X線を基本セットとする. 身体所見はバイタルサイン, 瞳孔, 局所神経徴候, 膀胱触診・エコー, 直腸診, 皮膚 (発汗・振戦), カテーテル刺入部の感染徴候を確認する. 原因不明の遷延性意識障害では頭部CTを, NCSEを疑えば脳波を追加する.\n'
        '\n'
        '■禁忌・やってはいけないこと\n'
        '・低活動型せん妄への抗精神病薬のルーチン投与は行わない. 興奮のない低活動型に鎮静系薬剤を追加すると意識障害を助長し, 誤嚥・転倒リスクを増す.\n'
        '・非定型抗精神病薬の予防的投与は行わないことを提案する (推奨度-2C). ハロペリドールの予防投与もせん妄発症を予防するとは言えない (0, C) とされ, ルーチンでの適応はない.\n'
        '・ベンゾジアゼピン系鎮静薬の漫然使用は避ける. BZD, オピオイドの使用はICUせん妄発症の治療関連危険因子として報告されており, できるだけ浅い鎮静を目指す.\n'
        '・原因検索を飛ばして対症的な鎮静薬投与のみで済ませない. せん妄は症状であり, 感染・代謝異常・NCSE・脳血管障害など背景疾患の検索と治療が優先される.\n'
        '・安易な身体抑制は避ける. 非薬物的対応 (見守り強化, 家族付き添い, ライン整理) を尽くした上での最終手段とし, 拘束自体が興奮やせん妄を助長しうる.\n'
        '\n'
        '■出典\n'
        '日本集中治療医学会 日本版・集中治療室における成人重症患者に対する痛み, 不穏, せん妄管理のための臨床ガイドライン (日集中医誌 J Jpn Soc Intensive Care Med Vol.21 No.5)',
  ),
  ColumnArticle(
    category: '集中治療・せん妄',
    title: 'アルコール離脱せん妄と, 通常のせん妄との違い',
    color: _cIcu,
    tags: const ['せん妄', 'アルコール離脱', '振戦せん妄', 'ベンゾジアゼピン'],
    body: '■時間経過: 振戦から振戦せん妄(DT)まで\n'
        '最終飲酒からの経過時間に応じて症状が段階的に進行する. アルコールは慢性的にGABA-A受容体機能を増強しグルタミン酸(NMDA)系を抑制しているが, 急な摂取中断でこの抑制が外れ, 中枢神経が過興奮状態に陥ることが病態の本質である.\n'
        '・6-12時間: 振戦, 発汗, 頻脈, 血圧上昇, 悪心, 不安などの軽症離脱症状\n'
        '・12-48時間: アルコール性幻覚症(意識は比較的清明なまま幻視・幻聴・幻触が出現)\n'
        '・24-48時間: 離脱痙攣(全般性強直間代発作, 単発〜群発)\n'
        '・48-96時間(多くは72時間前後がピーク): 振戦せん妄(delirium tremens, DT). 意識障害を伴う著明な見当識障害, 幻覚, 精神運動興奮に, 頻脈・高血圧・発熱・発汗などの自律神経症状が重なる. 頻度は離脱患者の3-5%程度とされるが, 無治療での死亡率は約15%と報告され, 早期認識と介入が予後を左右する.\n'
        '\n'
        '■通常のせん妄と治療の考え方が真逆になる理由\n'
        '通常のICUせん妄では, 過鎮静やベンゾジアゼピン(BZ)系薬の投与自体がせん妄発症のリスク因子として知られ, 日本版PADガイドラインもBZ系薬は避け, 症状が強い過活動型には抗精神病薬(ハロペリドールなど)を対症的に用いる方針を示す. 一方, アルコール離脱・DTでは病態そのものがGABA機能低下によるものであり, GABA-A受容体を賦活するBZ系薬が第一選択かつ治療の主役になる. 同ガイドラインもせん妄治療では"ベンゾジアゼピン薬を避ける"としつつ, 鎮静薬の適応として"不穏の管理, 強い不安, 痙攣, アルコール・ベンゾジアゼピン系薬離脱の治療"を明記し, プロトコル表でも鎮静薬選択は"ベンゾジアゼピン以外, アルコール依存ではベンゾ考慮"と例外規定している. 同じ"せん妄"でも, 背景にアルコール離脱があるかどうかで薬物選択の基本方針が反転する点を理解しておく.\n'
        '\n'
        '■鑑別が難しく, 薬歴が頼りである点\n'
        'ICUの過活動型せん妄は敗血症, 肝性脳症, 低酸素, 薬剤性(抗コリン薬, オピオイド), セロトニン症候群など原因が多岐にわたり, 自律神経症状(頻脈・発汗・振戦)は他の病態でも起こりうるため, 症状だけでのDT診断は難しい. 最も重要な手がかりは飲酒歴であり, 入院時に本人・家族から1日あたりの飲酒量, 最終飲酒時刻, 過去の離脱歴・DT歴・離脱痙攣歴を必ず聴取する. 評価にはCIWA-Ar(Clinical Institute Withdrawal Assessment for Alcohol, revised)などの離脱スコアを用い, 重症度に応じて薬物投与量を調整する(symptom-triggered投与). ただし人工呼吸中や鎮静下, せん妄で疎通が取れない患者ではCIWA-Arの問診項目が評価不能になるため, ICUでは頻脈・血圧・体温・発汗・興奮度などの他覚所見とRASSやCAM-ICU/ICDSCを併用した代替的評価が必要になる.\n'
        '\n'
        '■静注薬による対応\n'
        'BZ系薬の静注が治療の中心であり, 目標はRASS 0〜-1程度の安静・傾眠までの鎮静である.\n'
        '・ジアゼパム: 5-10mgを静注し, 効果不十分なら1-4時間ごとに追加する(front-loading). 活性代謝物により作用が長く症状再燃を抑えやすい半面, 肝代謝のため肝障害例では蓄積に注意する.\n'
        '・ロラゼパム: グルクロン酸抱合のみで代謝され肝障害の影響を受けにくく, 高齢者・肝硬変合併例で選択しやすい. 国内注射薬(ロラピタ)は成人4mgを2mg/分で静注し, 効果不十分なら追加投与し総量8mgまでを目安とする.\n'
        '・ミダゾラム: 経口・間欠静注のBZ系薬で制御できない重症DTでは持続静注に切り替える. 少量ずつ静注で滴定した後, 0.1mg/kg/h前後から持続投与を開始し鎮静深度を見ながら増減する. 高用量が必要になる場合は気道確保と人工呼吸管理を前提とする.\n'
        'いずれもCIWA-Arなどのスコアに基づくsymptom-triggered投与が, 固定スケジュール投与に比べ総投与量・治療期間を短縮できるとされる.\n'
        '\n'
        '■ビタミンB1(チアミン)をブドウ糖より先に投与する理由\n'
        '慢性飲酒者は摂食不良や吸収障害からチアミン欠乏をきたしていることが多い. チアミンはピルビン酸脱水素酵素やトランスケトラーゼなど糖代謝の補酵素であり, 欠乏状態でブドウ糖を先行投与すると糖代謝が急激に亢進してチアミンを消費し尽くし, Wernicke脳症(眼球運動障害, 運動失調, 意識障害)を誘発・顕在化させる. そのため補液・血糖補正に先立って, あるいは同時にチアミン100-500mgを静注してから糖負荷を行う. 未治療のWernicke脳症は不可逆性のKorsakoff症候群に移行しうるため, 疑わしければ躊躇せず投与する.\n'
        '\n'
        '■禁忌・注意\n'
        '・BZ系薬の反復・大量投与は呼吸抑制を招く. 特に高齢者, 肝障害, オピオイド併用例では過鎮静・低換気に注意し, 気道確保の準備と継続的な呼吸モニタを必須とする.\n'
        '・抗精神病薬(ハロペリドールなど)単独投与は痙攣閾値を下げるため, DTの第一選択にはしない. 幻覚・興奮が強くBZ系薬だけで制御困難な場合の併用にとどめる.\n'
        '・BZ系薬で症状が落ち着いた後の急激な減量・中止は離脱症状の再燃(反跳)を招く. 症状消失後は漸減する.\n'
        '・フルマゼニルによるBZ拮抗は離脱に伴う痙攣を誘発しうるため原則禁忌.\n'
        '・ブドウ糖を含む輸液をチアミン投与前に単独で急速投与しない.\n'
        '\n'
        '■非薬物療法\n'
        '・環境調整: 昼夜のメリハリをつけた照明, 静かな環境, 時計・カレンダーでの見当識付け, 眼鏡・補聴器の使用, 可能な範囲での家族面会.\n'
        '・電解質・Mg補正: 低K血症, 低Mg血症, 低P血症は慢性飲酒者に高頻度で, 低Mg血症は痙攣閾値をさらに下げるため積極的に補正する.\n'
        '・モニタリング: バイタルサイン(心拍数, 血圧, 体温)の頻回チェック, CIWA-ArやRASS/CAM-ICUによる反復評価, 痙攣・転倒・誤嚥対策を行い, 身体抑制は必要最小限にとどめ, 可能なら早期から離床など非薬理学的介入を優先する.\n'
        '\n'
        '■出典\n'
        '・日本集中治療医学会 日本版・集中治療室における成人重症患者に対する痛み・不穏・せん妄管理のための臨床ガイドライン (日集中医誌 Vol.21 No.5)',
  ),
  ColumnArticle(
    category: '集中治療・せん妄',
    title: '周術期の痙攣: 疑うべき原因と初期対応',
    color: _cIcu,
    tags: const ['緊急対応', '痙攣', 'てんかん重積', '局所麻酔薬中毒'],
    body: '■まず疑う原因(麻酔科特有のものを先頭に)\n'
        '・局所麻酔薬中毒(LAST): ブロックや硬膜外注入の直後~数分で発症. 耳鳴り, 口周囲/舌のしびれ, 金属味, 多弁が前駆し, 痙攣から心血管虚脱(徐脈, 心室性不整脈, 心停止)へ進む. 直前の手技歴と時間経過が鍵.\n'
        '・低酸素, 高CO2, 低血糖: SpO2, EtCO2, 血糖を即時確認. 血糖測定は他の治療より優先する.\n'
        '・電解質異常: 低Na血症(TUR症候群など灌流液吸収, 水中毒), 低Ca血症, 低Mg血症を採血で確認.\n'
        '・子癇: 妊娠20週以降~産褥で高血圧・蛋白尿・浮腫を伴う. 妊婦では必須の鑑別.\n'
        '・薬剤性: トラマドール, ペチジン(セロトニン症候群に注意), カルバペネム系(バルプロ酸併用で血中濃度低下し誘発), キノロン+NSAIDs, 高用量ペニシリン系, リドカイン中毒, フルマゼニルによるBZ拮抗, 抗精神病薬. 投与薬・内服中断歴を確認.\n'
        '・アルコール/BZ離脱, 抗てんかん薬の中断や絶食による血中濃度低下: 既往・内服歴の聴取が鍵.\n'
        '・頭蓋内病変: 出血, 梗塞, 腫瘍, 空気塞栓(座位手術, 中心静脈操作時), PRES. 局所神経徴候や意識回復遅延で疑い頭部CTへ.\n'
        '・悪性高熱, セロトニン症候群, 悪性症候群: 筋強直・高体温・頻脈を伴うが真の痙攣とは異なる. EtCO2急上昇と揮発性麻酔薬/スキサメトニウム曝露があれば悪性高熱を最優先.\n'
        '・心因性非てんかん発作(PNES): 眼瞼を強く閉じる, 非同期性の四肢運動, 発作中も受け答え可能, 発作後の意識清明化が早いことで鑑別.\n'
        '\n'
        '■初期対応の順序\n'
        '・ABCを確認し側臥位または頭部を横に向け誤嚥を防ぐ. 高流量酸素とSpO2モニタ, 用手気道確保. 無理な開口や口腔内への指・舌圧子挿入はしない.\n'
        '・静脈路確保と採血(血糖, 電解質, 血液ガス, Ca, Mg). 血糖は最優先で測定し, 低血糖なら50%ブドウ糖を先行投与.\n'
        '・心電図, 血圧, 体温をモニタしつつ次段階の薬剤を準備する.\n'
        '\n'
        '■静注薬 第1段階(ベンゾジアゼピン系)\n'
        '・ミダゾラム(ミダフレッサ): 0.15mg/kgを1mg/分以下で静注. 不十分なら持続0.1~0.4mg/kg/hへ.\n'
        '・ジアゼパム: 5~10mgを緩徐に静注(目安2mg/分以下), 不十分なら追加投与.\n'
        '・ロラゼパム(ロラピタ): 1バイアル1.0mL中2mg(2mg/mL). 添付文書上は同量の希釈液で1mg/mLに希釈し, 4mgを2mg/分で静注, 不十分なら総量8mgまで追加. 遮光・冷所(2~8℃)保存. 海外データではジアゼパムより消失率が高い.\n'
        '\n'
        '■静注薬 第2段階\n'
        '・ホスフェニトイン(ホストイン, 750mg/10mL): 22.5mg/kgを3mg/kg/分または150mg/分以下で静注. **この22.5mg/kgはホスフェニトイン実量で, フェニトイン当量(PE)表記では15mg PE/kgに相当する. 実量とPE換算は1.5倍異なるため必ず表記を確認する.** 注射用水・生食・5%ブドウ糖で希釈し, 気道確保・循環モニタ下で投与.\n'
        '・レベチラセタム: 1000~3000mgを2~5mg/kg/分で点滴. わが国ではてんかん重積への使用は保険適用外.\n'
        '・フェノバルビタール: 15~20mg/kgを100mg/分以下で静注. 呼吸抑制・血圧低下に注意.\n'
        '・ラコサミド: 400mg程度を15分で点滴する使用経験が集積しているが適応外であり, PR延長など循環動態を監視しながら投与.\n'
        '\n'
        '■第3段階(難治性重積)\n'
        '・痙攣が持続すれば気管挿管・人工呼吸管理下で全身麻酔薬による抑制に移行する.\n'
        '・プロポフォール: 1~2mg/kgを緩徐に静注後2~10mg/kg/hで持続し, 脳波でburst suppressionを目標に調整. 長時間高用量はPRISに注意.\n'
        '・ミダゾラム持続: 0.1~0.4mg/kg/hで持続し再燃時は増量. チオペンタール: 3~5mg/kgを緩徐に静注後3~5mg/kg/hで持続, 血圧低下に注意.\n'
        '・可能な限り脳波モニタを併用し, 痙攣停止後もNCSE(非けいれん性てんかん重積)への移行を見逃さない.\n'
        '\n'
        '■LASTのときの特別扱い\n'
        '・LASTが疑われたら通常のアルゴリズムより優先して脂肪乳剤投与を開始する.\n'
        '・20%脂肪乳剤を1.5mL/kg(理想体重)で急速ボーラス後, 0.25mL/kg/minで持続投与. 循環虚脱持続なら追加ボーラスと速度倍増(0.5mL/kg/min)を検討し, 安定後も10分以上継続. 累積上限は約10mL/kgが目安.\n'
        '・痙攣抑制はベンゾジアゼピン系を優先し, プロポフォールは循環抑制作用があるため不安定例で避ける.\n'
        '・アドレナリンは通常量を避け少量(1μg/kg未満)を目安に投与. バソプレシン, カルシウム拮抗薬, β遮断薬, リドカイン等の局所麻酔薬(クラスI抗不整脈薬)は使わない.\n'
        '・通常より蘇生が長時間に及ぶ想定で, 心肺バイパス(PCPS/ECMO)可能な施設への早期連絡を検討する.\n'
        '\n'
        '■禁忌・やってはいけないこと\n'
        '・フェニトイン/ホスフェニトインを高度徐脈, II度以上の房室ブロック, Adams-Stokes症候群に投与すること.\n'
        '・フェニトインを50mg/分を超える速度で投与すること(低血圧・心血管虚脱).\n'
        '・バルプロ酸内服中にカルバペネム系を併用すること(血中濃度低下で痙攣誘発).\n'
        '・痙攣中に無理な開口, 舌圧子やタオル・指を口腔内に挿入すること(歯牙損傷・誤嚥・受傷).\n'
        '・低血糖を除外せずに抗てんかん薬のみを投与すること.\n'
        '・ビタミンB1欠乏が疑われる患者にチアミン投与前にブドウ糖のみを先行投与すること.\n'
        '・LASTを疑う状況でリドカイン等を不整脈治療に用いること, 通常量のアドレナリンを投与すること.\n'
        '\n'
        '■非薬物療法\n'
        '・体位・気道: 側臥位または頭部を横に向け誤嚥を防ぐ(平坦位で十分). 用手気道確保, 経口/経鼻エアウェイ, 必要なら気管挿管.\n'
        '・酸素とモニタ: 高流量酸素とSpO2, EtCO2, 心電図, 血圧の継続モニタ.\n'
        '・身体抑制: 転落・外傷予防の最小限に留め, 四肢を強く押さえつけて完全に動きを止めようとしない(骨折・脱臼のリスク).\n'
        '・体温管理: 悪性高熱を疑う体温急上昇時は積極的な冷却(体表冷却, 冷却輸液).\n'
        '・原因検索: 頭部CT, 脳波モニタ(NCSE除外, burst suppression確認)を計画する.\n'
        '\n'
        '■出典\n'
        '・JRC蘇生ガイドライン2020 第7章 脳神経蘇生「ホスフェニトインの使用」「ジアゼパムとロラゼパム」の項.\n'
        '・LASTの脂肪乳剤療法等は指定ファイル未取得のため, 検証済み数値とASRA LASTチェックリストに準じる一般知識で補った.',
  ),
  ColumnArticle(
    category: '集中治療・せん妄',
    title: '非けいれん性てんかん重積(NCSE)と痙攣後の管理',
    color: _cIcu,
    tags: const ['てんかん重積', 'NCSE', '脳波', '神経集中治療'],
    body: '■NCSEを疑う場面\n'
        '・全身痙攣が治療で止まったにもかかわらず, 意識が期待される時間内に回復しない(目安: 治療開始後20-30分たっても意識清明化しない)\n'
        '・遷延する意識障害, 血糖・電解質・頭部画像・薬物の関与で説明のつかない昏睡\n'
        '・微細な眼球偏位や律動的眼振様運動, 眼瞼・口角・指先のミオクローヌス様のぴくつき\n'
        '・ICUや術後で鎮静を中止しても覚醒しない, 覚醒度が変動する, 反応性が乏しいまま推移する\n'
        '・痙攣性重積の治療歴があり, 痙攣は消失したのに神経学的所見が改善しない\n'
        '\n'
        '■診断\n'
        '・NCSEの確定診断には脳波が必須であり, 臨床所見のみでは診断できない\n'
        '・痙攣消失後30分たっても意識が回復しない場合は緊急脳波を手配する\n'
        '・発作性放電は間欠的にしか出現しないことが多く, 1回のスポット脳波では捉えきれないことがある. 持続脳波モニタリング(continuous EEG)は, ICUの昏睡患者や痙攣性重積治療後に意識が戻らない患者で発作の見逃しを防ぐために有用である\n'
        '・脳波がすぐに用意できない状況では, 診断的治療としてベンゾジアゼピン少量を静注し意識の変化を評価する方法もあるが, 過鎮静や気道防御反射低下を招きうるため慎重に行う\n'
        '\n'
        '■治療の考え方\n'
        '・NCSEの薬物治療は痙攣性てんかん重積に準じて段階的に進める\n'
        '・第1段階(ベンゾジアゼピン): ロラゼパム(ロラピタ, 2mg/mLを希釈し1mg/mLとして使用)を成人4mg, 2mg/分で静注. 効果不十分なら追加投与し総量8mgまで\n'
        '・第2段階(ベンゾジアゼピン抵抗性): 静注抗てんかん薬を選択する\n'
        '- ホスフェニトイン(ホストイン, 750mg/10mL): 添付文書の用量はホスフェニトイン実量で22.5mg/kgを3mg/kg/分または150mg/分以下で投与. PE(フェニトイン当量)表記では15mg PE/kgとなり実量と1.5倍異なるため, 海外文献のPE表記と取り違えないよう注意する\n'
        '- レベチラセタム: 1000-3000mgを2-5mg/kg/分で静注\n'
        '- フェノバルビタール: 15-20mg/kgを100mg/分以下で静注\n'
        '・NCSEでは痙攣による急激な全身状態悪化を伴わないことが多く, ミダゾラム持続やプロポフォールなど麻酔薬を用いた難治性重積治療にまで踏み込むかは, 脳波所見(周期性放電の形態, 背景活動の抑制度), 意識障害の程度, 基礎疾患, 循環呼吸の余力を総合して判断する\n'
        '・特に軽度の意識変容にとどまる焦点性NCSEでは, 深鎮静はかえって神経学的評価と脳波評価を困難にし合併症を増やすため, 抗てんかん薬の最適化を優先し麻酔薬導入は慎重に検討する\n'
        '\n'
        '■痙攣が止まった後の管理\n'
        '・再発予防の維持投与\n'
        '- レベチラセタム: 維持量として1回500-1500mgを1日2回, 静注または経口へ移行\n'
        '- ホスフェニトイン: 負荷後はフェニトイン換算で維持し, 血中濃度をみながら用量調整\n'
        '- フェノバルビタール: 負荷後は1-3mg/kg/日程度で維持し, 呼吸抑制と過鎮静に注意\n'
        '・原因検索: 血糖(低血糖・高血糖), 電解質(Na, Ca, Mgなど), 頭部画像(出血, 梗塞, 腫瘍, 脳炎所見の有無), 感染(髄膜炎, 脳炎, 敗血症), 薬剤性(抗菌薬, 向精神薬, 薬物離脱, アルコール離脱), 妊娠(子癇), 中毒(テオフィリン, 三環系抗うつ薬, イソニアジドなど)を系統的に確認する\n'
        '・気道と誤嚥: 意識障害が遷延する間は誤嚥リスクが高い. 気道防御反射を評価し, 誤嚥性肺炎を示唆する所見(嘔吐物の残存, 発熱, 酸素化悪化)をフォローする\n'
        '・横紋筋融解: CK, ミオグロビン, 腎機能を確認し, 高度なCK上昇があれば十分な輸液と尿量確保を行う\n'
        '・乳酸アシドーシス: 痙攣直後の乳酸上昇は生理的な範囲内で起こりうるが, 遷延する高乳酸血症は発作の継続や敗血症・循環不全など他病態の合併を疑う契機とする\n'
        '・高K血症: 横紋筋融解や腎機能障害を反映しうるため, 心電図とあわせて確認する\n'
        '・体温管理: 発熱があれば感染や中枢性発熱を鑑別しつつ解熱に努め, 高体温は二次性脳障害を助長するため積極的に冷却する. 予防的な低体温療法のルーチン適用は推奨されない\n'
        '・鎮静の考え方: 過鎮静は意識評価と脳波評価を妨げるため, 必要最小限の深度にとどめ, 可能な限り定期的に鎮静を中断して意識レベルと脳波所見を再評価する\n'
        '・抜管の判断とICU管理の閾値: 気道反射, 呼吸状態, 意識レベルの改善傾向を確認しながら抜管を検討する. NCSEが疑われる場合や持続脳波で発作波が残存する場合は抜管を急がずICU管理を継続する\n'
        '\n'
        '■禁忌・注意\n'
        '・意識が戻らないことを鎮静薬の残存効果と決めつけて漫然と経過観察を続けない. 鎮静を中止しても意識が回復しない場合はNCSEを積極的に疑い脳波を手配する\n'
        '・脳波を確認しないまま抗てんかん薬や麻酔薬を漫然と増量, 継続しない. 治療反応の評価には脳波所見の変化を用いる\n'
        '・ホスフェニトインは実量とPE換算量の取り違えに注意する(1.5倍の差). 急速投与は低血圧・不整脈を招くため投与速度を守る\n'
        '・過鎮静や過量の麻酔薬投与は循環抑制, 誤嚥, ICU滞在長期化のリスクを高めるため, 根拠のない深鎮静の継続は避ける\n'
        '\n'
        '■出典\n'
        '・日本蘇生協議会. JRC蘇生ガイドライン2020 第7章 脳神経蘇生(NR): てんかん重積に対する初期治療(ホスフェニトインの使用, ジアゼパムとロラゼパムに関するCQ)\n'
        '・「てんかん診療ガイドライン」作成委員会編. てんかん診療ガイドライン2018. 医学書院, 2018: てんかん重積状態の項',
  ),
  ColumnArticle(
    category: '集中治療・せん妄',
    title: '覚醒時興奮・覚醒時せん妄 (emergence delirium/agitation)',
    color: _cIcu,
    tags: const ['緊急対応', '小児麻酔', '覚醒時せん妄', 'PACU'],
    body: '■小児と成人の違い\n'
        '覚醒時興奮/覚醒時せん妄 (emergence delirium/agitation, ED) は特に就学前小児で頻度が高い. セボフルランやデスフルランなど覚醒の速い吸入麻酔薬で多いと報告され, プロポフォールTIVAでは相対的に少ない. 小児の評価にはPAEDスケール (5項目, 各0-4点, 合計20点満点) を用い, 概ね10点以上をED陽性の目安とする. 成人でも生じるが頻度は小児より低く, 疼痛・残存薬剤・代謝異常など器質的要因の比重が相対的に高い. 高齢, アルコール多飲歴, 術前不安, 長時間手術, 疼痛管理不良も危険因子になる.\n'
        '\n'
        '■発症のタイミングと自然経過\n'
        '麻酔覚醒直後, 抜管後数分から30分以内に発症することが多く, 多くは非薬理学的対応や経過観察のみで30分前後のうちに自然に消退する一過性の症状である. 30分を超えて遷延する場合や新規に悪化する場合は, 単純なEDと決めつけず器質的原因を再検索する.\n'
        '\n'
        '■まず除外すべき原因 (最重要. これを飛ばして鎮静しない)\n'
        '・低酸素, 高CO2, 上気道閉塞: パルスオキシメータ, 呼吸様式, 気道音を最優先で確認する.\n'
        '・疼痛: 興奮の原因として最も多い. 鎮静を追加する前に, まず鎮痛不足を疑う.\n'
        '・膀胱充満/尿閉, 体位による苦痛, 抑制帯や点滴ルートの不快感, 身体抑制そのもの.\n'
        '・低血糖, 低Na血症, 低体温/シバリング: 血糖, 電解質, 深部体温を確認する.\n'
        '・残存筋弛緩: TOF比を客観的に確認し, 拮抗不十分なら追加拮抗する.\n'
        '・残存麻酔薬/オピオイドによる意識混濁: 投与歴と時間経過を確認する.\n'
        '・中枢性抗コリン症候群 (抗コリン薬使用歴, 散瞳, 皮膚乾燥, 頻脈を伴う錯乱), セロトニン症候群 (発熱, 振戦, クローヌス, 反射亢進), 悪性症候群 (筋強剛, 高体温, CK上昇, 抗精神病薬使用歴).\n'
        '・脳血管障害, 非けいれん性てんかん重積 (NCSE): 局所神経症状や意識障害の遷延があれば想起し, 画像検査を検討する.\n'
        '\n'
        '■静注薬による対応 (用量つき)\n'
        '原因検索を並行させたうえで, 除外できない/苦痛が強い場合は以下を用いる.\n'
        '・鎮痛を先に: フェンタニル 0.5-1μg/kg を緩徐に静注. アセトアミノフェン 15mg/kg を点滴静注 (15分程度かけて).\n'
        '・鎮静: プロポフォール 0.5-1mg/kg を緩徐に静注, またはデクスメデトミジン 0.5μg/kg を10分かけて投与する.\n'
        '・小児のED予防に関するエビデンス: 麻酔終了前後のデクスメデトミジン単回投与 (0.3-0.5μg/kg程度), プロポフォールでの導入/維持併用, 適切なフェンタニルなどオピオイドによる鎮痛は, いずれもセボフルラン単独に比べEDの発生率を低下させるとメタ解析で報告されている.\n'
        '\n'
        '■禁忌・やってはいけないこと\n'
        '・原因検索をせずに鎮静薬だけを追加する: 低酸素や疼痛, 出血など重大な原因を鎮静で覆い隠してしまう.\n'
        '・パーキンソン病, レビー小体型認知症患者へのハロペリドール投与: 錐体外路症状の増悪や過敏反応, 悪性症候群のリスクがあり避ける.\n'
        '・ベンゾジアゼピン系の安易な追加: 特に高齢者では脱抑制やせん妄の遷延を招きやすく, 第一選択にしない.\n'
        '・物理的抑制を第一手段にすること: 自己抜管やライン抜去のリスクをむしろ高めうる. 原因検索と鎮痛, 環境調整を優先し, 抑制は切迫した危険がある場合の補助手段にとどめ, 継続の要否を短時間で再評価する.\n'
        '\n'
        '■非薬物療法\n'
        '・体位: 誤嚥や自己抜管を防ぎつつ, 気道を確保しやすく苦痛の少ない体位に調整する.\n'
        '・保温: シバリングは興奮様の動きに見えるため, 加温と深部体温の確認を行う.\n'
        '・モニタ: SpO2, 呼吸様式, バイタルサインの連続監視を継続する.\n'
        '・家族の同席: 小児では保護者を早期にPACUへ入れ, 声かけと抱っこで安心させる.\n'
        '・静かな環境: 照明を落とし, 音や不要な処置刺激を最小限にする.\n'
        '・抜管の判断: 覚醒が不安定なまま無理に抜管しない. 十分な自発呼吸, 咳嗽反射, 可能ならTOF回復を確認してから抜管する. 半覚醒状態での強い刺激下の抜管はEDを誘発しうるため避ける.\n'
        '\n'
        '■出典\n'
        '・Sikich N, Lerman J. Development and psychometric evaluation of the pediatric anesthesia emergence delirium scale. Anesthesiology 2004;100:1138-45.\n'
        '・Vlajkovic GP, Sindjelic RP. Emergence delirium in children: many questions, few answers. Anesth Analg 2007;104:84-91.\n'
        '・Dahmani S, et al. Pharmacological prevention of sevoflurane- and desflurane-related emergence agitation in children: a meta-analysis of published studies. Br J Anaesth 2010;104:216-23.\n'
        '・日本集中治療医学会 J-PADガイドライン作成委員会. 痛み・不穏・せん妄管理のための臨床ガイドライン. 日集中医誌 2014;21:539-579.',
  ),
];
